INSERT INTO tmp_vnj_status (kind, id, status) SELECT 'textbook', id, status FROM textbook WHERE id BETWEEN 3000001 AND 3999999;
INSERT INTO tmp_vnj_status (kind, id, status) SELECT 'lesson', id, status FROM lesson WHERE id BETWEEN 3000001 AND 3999999;
INSERT INTO tmp_vnj_status (kind, id, status) SELECT 'quiz', id, status FROM assessment_quiz WHERE id BETWEEN 3000001 AND 3999999;
INSERT INTO tmp_vnj_status (kind, id, active) SELECT 'question', id, is_active FROM assessment_question WHERE id BETWEEN 3000001 AND 3999999;
