INSERT INTO grammar_point (id, lesson_id, tag_id, pattern, meaning, example, note, order_index) VALUES
(3000001, 3000002, NULL, 'N1 は N2 です', 'N1 là N2\nN1 là N2', 'わたしは マイク・ミラーです。\nTôi là Mike Miller.', 'N1 は N2 です 。', 1),
(3000002, 3000002, NULL, 'N1 は N2 じゃ（では）ありません', 'N1 không phải là N2\nN1 không phải là N2', 'サントスさんは 学生じゃ ありません。\nAnh Santos không phải là sinh viên.', 'N1 は N2 じゃ ありません 。\nN1 は N2 では ありません 。', 2),
(3000003, 3000002, NULL, 'N1 は N2 ですか', 'Câu hỏi có／không\nCâu hỏi có／không', 'ミラーさんは アメリカ人ですか。\nAnh Miller có phải là người Mỹ không?', 'N1 は N2 です か 。\n… はい 、 N2 です。\n… いいえ 、 N2 じゃ ありません。', 3),
(3000004, 3000002, NULL, 'N は だれ／どなた ですか', 'Ai?\nAi?', 'あの方は どなたですか。\nVị kia là ai ạ?', 'N は だれ ですか。\nN は どなた ですか。\n… N です。', 4),
(3000005, 3000002, NULL, 'N は なんさい／おいくつ ですか', 'Hỏi tuổi\nHỏi tuổi', 'グプタさんは おいくつですか。\nAnh Gupta bao nhiêu tuổi?', 'N は なんさい ですか。\nN は おいくつ ですか。\n… số + さい です。', 5),
(3000006, 3000002, NULL, 'N も', 'N cũng\nN cũng', 'ミラーさんは 会社員です。グプタさんも 会社員です。\nAnh Miller là nhân viên công ty. Anh Gupta cũng là nhân viên công ty.', 'N1 は N2 です。 N3 も N2 です。', 6),
(3000007, 3000002, NULL, 'N1 の N2', 'N2 của／thuộc N1\nN2 của／thuộc N1', 'ミラーさんは IMCの 社員です。\nAnh Miller là nhân viên công ty IMC.', 'N1 の N2', 7),
(3000008, 3000002, NULL, '～さん', 'Cách gọi tên người khác\nCách gọi tên người khác', 'あの方は ミラーさんです。\nVị kia là anh Miller.', 'Tên + さん', 8),
(3000009, 3000013, NULL, 'これ／それ／あれ', 'Cái này, cái đó, cái kia\nCái này, cái đó, cái kia', 'これは 雑誌です。\nĐây là tạp chí.', 'これ／それ／あれ は N です。\nこれ／それ／あれ は 何ですか。', 1),
(3000010, 3000013, NULL, 'この／その／あの N', 'N này, N đó, N kia\nN này, N đó, N kia', 'この 本は わたしのです。\nQuyển sách này là của tôi.', 'この／その／あの N は ～です。', 2),
(3000011, 3000013, NULL, 'そうです／違います', 'Xác nhận hoặc phủ nhận\nXác nhận hoặc phủ nhận', 'それは 辞書ですか。\nĐó có phải là từ điển không?', '…はい、 そうです 。\n…いいえ、違います。\n…いいえ、 N です。', 3),
(3000012, 3000013, NULL, '～か、～か', 'Chọn một trong hai\nChọn một trong hai', 'これは シャープペンシルですか、ボールペンですか。\nĐây là bút chì bấm hay bút bi?', 'これは N1 です か 、 N2 です か 。\n… N1／N2 です。', 4),
(3000013, 3000013, NULL, 'N1 の N2', 'Nội dung hoặc loại đồ vật\nNội dung hoặc loại đồ vật', 'これは コンピューターの 本です。\nĐây là sách về máy tính.', 'N1 の N2\nそれは 何の N ですか。', 5),
(3000014, 3000013, NULL, 'だれの N', 'Đồ vật của ai?\nĐồ vật của ai?', 'これは わたしの 本です。\nĐây là sách của tôi.', 'これは người sở hữu の đồ vật です。\nこれは だれの N ですか。', 6),
(3000015, 3000013, NULL, 'N のです', 'Lược danh từ chỉ vật\nLược danh từ chỉ vật', 'この 辞書は あなたのですか。\nQuyển từ điển này là của bạn phải không?', '… người sở hữu の です。\n… người sở hữu の じゃ ありません。\nこの N は だれの ですか。', 7),
(3000016, 3000013, NULL, 'お～', 'Cách nói lịch sự\nCách nói lịch sự', 'これは おみやげです。\nĐây là quà biếu.', 'お + một số danh từ', 8),
(3000017, 3000013, NULL, 'そうですか', 'Vậy à, ra là vậy\nVậy à, ra là vậy', 'この 傘は あなたのですか。\nChiếc ô này là của bạn phải không?', 'そうですか 。', 9),
(3000018, 3000024, NULL, 'ここ／そこ／あそこ', 'Đây, đó, kia chỉ nơi chốn\nĐây, đó, kia chỉ nơi chốn', 'ここは 食堂です。\nĐây là nhà ăn.', 'ここ／そこ／あそこ は địa điểm です。\nこちら／そちら／あちら — phía này／phía đó／phía kia', 1),
(3000019, 3000024, NULL, 'N は địa điểm です', 'Cho biết vị trí của N\nCho biết vị trí của N', 'ここは わたしの うちです。\nĐây là nhà tôi.', 'N は địa điểm です。\nđịa điểm này は tên nơi です。', 2),
(3000020, 3000024, NULL, 'どこ／どちら', 'Hỏi nơi chốn\nHỏi nơi chốn', 'すみません、エレベーターは どちらですか。\nXin lỗi, thang máy ở phía nào ạ?', 'N は どこ ですか。\nN は どちら ですか。\n… địa điểm です。', 3),
(3000021, 3000024, NULL, 'お国／会社は どちらですか', 'Hỏi nước, cơ quan\nHỏi nước, cơ quan', 'お国は どちらですか。\nBạn đến từ nước nào?', 'お国は どちらですか。\n会社／学校は どこ／どちらですか。', 4),
(3000022, 3000024, NULL, 'どこの N', 'N của nước nào, hãng nào?\nN của nước nào, hãng nào?', 'これは どこの 時計ですか。\nĐây là đồng hồ của nước nào?', 'これは どこの sản phẩm ですか。\n… nước／công ty の sản phẩm です。', 5),
(3000023, 3000024, NULL, 'お～', 'Thể hiện sự tôn trọng\nThể hiện sự tôn trọng', 'お国は どちらですか。\nBạn đến từ nước nào?', 'お国は どちらですか。', 6),
(3000024, 3000024, NULL, '何階', 'Hỏi và nói số tầng\nHỏi và nói số tầng', '靴売り場は 何階ですか。\nQuầy giày ở tầng mấy?', 'N は 何階ですか。\n…số tầng 階です。\n…地下 + số tầng です。', 7),
(3000025, 3000024, NULL, 'いくら', 'Hỏi giá tiền\nHỏi giá tiền', 'この ネクタイは いくらですか。\nChiếc cà vạt này giá bao nhiêu?', 'この N は いくら ですか。\n…số tiền 円です。', 8),
(3000026, 3000035, NULL, '～時 ～分です', 'Giờ, phút và thứ\nGiờ, phút và thứ', '今 何時ですか。\nBây giờ là mấy giờ?', '今 số 時 số 分です。\nN は 今 何時ですか。\nN は 何曜日ですか。', 1),
(3000027, 3000035, NULL, 'Vます／Vません／Vました／Vませんでした', 'Bốn dạng động từ lịch sự\nBốn dạng động từ lịch sự', 'あした 休みます。\nNgày mai tôi sẽ nghỉ.', 'V ます 。／V ません 。\nV ました 。／V ませんでした 。', 2),
(3000028, 3000035, NULL, 'Vますか／Vましたか', 'Hỏi về hành động\nHỏi về hành động', 'あした 休みますか。\nNgày mai bạn có nghỉ không?', 'Vます か 。 …はい、Vます。／いいえ、Vません。\nVました か 。 …はい、Vました。／いいえ、Vませんでした。', 3),
(3000029, 3000035, NULL, 'Thời gian に V', 'Làm gì lúc nào\nLàm gì lúc nào', '毎朝 8時に 起きます。\nMỗi sáng tôi thức dậy lúc 8 giờ.', 'Thời điểm に V。\n何時に Vますか。', 4),
(3000030, 3000035, NULL, 'N1 から N2 まで', 'Từ N1 đến N2\nTừ N1 đến N2', '会議は 2時から 4時までです。\nCuộc họp diễn ra từ 2 giờ đến 4 giờ.', 'Thời gian bắt đầu から Thời gian kết thúc まで V。\nN は Thời gian から Thời gian まで です。', 5),
(3000031, 3000035, NULL, 'N1 と N2', 'N1 và N2\nN1 và N2', '美術館の 休みは 月曜日と 火曜日です。\nBảo tàng mỹ thuật nghỉ vào thứ hai và thứ ba.', 'N1 と N2', 6),
(3000032, 3000035, NULL, '～ね', 'Xác nhận, đồng cảm\nXác nhận, đồng cảm', '毎日 11時まで 働きます。\nNgày nào tôi cũng làm việc đến 11 giờ.', 'Câu ね 。\n大変ですね。', 7),
(3000033, 3000046, NULL, 'N へ 行きます／来ます／帰ります', 'Đi, đến, về\nĐi, đến, về', 'スーパーへ 行きます。\nTôi đi siêu thị.', 'Nơi đến へ 行きます。\nNơi đến へ 来ます。／帰ります。\nどこへ 行きますか。', 1),
(3000034, 3000046, NULL, 'どこ（へ）も V phủ định', 'Không đi đâu cả\nKhông đi đâu cả', 'あした どこも 行きません。\nNgày mai tôi không đi đâu cả.', 'どこも 行きません。\nどこへも 行きませんでした。', 2),
(3000035, 3000046, NULL, 'N で V', 'Đi bằng phương tiện gì\nĐi bằng phương tiện gì', '地下鉄で うちへ 帰ります。\nTôi về nhà bằng tàu điện ngầm.', 'Phương tiện で Nơi đến へ V。\n何で Nơi đến へ 行きますか。\n歩いて 行きます。', 3),
(3000036, 3000046, NULL, 'N と V', 'Đi cùng ai\nĐi cùng ai', '友達と 駅へ 行きます。\nTôi đi đến ga cùng bạn.', 'Người / con vật と V。\nだれと Vますか。\n一人で V。', 4),
(3000037, 3000046, NULL, '～年・～月・～日', 'Đọc năm, tháng, ngày\nĐọc năm, tháng, ngày', '誕生日は 7月20日です。\nSinh nhật của tôi là ngày 20 tháng 7.', 'Năm 年 → Tháng 月 → Ngày 日 → Thứ\n何月 何日ですか。\n誕生日は tháng / ngàyです。', 5),
(3000038, 3000046, NULL, 'いつ', 'Khi nào\nKhi nào', 'いつ うちへ 帰りますか。\nKhi nào bạn về nhà?', 'いつ Nơi đến へ Vますか。\n… Thời gian （に）Vます。\nN は いつ ですか。', 6),
(3000039, 3000046, NULL, '～よ', 'Báo thông tin cho người nghe\nBáo thông tin cho người nghe', 'この 電車は 甲子園へ 行きますか。\nTàu này có đi Koshien không?', 'Câu よ 。\n～です よ 。／～ます よ 。', 7),
(3000040, 3000046, NULL, 'そうですね', 'Đồng tình với người nói\nĐồng tình với người nói', 'あしたは 日曜日ですね。\nNgày mai là chủ nhật nhỉ.', '… そうですね 。\n… あ、 そうですね 。', 8),
(3000041, 3000057, NULL, 'N を Vます', 'Đối tượng của hành động\nĐối tượng của hành động', 'わたしは パンを 食べます。\nTôi ăn bánh mì.', 'Đối tượng を Vます。', 1),
(3000042, 3000057, NULL, 'N を します', 'Làm, chơi, tổ chức\nLàm, chơi, tổ chức', '日曜日 テニスを します。\nChủ nhật tôi chơi quần vợt.', 'Hoạt động を します 。', 2),
(3000043, 3000057, NULL, '何を しますか', 'Làm gì?\nLàm gì?', '土曜日 何を しますか。\nThứ bảy bạn làm gì?', '何を しますか。\n何を しましたか。\n何も Vません（でした）。', 3),
(3000044, 3000057, NULL, 'なん／なに', 'Hai cách đọc của 何\nHai cách đọc của 何', 'これは 何の 本ですか。\nĐây là sách về gì?', '何ですか／何の N\n何歳／何時\n何を Vますか', 4),
