(3000197, 3000042, 'GRAMMAR', 3000024, 'Ví dụ 22', '食堂は 地下1階です。', 'Nhà ăn ở tầng hầm thứ nhất.', 22),
(3000198, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 23', 'この ネクタイは いくらですか。', 'Chiếc cà vạt này giá bao nhiêu?', 23),
(3000199, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 24', '…1,500円です。', '…1.500 yên.', 24),
(3000200, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 25', 'この 手帳は いくらですか。', 'Cuốn sổ tay này giá bao nhiêu?', 25),
(3000201, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 26', '…600円です。', '…600 yên.', 26),
