(3000203, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 28', 'ここは 受付です。', 'Đây là quầy tiếp tân.', 28),
(3000204, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 29', 'ここは 事務所です。', 'Đây là văn phòng.', 29),
(3000205, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 30', 'ここは 会議室です。', 'Đây là phòng họp.', 30),
(3000206, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 31', 'ここは トイレです。', 'Đây là nhà vệ sinh.', 31),
(3000207, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 32', 'トイレは どこですか。', 'Nhà vệ sinh ở đâu?', 32),
(3000208, 3000042, 'GRAMMAR', 3000025, 'Ví dụ 33', '…あそこです。', '…Ở chỗ kia.', 33),
