(3001209, 3000279, 'GRAMMAR', 3000106, 'Ví dụ 18', 'この いすに 座って ください。', 'Mời bạn ngồi vào ghế này.', 18),
(3001210, 3000279, 'GRAMMAR', 3000106, 'Ví dụ 19', '教室に 入っても いいですか。', 'Tôi vào lớp học có được không?', 19),
(3001211, 3000279, 'GRAMMAR', 3000107, 'Ví dụ 20', '机の 上に 本を 置いて ください。', 'Hãy đặt sách lên bàn.', 20),
(3001212, 3000279, 'GRAMMAR', 3000107, 'Ví dụ 21', 'ここに 住所を 書いて ください。', 'Hãy ghi địa chỉ vào đây.', 21),
(3001213, 3000279, 'GRAMMAR', 3000107, 'Ví dụ 22', 'あそこに 車を 止めて ください。', 'Hãy đỗ xe ở đằng kia.', 22),
(3001214, 3000279, 'GRAMMAR', 3000107, 'Ví dụ 23', 'パソコンを 使っても いいですか。', 'Tôi dùng máy tính có được không?', 23),
