(3004589, 3001007, 'GRAMMAR', NULL, '付きます', 'ポケットがつきます。', 'Có túi (được gắn túi).', 10),
(3004590, 3001007, 'GRAMMAR', NULL, '外れます', 'ボタンがはずれます。', 'Cúc áo bị tuột.', 11),
(3004591, 3001007, 'GRAMMAR', NULL, '止まります', 'エレベーターが止まります。', 'Thang máy dừng lại.', 12),
(3004592, 3001007, 'GRAMMAR', NULL, 'まちがえます', '漢字をまちがえました。', 'Tôi đã viết sai chữ kanji.', 13),
(3004593, 3001007, 'GRAMMAR', NULL, '落とします', '財布を落としました。', 'Tôi đã làm rơi ví.', 14),
(3004594, 3001007, 'GRAMMAR', NULL, '掛かります', 'ドアにかぎが掛かります。', 'Cửa bị khóa.', 15),
(3004595, 3001007, 'GRAMMAR', NULL, 'ふきます', 'テーブルをふきます。', 'Lau bàn.', 16),
(3004596, 3001007, 'GRAMMAR', NULL, '取り替えます', '電池を取り替えます。', 'Thay pin.', 17),
(3004597, 3001007, 'GRAMMAR', NULL, '片づけます', '部屋を片づけます。', 'Dọn dẹp phòng.', 18),
(3004598, 3001007, 'GRAMMAR', NULL, '[お]皿', 'お皿を洗いました。', 'Tôi đã rửa đĩa.', 19),
(3004599, 3001007, 'GRAMMAR', NULL, '[お]ちゃわん', 'おちゃわんを使います。', 'Dùng cái bát.', 20),
(3004600, 3001007, 'GRAMMAR', NULL, 'コップ', 'コップに水を入れます。', 'Tôi rót nước vào cốc.', 21),
(3004601, 3001007, 'GRAMMAR', NULL, 'ガラス', '窓はガラスできれいです。', 'Cửa sổ làm bằng thủy tinh nên đẹp.', 22),
(3004602, 3001007, 'GRAMMAR', NULL, '袋', '買い物の荷物を袋に入れます。', 'Tôi cho đồ mua vào túi.', 23),
(3004603, 3001007, 'GRAMMAR', NULL, '書類', 'この書類に名前を書いてください。', 'Vui lòng viết tên vào giấy tờ này.', 24),
(3004604, 3001007, 'GRAMMAR', NULL, '枝', '木の枝に鳥がいます。', 'Có con chim trên cành cây.', 25),
(3004605, 3001007, 'GRAMMAR', NULL, '駅員', '駅員に切符を見せます。', 'Tôi đưa vé cho nhân viên nhà ga xem.', 26),
(3004606, 3001007, 'GRAMMAR', NULL, '交番', '交番は道の角にあります。', 'Bốt cảnh sát ở góc đường.', 27),
(3004607, 3001007, 'GRAMMAR', NULL, 'スピーチ', '明日クラスでスピーチをします。', 'Ngày mai tôi sẽ phát biểu trong lớp.', 28),
(3004608, 3001007, 'GRAMMAR', NULL, '返事', '先生に返事を送りました。', 'Tôi đã gửi trả lời cho cô giáo.', 29),
(3004609, 3001007, 'GRAMMAR', NULL, 'お先にどうぞ。', '電車でお先にどうぞ。', 'Xin mời anh/chị đi trước trên tàu.', 30),
(3004610, 3001007, 'GRAMMAR', NULL, '源氏物語', '源氏物語は有名な古い物語です。', 'Genji Monogatari là một truyện cổ nổi tiếng.', 31),
(3004611, 3001007, 'GRAMMAR', NULL, '今の電車', '今の電車で財布を忘れました。', 'Tôi đã để quên ví trên đoàn tàu vừa rồi.', 32),
(3004612, 3001007, 'GRAMMAR', NULL, '忘れ物', '忘れ物がないか、もう一度確認してください。', 'Hãy kiểm tra lại xem có vật để quên không.', 33),
(3004613, 3001007, 'GRAMMAR', NULL, 'このくらい', 'このくらいなら大丈夫です。', 'Cỡ này thì được thôi.', 34),
(3004614, 3001007, 'GRAMMAR', NULL, '～側', '駅の左側に出口があります。', 'Có lối ra ở phía trái của ga.', 35),
(3004615, 3001007, 'GRAMMAR', NULL, 'ポケット', 'シャツのポケットに鍵を入れた。', 'Tôi đã bỏ chìa khóa vào túi áo.', 36),
(3004616, 3001007, 'GRAMMAR', NULL, '～辺', 'この辺にコンビニがありますか。', 'Ở quanh đây có cửa hàng tiện lợi không?', 37),
(3004617, 3001007, 'GRAMMAR', NULL, '覚えていません。', 'すみません、覚えていません。', 'Xin lỗi, tôi không nhớ.', 38),
(3004618, 3001007, 'GRAMMAR', NULL, '網棚', '網棚に荷物を置かないでください。', 'Xin đừng đặt hành lý lên giá lưới (trên tàu).', 39),
(3004619, 3001007, 'GRAMMAR', NULL, '確か', '確か、会議は３時からでした。', 'Nếu không nhầm thì cuộc họp bắt đầu từ 3 giờ.', 40),
(3004620, 3001007, 'GRAMMAR', NULL, '新宿', '新宿で友だちと会います。', 'Tôi sẽ gặp bạn ở Shinjuku.', 41),
(3002350, 3000559, 'GRAMMAR', 3000191, 'Ví dụ 1', 'ドアが 閉まって います。', 'Cửa đóng rồi.', 1),
(3002351, 3000559, 'GRAMMAR', 3000191, 'Ví dụ 2', 'この いすは 壊れて います。', 'Chiếc ghế này bị hỏng.', 2),
(3002352, 3000559, 'GRAMMAR', 3000191, 'Ví dụ 3', '教室の 電気が 消えて いました。', 'Lúc đó đèn trong lớp đã tắt.', 3),
(3002353, 3000559, 'GRAMMAR', 3000192, 'Ví dụ 4', '漢字の 宿題は もう やって しまいました。', 'Tôi đã làm xong bài tập chữ Hán rồi.', 4),
(3002354, 3000559, 'GRAMMAR', 3000192, 'Ví dụ 5', '今 これを コピーして しまいます。', 'Bây giờ tôi sẽ photocopy cho xong chỗ này.', 5),
(3002355, 3000559, 'GRAMMAR', 3000192, 'Ví dụ 6', 'この 本は もう 読みました。', 'Tôi đã đọc cuốn sách này rồi.', 6),
(3002356, 3000559, 'GRAMMAR', 3000192, 'Ví dụ 7', '…もう 読んで しまったんですか。', '…Bạn đã đọc xong rồi cơ à?', 7),
(3002357, 3000559, 'GRAMMAR', 3000193, 'Ví dụ 8', 'パスポートを なくして しまいました。', 'Tôi lỡ làm mất hộ chiếu rồi.', 8),
(3002358, 3000559, 'GRAMMAR', 3000193, 'Ví dụ 9', 'パソコンが 故障して しまいました。', 'Máy tính của tôi hỏng mất rồi.', 9),
(3002359, 3000559, 'GRAMMAR', 3000194, 'Ví dụ 10', '交番に 行きます。', 'Tôi đi đến đồn cảnh sát.', 10),
(3002360, 3000559, 'GRAMMAR', 3000194, 'Ví dụ 11', '友達が うちに 来ました。', 'Bạn tôi đã đến nhà tôi.', 11),
(3002361, 3000559, 'GRAMMAR', 3000194, 'Ví dụ 12', '国に 帰ります。', 'Tôi sẽ về nước.', 12),
(3002362, 3000559, 'GRAMMAR', 3000195, 'Ví dụ 13', '財布を 落として しまいました。', 'Tôi làm rơi ví mất rồi.', 13),
(3002363, 3000559, 'GRAMMAR', 3000195, 'Ví dụ 14', '…それは 大変ですね。', '…Thế thì gay quá nhỉ.', 14),
(3002364, 3000559, 'GRAMMAR', 3000195, 'Ví dụ 15', 'きのう 本を 買いました。その 本は とても おもしろいです。', 'Hôm qua tôi mua một cuốn sách. Cuốn sách đó rất hay.', 15),
(3002365, 3000559, 'GRAMMAR', 3000195, 'Ví dụ 16', 'タクシーで 行って ください。', 'Bạn hãy đi bằng taxi nhé.', 16),
(3002366, 3000559, 'GRAMMAR', 3000195, 'Ví dụ 17', '…はい、そう します。', '…Vâng, tôi sẽ làm như vậy.', 17),
(3002367, 3000559, 'GRAMMAR', 3000196, 'Ví dụ 18', 'あ、かばんが ありました。', 'A, tìm thấy cặp rồi!', 18),
(3002368, 3000559, 'GRAMMAR', 3000196, 'Ví dụ 19', 'かぎが ありません。', 'Tôi không thấy chìa khóa đâu.', 19),
(3002369, 3000559, 'GRAMMAR', 3000196, 'Ví dụ 20', '…あ、ありました。ポケットの 中です。', '…A, đây rồi! Ở trong túi.', 20),
(3002370, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 21', 'どこかで 財布を なくして しまいました。', 'Tôi làm mất ví ở đâu đó rồi.', 21),
(3002371, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 22', 'どこかに 電話が ありますか。', 'Có chỗ nào có điện thoại không?', 22),
(3002372, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 23', '窓が 開いて います。', 'Cửa sổ đang mở.', 23),
(3002373, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 24', '電気が ついて います。', 'Đèn đang bật.', 24),
(3002374, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 25', 'お皿が 割れて います。', 'Đĩa bị vỡ.', 25),
(3002375, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 26', 'ボタンが 外れて います。', 'Cúc áo bị tuột.', 26),
(3002376, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 27', 'シャツが 汚れて います。', 'Áo sơ mi bị bẩn.', 27),
(3002377, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 28', '袋が 破れて います。', 'Túi bị rách.', 28),
(3002378, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 29', '車が 止まって います。', 'Xe đang đỗ.', 29),
(3002379, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 30', '木の 枝が 折れて います。', 'Cành cây bị gãy.', 30),
(3002380, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 31', 'エアコンが ついて いますから、消して ください。', 'Điều hòa đang bật, bạn tắt giúp nhé.', 31),
(3002381, 3000559, 'GRAMMAR', 3000197, 'Ví dụ 32', 'テーブルが 汚れて いますから、ふいて ください。', 'Bàn bị bẩn nên bạn lau giúp nhé.', 32),
(3002382, 3000560, 'READING', NULL, 'Luyện tập', 'Bài có 9 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002383, 3000561, 'LISTENING', NULL, '忘れ物を して しまったんです – Tôi để quên đồ mất rồi', 'イー：すみません。今の 電車に 忘れ物を して しまったんですが……。\n駅員：何を 忘れたんですか。\nイー：青い かばんです。このくらいの……。\nイー：外側に 大きい ポケットが 付いて います。\n駅員：どの 辺に 置きましたか。\nイー：よく 覚えて いません。\nイー：でも、網棚の 上に 置きました。\n駅員：中に 何が 入って いますか。\nイー：えーと、確か 本と 傘が 入って います。\n駅員：じゃ、調べますから、ちょっと 待って いて ください。\n駅員：ありましたよ。\nイー：ああ、よかった。\n駅員：今 新宿駅に ありますが、どう しますか。\nイー：すぐ 取りに 行きます。\n駅員：じゃあ、新宿駅の 事務所に 行って ください。\nイー：はい。どうも ありがとう ございました。', 'Xin lỗi, tôi lỡ để quên đồ trên chuyến tàu vừa rồi…\nChị để quên gì ạ?\nMột chiếc cặp màu xanh dương. Cỡ chừng này…\nBên ngoài có một ngăn túi lớn.\nChị đã để ở chỗ nào ạ?\nTôi không nhớ rõ lắm.\nNhưng tôi đã để trên giá hành lý.\nBên trong có những gì ạ?\nỪm, nếu tôi nhớ không nhầm thì có sách và ô.\nĐể tôi kiểm tra, chị vui lòng chờ một chút ạ.\nTìm thấy rồi, chị ạ.\nÔi, may quá!\nHiện chiếc cặp đang ở ga Shinjuku, chị muốn làm thế nào ạ?\nTôi sẽ đến lấy ngay.\nVậy chị đến văn phòng ga Shinjuku nhé.\nVâng. Cảm ơn anh rất nhiều.', 1),
(3002384, 3000561, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002385, 3000561, 'LISTENING', NULL, 'Nhắc người khác về trạng thái của đồ vật', 'A：あのう……。\nB：はい。\nA：かばんが 開いて いますよ。\nB：えっ。あ、どうも すみません。\nA：あのう……。\nB：はい。\nA：ボタンが 外れて いますよ。\nB：えっ。あ、どうも すみません。\nA：あのう……。\nB：はい。\nA：クリーニングの 紙が 付いて いますよ。\nB：えっ。あ、どうも すみません。', 'Xin lỗi…\nVâng?\nCặp đang mở đấy.\nƠ! À, cảm ơn bạn nhiều.\nXin lỗi…\nVâng?\nCúc áo bị tuột rồi đấy.\nƠ! À, cảm ơn bạn nhiều.\nXin lỗi…\nVâng?\nNhãn giấy của tiệm giặt vẫn còn dính trên áo đấy.\nƠ! À, cảm ơn bạn nhiều.', 3),
(3002386, 3000561, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002387, 3000561, 'LISTENING', NULL, 'Xin phép dùng đồ và đề nghị dùng cái khác', 'A：すみません。\nA：この パンチ、 使っても いいですか。\nB：あ、その パンチは 壊れて いますから、こちらのを 使って ください。\nA：すみません。\nA：すみません。\nA：この 袋を 使っても いいですか。\nB：あ、その 袋は 汚れて いますから、こちらのを 使って ください。\nA：すみません。\nA：すみません。\nA：この 封筒を 使っても いいですか。\nB：あ、その 封筒は 破れて いますから、こちらのを 使って ください。\nA：すみません。', 'Xin lỗi.\nMình dùng cái đục lỗ giấy này được không?\nÀ, cái đục lỗ giấy đó hỏng rồi, bạn dùng cái này nhé.\nCảm ơn bạn.\nXin lỗi.\nMình dùng cái túi này được không?\nÀ, cái túi đó bẩn rồi, bạn dùng cái này nhé.\nCảm ơn bạn.\nXin lỗi.\nMình dùng phong bì này được không?\nÀ, phong bì đó rách rồi, bạn dùng cái này nhé.\nCảm ơn bạn.', 5),
(3002388, 3000561, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002389, 3000561, 'LISTENING', NULL, 'Kể sự cố và nhắc việc cần làm ngay', 'A：どう したんですか。\nB：どこかで 財布を 落として しまったんです。\nA：それは 大変ですね。\nA：すぐ 交番に 行かないと。\nB：ええ。\nA：どう したんですか。\nB：どこかで カードを なくして しまったんです。\nA：それは 大変ですね。\nA：すぐ カード会社に 連絡しないと。\nB：ええ。\nA：どう したんですか。\nB：電車に 書類を 忘れて しまったんです。\nA：それは 大変ですね。\nA：すぐ 駅員に 言わないと。\nB：ええ。', 'Có chuyện gì vậy?\nMình đánh rơi ví ở đâu đó mất rồi.\nThế thì gay go quá nhỉ.\nPhải đến đồn cảnh sát ngay thôi.\nVâng.\nCó chuyện gì vậy?\nMình làm mất thẻ ở đâu đó rồi.\nThế thì gay go quá nhỉ.\nPhải liên hệ công ty phát hành thẻ ngay thôi.\nVâng.\nCó chuyện gì vậy?\nMình để quên tài liệu trên tàu mất rồi.\nThế thì gay go quá nhỉ.\nPhải báo cho nhân viên nhà ga ngay thôi.\nVâng.', 7),
(3002390, 3000561, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002391, 3000562, 'READING', NULL, 'Luyện tập', 'Bài có 10 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002392, 3000563, 'READING', NULL, 'Văn mẫu 文型', '窓が 閉まって います。\n電車に 傘を 忘れて しまいました。', 'Cửa sổ đang đóng.\nTôi để quên ô trên tàu mất rồi.', 1),
(3002393, 3000563, 'READING', NULL, 'Ví dụ 例文', '会議室の かぎが 掛かって いますね。\n…じゃ、渡辺さんに 言って、開けて もらいましょう。\nこの パソコン、使っても いいですか。\n…それは 故障して いますから、あちらのを 使って ください。\nシュミットさんが 持って 来た ワインは どこですか。\n…みんなで 飲んで しまいました。\nいっしょに 帰りませんか。\n…すみません。この メールを 書いて しまいますから、お先に どうぞ。\n約束の 時間に 間に 合いましたか。\n…いいえ、遅れて しまいました。道を まちがえたんです。\nどうしたんですか。\n…タクシーに 荷物を 忘れて しまったんです。', 'Cửa phòng họp đang khóa nhỉ.\n…Vậy nhờ chị Watanabe mở cửa giúp nhé.\nTôi dùng máy tính này được không?\n…Máy đó đang hỏng, bạn dùng máy đằng kia nhé.\nRượu vang ông Schmidt mang đến đâu rồi?\n…Mọi người uống hết rồi.\nChúng ta cùng về nhé?\n…Xin lỗi, tôi cần viết cho xong email này. Bạn cứ về trước nhé.\nBạn có đến kịp giờ hẹn không?\n…Không, tôi đến muộn mất rồi. Tôi đi nhầm đường.\nCó chuyện gì vậy?\n…Tôi để quên hành lý trên taxi mất rồi.', 2),
(3002394, 3000563, 'READING', NULL, 'Luyện tập A – 1', 'ドアが 開いて います。\n車が 止まって います。\nガラスが 割れて います。', 'Cửa đang mở.\nXe đang đỗ.\nKính bị vỡ.', 3),
(3002395, 3000563, 'READING', NULL, 'Luyện tập A – 2', 'この 袋は 破れて います。\nその コピー機は 故障して います。\nあの 木は 折れて います。', 'Cái túi này bị rách.\nMáy phô tô đó bị hỏng.\nCái cây kia bị gãy.', 4),
(3002396, 3000563, 'READING', NULL, 'Luyện tập A – 3', '「源氏物語」は 全部 読んで しまいました。\n漢字の 宿題は もう やって しまいました。\nレポートは 今晩 書いて しまいます。\n資料は 金曜日までに 作って しまいます。', 'Tôi đã đọc hết Truyện Genji.\nTôi làm xong bài tập chữ Hán rồi.\nTối nay tôi sẽ viết xong báo cáo.\nTôi sẽ làm xong tài liệu chậm nhất vào thứ sáu.', 5),
(3002397, 3000563, 'READING', NULL, 'Luyện tập A – 4', '財布を 落として しまいました。\n電話番号を まちがえて しまいました。\nパソコンが 壊れて しまいました。', 'Tôi làm rơi ví mất rồi.\nTôi nhầm số điện thoại mất rồi.\nMáy tính hỏng mất rồi.', 6),
(3002398, 3000564, 'READING', NULL, 'Luyện tập', 'Bài có 4 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002399, 3000565, 'READING', NULL, 'wright', 'わたしは先週友達のうちへ遊びに行きました。\n大阪駅で来た電車にすぐ乗りました。\n友達はうちの近くの駅で待っていると言いました。\nでも、わたしが乗った電車はその駅を通り過ぎてしまいました。\nそれは特急電車でした。\n京都までどこにも止まりませんでした。\nわたしはもう一度大阪へ行く電車に乗りました。\n友達は駅で2時間待っていてくれました。\nうれしかったです。', 'Tuần trước, tôi đến nhà bạn chơi.\nỞ ga Osaka, tôi lên ngay chuyến tàu vừa đến.\nBạn tôi nói sẽ đợi ở ga gần nhà mình.\nNhưng chuyến tàu tôi lên lại chạy qua luôn ga ấy mất rồi.\nĐó là tàu tốc hành đặc biệt.\nTàu không dừng ở đâu cho đến tận Kyoto.\nTôi lại lên một chuyến tàu đi Osaka.\nBạn tôi đã đợi tôi ở ga suốt hai tiếng.\nTôi rất vui.', 1),
(3002400, 3000565, 'READING', NULL, 'john-arrival', '先週日本人のうちにホームステイしました。\n晩ごはんのあとで、お母さんが「おふろ、どうぞ」と言ってくれました。\n日本のおふろは初めてでした。\nバスタブは大きくて、お湯がたくさん入っていました。\nお湯は少し熱かったです。', 'Tuần trước, tôi ở homestay tại nhà một gia đình người Nhật.\nSau bữa tối, người mẹ trong gia đình nói với tôi: “Mời cháu đi tắm.”\nĐó là lần đầu tôi tắm kiểu Nhật.\nBồn tắm rộng và có rất nhiều nước nóng.\nNước hơi nóng một chút.', 2),
(3002401, 3000565, 'READING', NULL, 'john-bath', 'お湯の中でゆっくり体を洗いました。\nそして汚れたお湯を全部捨てました。\n次にお父さんがふろ場へ行きました。\n「あれ？お湯が入っていない。」\nお父さんはびっくりしました。\n日本のおふろは、バスタブの外で体を洗ってから、中に入るんですね。\n知りませんでした。', 'Tôi thong thả tắm rửa trong nước nóng.\nSau đó, tôi xả hết nước bẩn trong bồn.\nTiếp theo, người bố trong gia đình đi vào phòng tắm.\n“Ủa? Không có nước nóng trong bồn.”\nNgười bố rất ngạc nhiên.\nHóa ra khi tắm kiểu Nhật, phải tắm rửa bên ngoài bồn rồi mới vào ngâm mình trong bồn nhỉ.\nTrước đó tôi không biết điều này.', 3),
(3002402, 3000565, 'READING', NULL, 'miguel-offer', 'わたしは水曜日の夜、日本人の友達のうちで、スペイン語を教えています。\n先週友達が「来月スペインへ旅行に行きますから、もっと勉強したいです」と言いました。\nわたしは「じゃ、土曜日も来ましょうか」と聞きました。\n彼は「土曜日はいいです」と言いました。', 'Tối thứ tư hằng tuần, tôi dạy tiếng Tây Ban Nha tại nhà một người bạn Nhật.\nTuần trước, bạn tôi nói: “Tháng sau tôi đi du lịch Tây Ban Nha nên muốn học thêm.”\nTôi hỏi: “Vậy thứ bảy tôi cũng đến nhé?”\nAnh ấy nói: “Thứ bảy thì thôi, không cần đâu.”', 4),
(3002403, 3000565, 'READING', NULL, 'miguel-visit', '土曜日に友達のうちへ行きました。\n家の電気は消えていました。\nベルを押しましたが、返事がありませんでした。', 'Thứ bảy, tôi đến nhà bạn.\nĐèn trong nhà đều tắt.\nTôi bấm chuông nhưng không có ai trả lời.', 5),
(3002404, 3000565, 'READING', NULL, 'miguel-call', '日曜日、彼に電話しました。\n「きのう、あなたのうちへ行きましたよ。」\n「『土曜日はいいです』と言ったでしょう？」\n「……。」', 'Chủ nhật, tôi gọi điện cho anh ấy.\n“Hôm qua tôi có đến nhà anh đấy.”\n“Tôi đã nói là ‘Thứ bảy thì không cần’ rồi mà?”\n“……”', 6),
(3002405, 3000566, 'READING', NULL, 'Luyện tập', 'Bài có 8 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002406, 3000567, 'LISTENING', NULL, '1. Nhận ra điều cần sửa友達が いずみさんに 注意しました。いずみさんは どうしますか。Bạn nhắc nhở Izumi. Chị ấy sẽ làm gì?', 'A：あれ？ いずみ、車の電気が ついているよ。\nB：え？ あ、ほんとう。ついて いるね。\nB：ちょっと待って いて。\nA：いずみ、かばんが開いて いるよ。\nB：え? ほんとう。\nA：危ないね。\nA：気を つけて。\nB：うん。\nA：いずみ、シャツの ボタンが外れているよ。\nB：あら、そう?\nB：ありがとう。\nA：ああ、おいしかった。\nA：ごちそうさま。\nB：いずみ、アイスクリームが付いているよ。\nA：え? どこ?\nB：口の横。\nB：違う。右。そう。そう。\nA：ありがとう。', 'Ơ, Izumi, đèn xe vẫn sáng kìa.\nHả? Đúng là đèn vẫn bật.\nChờ một chút nhé.\nIzumi, cặp đang mở kìa.\nHả? Đúng thật.\nNguy hiểm nhỉ.\nCẩn thận nhé.\nỪ.\nIzumi, cúc áo sơ mi tuột ra kìa.\nƠ, thế à?\nCảm ơn.\nÀ, ngon quá.\nCảm ơn đã mời nhé.\nIzumi, dính kem kìa.\nHả? Ở đâu?\nBên cạnh miệng ấy.\nKhông phải, bên phải, đúng rồi, đúng rồi.\nCảm ơn.', 1),
(3002407, 3000567, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002408, 3000567, 'LISTENING', NULL, '2. Đồ vật có vấn đề gì?店の 人は どうして「こちらのを どうぞ」と 言いましたか。Vì sao nhân viên cửa hàng nói: “Mời quý khách lấy cái này”?', 'A：すみません。\nA：これ、ください。\nB：はい、ありがとうございます。\nB：お皿が5枚ですね。\nA：はい。\nB：あ、これは……。\nA：あれ、割れて いますね。\nB：すみません。\nB：こちらに新しいのが ありますから、こちらのを どうぞ。\nA：すみません。\nA：大きい袋を ください。\nB：はい。\nB：これで いいですか。\nA：ありがとう。\nA：あれ? これは破れて いますよ。\nB：え? どうもすみません。\nB：こちらのを どうぞ。\nB：いらっしゃいませ。\nA：てんぷら定食、ください。\nB：かしこまりました。\nB：お待たせました。\nA：あれ? すみません。\nA：この はし、折れて いるんですけど。\nB：あ、どうもすみません。\nB：こちらのを どうぞ。\nA：すみません。\nA：きのう こちらで買った セーターなんですが。\nB：はい。\nA：ここ、汚れて いるんです。\nB：あ。そうですね。どうもすみません。\nB：こちらに同じものが ありますから、こちらのを どうぞ。\nA：ありがとう。', 'Xin lỗi.\nCho tôi cái này.\nVâng, cảm ơn.\n5 cái đĩa phải không ạ?\nVâng.\nÀ, cái này…\nCái đó bị nứt nhỉ.\nXin lỗi.\nCó đĩa mới ở đây, mời anh lấy chiếc này.\nXin lỗi.\nCho tôi một chiếc túi lớn.\nVâng.\nCái này được không?\nCảm ơn.\nƠ, cái này bị rách rồi.\nƠ? Thành thật xin lỗi.\nMời quý khách lấy cái này.\nXin chào quý khách.\nCho tôi suất cơm tempura.\nVâng ạ.\nXin lỗi đã để quý khách chờ.\nỦa… Xin lỗi.\nChiếc đũa này bị gãy rồi…\nÀ, thành thật xin lỗi.\nMời quý khách dùng đôi này.\nXin lỗi.\nChiếc áo len này tôi mua ở đây hôm qua.\nVâng.\nChỗ này bị bẩn.\nÀ, đúng rồi. Thành thật xin lỗi quý khách.\nCó chiếc cùng loại ở đây, mời anh lấy chiếc này.\nCảm ơn.', 3),
(3002409, 3000567, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002410, 3000567, 'LISTENING', NULL, '3. Hoàn thành nhanh đến mức nào?タワポンさんは すごい人です。どうして すごい人ですか。Thawaphon làm được những việc gì đáng nể?', 'A：タワポンさん、昼ごはんを食べませんか。\nB：もう食べました。\nA：え? いつ食べたんですか。\nB：休み時間に食べて しまいました。\nA：え？10分の休み時間に？\nA：速いですね。\nA：タワポンさん、スピーチは もう覚えましたか。\nB：はい、もう覚えました。\nA：え？ ほんとうに覚えて しまったんですか。きのうは まだ でしたね。\nB：はい、けさ学校へ来るとき、1時間公園で練習しました。\nB：全部覚えましたよ。\nA：へえ、すごいですね。\nA：タワポンさん、夏休みの宿題は もうやって しまいましたか。\nB：ええ。富士山に ついてレポートを書きました。\nA：え?先週聞いたとき、まだでしたね 。\nB：ええ 。\nB：この土曜日と日曜日、頑張りました。\nA：タワポンさん、その本、どうですか。\nA：おもしろいですか。\nB：ええ、おもしろかったですよ。\nA：え?\nA：もう読んで しまったんですか。\nB：ええ。\nB：読んで しまいましたよ。\nB：よかったら、どうぞ。\nB：1週間あったら、読めますよ。\nA：タワポンさんが1週間だったら、\nA：わたしは3週間かかりますよ。', 'Thawaphon, bạn đi ăn trưa cùng tôi không?\nTôi đã ăn rồi.\nHả? Bạn ăn lúc nào vậy?\nTôi ăn xong trong giờ giải lao rồi.\nHả? Trong giờ giải lao 10 phút ấy à?\nNhanh nhỉ.\nThawaphon, đã thuộc bài phát biểu chưa?\nVâng, thuộc rồi.\nHả? Thuộc hết thật rồi à? Hôm qua vẫn chưa mà.\nVâng, sáng nay trên đường đến trường, tôi luyện tập 1 tiếng ở công viên.\nTôi thuộc hết rồi đấy.\nỒ, giỏi thật đấy.\nThawaphon, bạn đã làm xong hết bài tập hè chưa?\nVâng, tôi đã viết báo cáo về núi Phú Sĩ.\nHả? Tuần trước tôi hỏi thì bạn vẫn chưa xong mà.\nVâng.\nTôi đã cố làm trong thứ bảy và chủ nhật vừa rồi.\nBạn Thawaphon, quyển sách đó như thế nào?\nThú vị không?\nVâng, thú vị đấy.\nHả?\nBạn đã đọc xong rồi à?\nVâng.\nTôi đã đọc xong rồi đấy.\nNếu muốn thì bạn đọc đi.\nCó 1 tuần là đọc xong đấy.\nThawaphon mà mất một tuần thì…\ntôi phải mất ba tuần đấy.', 5),
(3002411, 3000567, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002412, 3000567, 'LISTENING', NULL, '4. Miller sẽ làm gì tiếp? ミラーさんは これから どうしますか。 Miller sẽ làm gì tiếp theo?', 'A：ミラーさん、もう12時ですね。\nA：食事に行きませんか。\nB：すみません。\nB：このレポート、書いてしまいたいですから、\nB：お先に どうぞ。\nA：何分ぐらいかかりますか 。\nB：10分ぐらいです。\nA：10分ですか。\nA：おなかも すいたし、レストランも込むし、……。\nA：じゃ。\nA：あ、12時50分ですね。\nA：もう会社に戻らないと。1時から会議なんです。\nB：お先に どうぞ。\nB：わたしは この コーヒーを飲んで しまいますから。\nA：じゃ。\nA：もう5時ですね。\nA：帰りませんか。\nB：すみません。あしたから出張なんです。\nB：この資料を作って しまわないと、……。\nA：大変ですね。\nB：ええ。ですから、お先にどうぞ。\nA：わかりました。じゃ。', 'Anh Miller, đã 12 giờ rồi nhỉ.\nCùng đi dùng bữa không?\nXin lỗi.\nTôi muốn viết xong báo cáo này đã.\nXin mời bạn đi trước ạ.\nMất khoảng mấy phút?\nKhoảng 10 phút.\n10 phút phải không?\nTôi cũng đói rồi, mà nhà hàng sẽ đông nữa…\nVậy thì…\nÀ, 12 giờ 50 phút rồi nhỉ.\nTôi phải quay lại công ty thôi. Tôi có cuộc họp lúc 1 giờ.\nBạn cứ về trước đi.\nTôi uống hết ly cà phê này đã.\nVậy tôi xin phép về trước.\nĐã 5 giờ rồi nhỉ.\nVề cùng chứ?\nXin lỗi, từ ngày mai tôi sẽ đi công tác.\nTôi phải làm cho xong tài liệu này.\nVất vả nhỉ.\nVâng, vậy, bạn về trước đi.\nTôi hiểu rồi. Chào bạn nhé.', 7),
(3002413, 3000567, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002414, 3000567, 'LISTENING', NULL, '5. Sự cố và cách giải quyếtエドさんは よく小さい失敗を します。何を しましたか。どうしますか。Ed gặp những sự cố nhỏ nào và sẽ xử lý thế nào?', 'A：エドさん、どうしたんですか。\nB：本を なくして しまったんです。\nA：またですか 。\nA：今度は何の本?\nB：先週図書館から借りた本です。\nB：それを読んで、レポートを書いたんですが。\nA：これですか。\nB：あ、それです 。\nB：先生、どこに ありましたか 。\nA：わたしの机の上に ありましたよ。\nA：レポートと いっしょに。\nB：ああ、よかった。\nB：すぐ返しに行きます。\nA：こんにちは。\nB：こんにちは。\nB：エドさん、きょうは新しいかばんだね。\nA：え?新しいかばん?\nA：わあ、まちがえて しまった。\nA：これ、ミゲルさんのだ。\nB：ミゲルさん、探していると思うよ。\nB：すぐ電話しないと。\nA：うん、わかった。\nA：いらっしゃいませ。\nB：すみません。この ケータイなんですけど、\nB：けさ、駅で落として しまいました。\nB：それから全然動きません。\nA：ちょっと見せて ください。\nA：ああ、これは もう使えませんね。\nB：ええー？残念！ でも、しかたがありませんね。\nB：新しいのを お願いします。\nA：はい、かしこまりました。', 'Ed, em làm sao thế?\nEm làm mất quyển sách rồi ạ.\nLại mất nữa hả?\nLần này là quyển sách gì?\nQuyển sách em mượn ở thư viện tuần trước ạ.\nEm đọc sách đó rồi viết báo cáo.\nCái này phải không?\nÀ, đúng quyển đó ạ.\nThưa cô, nó nằm ở đâu vậy?\nỞ trên bàn cô đấy.\nCùng với báo cáo.\nÀ, may quá.\nEm sẽ đi trả lại ngay.\nXin chào.\nXin chào.\nEd, hôm nay bạn có cặp mới nhỉ.\nHả? Cặp mới à?\nÔi, tôi cầm nhầm rồi.\nCái này là của Miguel.\nTôi nghĩ bạn Miguel đang tìm đấy.\nPhải gọi điện ngay thôi.\nỪ, tôi biết rồi.\nXin chào quý khách.\nXin lỗi, chiếc điện thoại này…\nSáng nay tôi làm rơi nó ở ga.\nTừ đó nó không hoạt động nữa.\nCho tôi xem một chút.\nÀ, máy này không dùng được nữa rồi.\nỦa, tiếc quá. Nhưng mà không còn cách nào khác.\nCho tôi cái mới nhé.\nVâng ạ.', 9),
(3002415, 3000567, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 10),
(3002416, 3000568, 'READING', NULL, 'Luyện tập', 'Bài có 45 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002417, 3000569, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo tình huống của bạn. Câu mẫu của Nguyễn Minh chỉ là gợi ý.\nはい、ついて います。\n日本語の 本が 入って います。\nわたしが 使って いる 銀行は 閉まって います。\n謝って、同じ 本を 買って 返します。', NULL, 1),
(3002418, 3000569, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo tình huống của bạn. Câu mẫu của Nguyễn Minh chỉ là gợi ý.\n今 パソコンが ついて いますか。\nかばんに 何が 入って いますか。\n土曜日 銀行は 開いて いますか。\n借りた 本を なくして しまったら、どうしますか。', NULL, 2),
(3002419, 3000569, 'READING', NULL, '2. Nghe: đúng hay sai', 'Nghe hội thoại và câu ★, chọn ○ nếu đúng hoặc × nếu sai.\n男：寒いですね。\n女：あ、窓が 少し 開いて いますよ。\n男：あ、そうですね。閉めましょうか。\n女：はい、お願いします。\n★：部屋の 窓は 開いて いました。\n女：すみません。この コピー機、使っても いいですか。\n男：ここの コピー機、今 壊れて いるんです。すみませんが、２階のを 使って ください。\n女：はい、わかりました。\n★：２階の コピー機は 今 故障して います。\n男：いらっしゃいませ。\n女：あのう、きのう こちらに 傘を 忘れて しまったんですが。\n男：傘ですか。\n女：ええ、赤い 傘です。あの テーブルの 横に 置いたんですが。\n男：ああ、ちょっと 待って ください。……これですか。\n女：あ、それです。どうも すみません。\n★：女の 人は テーブルの 横に 傘を 忘れました。\n男：今 ちょっと いい？ 来週の 会議に ついて 話したいんだけど。\n女：あ、これを コピーして しまいたいんだけど。すぐ 終わるから。\n男：わかった。じゃ、終わったら、言って。\n★：女の 人は もう コピーを して しまいました。', NULL, 3),
(3002420, 3000569, 'READING', NULL, '8. Đọc bản tin và chọn tranh', 'Đọc bản tin động đất rồi chọn tranh phù hợp với toàn bộ nội dung.\nけさ ５時４６分に 大きい 地震が ありました。今 わたしは 駅の 前に います。駅の 建物は 壊れて、壁の 時計は 止まって います。時計の 針は ５時４６分を 指して います。電車は 動いて いません。\n古い ビルが 駅前の 広い 道に 倒れて います。倒れて いない ビルも 窓の ガラスが 割れて います。ビルの 中を 見ると、いろいろな 物が 壊れて います。危ないですから、入る ことが できません。\n駅の 西の 方では 今も うちが 燃えて います。', NULL, 4),
(3002421, 3000569, 'READING', NULL, '9. Tập làm phóng viên', 'Dựa vào tranh, đóng vai phóng viên để miêu tả hiện trường bằng tự động từ + て います. Có nhiều cách trả lời.\n今、わたしは うちの 中に います。窓の ガラスが 割れて います。\n食器棚が 倒れて います。お皿や コップが 割れて います。いすも 倒れて います。\n床が 汚れて います。台所の 火は まだ ついて います。', NULL, 5),
(3002422, 3000570, 'READING', NULL, 'Luyện tập', 'Bài có 22 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002423, 3000571, 'READING', NULL, '3. Tả trạng thái trong phòng', '〜が 〜ています Nhìn tranh, hoàn thành hai câu đã cho phần đầu, rồi viết thêm các câu tả trạng thái những vật khác trong phòng.\nカーテンが 汚れています。\nいすが 壊れています。\n皿が 割れています。\n木の 枝が 折れています。\n本が 破れています。', NULL, 1),
(3002424, 3000571, 'READING', NULL, '5. Viết hội thoại theo tranh', '〜は 〜ています Viết hội thoại: người nam xin chiếc túi, chiếc cốc hoặc xin ngồi ghế, người nữ nhắc trạng thái của vật đó.\nこの コップを もらっても いいですか。\nあ、その コップは 割れています。\nこの いすに 座っても いいですか。\nあ、その いすは 壊れています。', NULL, 2),
(3002425, 3000571, 'READING', NULL, '6. Kể việc đáng tiếc theo tranh', '〜てしまいました（残念） Nhìn tranh, viết các việc đáng tiếc với 〜てしまいました theo ví dụ. Có thể chọn nhiều cách diễn đạt phù hợp với từng đồ vật hoặc từ gợi ý.\nかばんを 忘れてしまいました。\n電話番号を 忘れてしまいました。\n約束を 忘れてしまいました。\nかぎを なくしてしまいました。\nお金を 落としてしまいました。', NULL, 3),
(3002426, 3000571, 'READING', NULL, '7. Kể một việc đáng tiếc của bạn', '〜てしまいました（残念） Viết một việc đáng tiếc bạn đã gặp: xảy ra lúc nào, ở đâu, chuyện gì và sau đó thế nào.\nきのう、大学へ 行く とき、うちに 宿題を 忘れてしまいました。\nそれで、うちへ 帰りました。', NULL, 4),
(3002427, 3000571, 'READING', NULL, '10. Hoàn thành câu với てしまう', '「〜てしまいます」の 整理（残念・完了） Dùng 〜てしまいました hoặc 〜てしまいます để viết tiếp câu cho phù hợp.\nもう、帰れますか。\nいいえ。宿題を やってしまいますから、お先に どうぞ。', NULL, 5),
(3002428, 3000572, 'READING', NULL, 'Luyện tập', 'Bài có 34 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002429, 3000573, 'READING', NULL, 'Danh sách kanji', '書 (THƯ) — viết; sách — しょ\n類 (LOẠI) — loại, chủng loại; giống nhau — るい\n駅 (DỊCH) — ga — えき\n員 (VIÊN) — thành viên — いん\n交 (GIAO) — giao nhau; qua lại, giao lưu; trộn lẫn — こう\n番 (PHIÊN) — số thứ tự; lượt, phiên; canh gác — ばん\n返 (PHẢN) — trả lại; đáp lại — へん\n事 (SỰ) — việc, vấn đề — じ\n開 (KHAI) — mở — あ\n閉 (BẾ) — đóng — し\n消 (TIÊU) — tắt, dập tắt; biến mất; tiêu hao — き\n止 (CHỈ) — dừng; đỗ — と\n掛 (QUẢI) — treo, mắc; tốn (thời gian, tiền) — か\n壊 (HOẠI) — phá hủy, làm hỏng; vỡ, hỏng — こわ\n割 (CÁT) — chia, cắt; tỷ lệ — わ\n折 (CHIẾT) — gấp, bẻ, gãy; dịp — お\n破 (PHÁ) — phá vỡ, xé rách; đánh bại — やぶ\n汚 (Ô) — bẩn, làm bẩn; ô nhục — よご\n付 (PHÓ) — gắn vào, kèm theo; giao, trao — つ\n外 (NGOẠI) — bên ngoài; khác; nước ngoài — はず\n落 (LẠC) — rơi; làm rơi — お\n取 (THỦ) — lấy, cầm; giành được — と\n替 (THẾ) — thay, thay thế; đổi — か\n片 (PHIẾN) — mảnh; một bên, một phía — かた\n皿 (MÃNH) — đĩa — さら\n袋 (ĐẠI) — túi, bao — ふくろ\n枝 (CHI) — cành, nhánh — えだ\n先 (TIÊN) — trước — さき\n源 (NGUYÊN) — nguồn, khởi nguồn — げん\n氏 (THỊ) — họ, dòng họ; ông, ngài (sau tên) — し\n物 (VẬT) — đồ vật — もの\n語 (NGỮ) — ngôn ngữ; kể chuyện — がたり', NULL, 1),
(3002430, 3000574, 'READING', NULL, '使い方 – Câu ví dụ', '新しい住所と電話番号を教えてください。\nデパートでもらった紙の袋は捨てません。また使います。\n大切なカードを落としてしまいました。\n車が汚れています。彼女が乗る前に、洗わなければなりません。\nきのう覚えた漢字をもう忘れてしまいました。\nこのホテルは山側の部屋が海側の部屋より高いです。\nエレベーターが止まりました。ドアが開きません。\n子どもが家に帰りました。上着のボタンが外れているし、ごみがたくさん付いているし、ズボンは汚れています。', NULL, 1),
(3002431, 3000574, 'READING', NULL, '読み物 – Bài đọc · 忘れ物市', '電車や駅の忘れ物、落とし物で多い物は傘です。傘の忘れ物は1年で30万本あります。服、財布、カメラ、ケータイなども多いです。持ち主がわからない傘は6か月後に、デパートなどで安く売ります。1本10円ぐらいですから、人気があります。\nどうして傘が多いと思いますか。\n①傘の忘れ物は取りに来る人が少ないから。\n②忘れた人は忘れたことを忘れているから。\n③それは忘れ物ではないから。（ごみを捨てた。）\nあなたはどう思いますか。', NULL, 2),
(3002432, 3000575, 'READING', NULL, 'Luyện tập', 'Bài có 12 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002433, 3000576, 'READING', NULL, 'Luyện tập', 'Bài có 6 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002434, 3000577, 'READING', NULL, 'Danh sách từ vựng', 'Bài có 43 từ vựng.', NULL, 1),
(3004621, 3001008, 'GRAMMAR', NULL, 'はります', 'ポスターを壁にはります。', 'Dán poster lên tường.', 1),
(3004622, 3001008, 'GRAMMAR', NULL, '掛けます', '絵を壁に掛けます。', 'Treo tranh lên tường.', 2),
(3004623, 3001008, 'GRAMMAR', NULL, '飾ります', '部屋に花を飾ります。', 'Trang trí phòng bằng hoa.', 3),
(3004624, 3001008, 'GRAMMAR', NULL, '並べます', '本を机の上に並べます。', 'Xếp sách trên bàn.', 4),
(3004625, 3001008, 'GRAMMAR', NULL, '植えます', '庭に木を植えます。', 'Trồng cây vào vườn.', 5),
(3004626, 3001008, 'GRAMMAR', NULL, '戻します', '本を元の場所に戻します。', 'Đưa sách về chỗ cũ.', 6),
(3004627, 3001008, 'GRAMMAR', NULL, 'まとめます', 'レポートをまとめます。', 'Tổng hợp báo cáo.', 7),
(3004628, 3001008, 'GRAMMAR', NULL, 'しまいます', '洋服をタンスにしまいます。', 'Cất quần áo vào tủ.', 8),
(3004629, 3001008, 'GRAMMAR', NULL, '決めます', '明日の予定を決めます。', 'Quyết định kế hoạch ngày mai.', 9),
(3004630, 3001008, 'GRAMMAR', NULL, '予習します', '授業の前に予習します。', 'Chuẩn bị bài trước giờ học.', 10),
(3004631, 3001008, 'GRAMMAR', NULL, '復習します', '今日の授業の後で復習します。', 'Hôm nay sẽ ôn bài sau giờ học.', 11),
(3004632, 3001008, 'GRAMMAR', NULL, 'そのままにします', 'そのままにします。', 'Để nguyên như vậy.', 12),
(3004633, 3001008, 'GRAMMAR', NULL, '授業', '明日、授業があります。', 'Ngày mai có giờ học.', 13),
(3004634, 3001008, 'GRAMMAR', NULL, '講義', '大学で面白い講義を聞きました。', 'Tôi đã nghe một bài giảng thú vị ở trường đại học.', 14),
(3004635, 3001008, 'GRAMMAR', NULL, 'ミーティング', '午後にミーティングがあります。', 'Chiều có cuộc họp.', 15),
(3004636, 3001008, 'GRAMMAR', NULL, '予定', '旅行の予定を立てます。', 'Lên kế hoạch cho chuyến đi.', 16),
(3004637, 3001008, 'GRAMMAR', NULL, 'お知らせ', '掲示板にお知らせがあります。', 'Có thông báo trên bảng thông báo.', 17),
(3004638, 3001008, 'GRAMMAR', NULL, 'ガイドブック', '旅行にガイドブックを持って行きます。', 'Mang sách hướng dẫn du lịch khi đi du lịch.', 18),
(3004639, 3001008, 'GRAMMAR', NULL, 'カレンダー', 'カレンダーに予定を書きます。', 'Viết kế hoạch lên lịch.', 19),
(3004640, 3001008, 'GRAMMAR', NULL, 'ポスター', '壁にポスターが貼ってあります。', 'Có poster dán trên tường.', 20),
(3004641, 3001008, 'GRAMMAR', NULL, '予定表', '明日の予定表を見せてください。', 'Hãy cho tôi xem lịch làm việc ngày mai.', 21),
(3004642, 3001008, 'GRAMMAR', NULL, 'ごみ箱', 'ごみ箱にゴミを捨ててください。', 'Hãy bỏ rác vào thùng rác.', 22),
(3004643, 3001008, 'GRAMMAR', NULL, '人形', 'その人形は古いです。', 'Con búp bê đó cũ.', 23),
(3004644, 3001008, 'GRAMMAR', NULL, '花瓶', '花瓶に花を入れます。', 'Tôi bỏ hoa vào lọ hoa.', 24),
(3004645, 3001008, 'GRAMMAR', NULL, '鏡', '鏡で髪をチェックします。', 'Tôi kiểm tra tóc bằng gương.', 25),
(3004646, 3001008, 'GRAMMAR', NULL, '引き出し', '引き出しにペンがあります。', 'Có bút trong ngăn kéo.', 26),
(3004647, 3001008, 'GRAMMAR', NULL, '玄関', '玄関で靴を脱いでください。', 'Hãy cởi giày ở cửa vào.', 27),
(3004648, 3001008, 'GRAMMAR', NULL, '廊下', '廊下を静かに歩いてください。', 'Hãy đi nhẹ nhàng trên hành lang.', 28),
(3004649, 3001008, 'GRAMMAR', NULL, '壁', '壁に絵を掛けました。', 'Tôi treo tranh lên bức tường.', 29),
(3004650, 3001008, 'GRAMMAR', NULL, '池', '公園の池で魚を見ました。', 'Tôi đã nhìn thấy cá ở cái ao trong công viên.', 30),
(3004651, 3001008, 'GRAMMAR', NULL, '元の所', '元の所に戻してください。', 'Hãy trả về chỗ ban đầu.', 31),
(3004652, 3001008, 'GRAMMAR', NULL, '周り', '公園の周りを散歩します。', 'Đi dạo xung quanh công viên.', 32),
(3004653, 3001008, 'GRAMMAR', NULL, '真ん中', '部屋の真ん中にテーブルがあります。', 'Ở giữa phòng có một cái bàn.', 33),
(3004654, 3001008, 'GRAMMAR', NULL, '隅', '部屋の隅に猫がいます。', 'Có con mèo ở góc phòng.', 34),
(3004655, 3001008, 'GRAMMAR', NULL, 'まだ', 'まだ終わっていません。', 'Vẫn chưa xong.', 35),
(3004656, 3001008, 'GRAMMAR', NULL, 'リュック', '彼は大きなリュックを背負っている。', 'Anh ấy đang đeo một chiếc ba lô lớn.', 36),
(3004657, 3001008, 'GRAMMAR', NULL, '非常袋', '非常袋を玄関に置いておきます。', 'Tôi để túi khẩn cấp ở cửa chính.', 37),
(3004658, 3001008, 'GRAMMAR', NULL, '非常時', '非常時は落ち着いて避難してください。', 'Khi khẩn cấp hãy bình tĩnh và sơ tán.', 38),
(3004659, 3001008, 'GRAMMAR', NULL, '生活します', '都会で生活します。', 'Sống ở thành phố.', 39),
(3004660, 3001008, 'GRAMMAR', NULL, '懐中電灯', '懐中電灯をバッグに入れてください。', 'Hãy để đèn pin vào túi.', 40),
(3004661, 3001008, 'GRAMMAR', NULL, '～とか、～とか', 'りんごとか、みかんとかを買いました。', 'Tôi đã mua như táo, như quýt (ví dụ các loại trái cây).', 41),
(3002435, 3000579, 'GRAMMAR', 3000198, 'Ví dụ 1', '机の 上に メモが 置いて あります。', 'Trên bàn có để sẵn một mẩu ghi chú.', 1),
(3002436, 3000579, 'GRAMMAR', 3000198, 'Ví dụ 2', '今月の 予定は カレンダーに 書いて あります。', 'Kế hoạch tháng này đã được ghi trên lịch.', 2),
(3002437, 3000579, 'GRAMMAR', 3000198, 'Ví dụ 3', 'メモは どこですか。', 'Mẩu ghi chú ở đâu?', 3),
(3002438, 3000579, 'GRAMMAR', 3000198, 'Ví dụ 4', '…机の 上に 置いて あります。', '…Có để sẵn trên bàn.', 4),
(3002439, 3000579, 'GRAMMAR', 3000199, 'Ví dụ 5', '旅行の まえに、切符を 買って おきます。', 'Trước chuyến du lịch, tôi sẽ mua vé sẵn.', 5),
(3002440, 3000579, 'GRAMMAR', 3000199, 'Ví dụ 6', 'パーティーの まえに、何を して おいたら いいですか。', 'Trước bữa tiệc, tôi nên làm gì để chuẩn bị?', 6),
(3002441, 3000579, 'GRAMMAR', 3000199, 'Ví dụ 7', '…飲み物を 買って おいて ください。', '…Bạn hãy mua sẵn đồ uống nhé.', 7),
(3002442, 3000579, 'GRAMMAR', 3000200, 'Ví dụ 8', 'はさみを 使ったら、元の 所に 戻して おいて ください。', 'Dùng kéo xong, bạn cất lại chỗ cũ nhé.', 8),
(3002443, 3000579, 'GRAMMAR', 3000200, 'Ví dụ 9', '本を 読んだら、棚に 戻して おきます。', 'Đọc sách xong, tôi sẽ đặt lại trên kệ.', 9),
(3002444, 3000579, 'GRAMMAR', 3000201, 'Ví dụ 10', 'ドアを 閉めても いいですか。', 'Tôi đóng cửa được không?', 10),
(3002445, 3000579, 'GRAMMAR', 3000201, 'Ví dụ 11', '…暑いですから、開けて おいて ください。', '…Vì nóng nên bạn cứ để cửa mở nhé.', 11),
(3002446, 3000579, 'GRAMMAR', 3000201, 'Ví dụ 12', 'あした 会議が ありますから、いすは このままに して おいて ください。', 'Mai có cuộc họp nên bạn cứ để ghế nguyên như thế này nhé.', 12),
(3002447, 3000579, 'GRAMMAR', 3000202, 'Ví dụ 13', 'まだ 雨が 降って います。', 'Trời vẫn đang mưa.', 13),
(3002448, 3000579, 'GRAMMAR', 3000202, 'Ví dụ 14', '子どもは まだ 寝て います。', 'Bé vẫn đang ngủ.', 14),
(3002449, 3000579, 'GRAMMAR', 3000203, 'Ví dụ 15', 'どんな スポーツを して いますか。', 'Bạn chơi những môn thể thao nào?', 15),
(3002450, 3000579, 'GRAMMAR', 3000203, 'Ví dụ 16', '…テニスとか 水泳とか。', '…Như quần vợt, bơi lội.', 16),
(3002451, 3000579, 'GRAMMAR', 3000203, 'Ví dụ 17', '休みの 日は 公園とか 美術館とかへ 行きます。', 'Ngày nghỉ tôi đi những nơi như công viên, bảo tàng mỹ thuật.', 17),
(3002452, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 18', '庭にも 花が あります。', 'Trong vườn cũng có hoa.', 18),
(3002453, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 19', 'うちでも 日本語を 勉強します。', 'Ở nhà tôi cũng học tiếng Nhật.', 19),
(3002454, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 20', 'ほかにも いろいろ あります。', 'Ngoài ra còn có nhiều thứ khác nữa.', 20),
(3002455, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 21', '棚の 上に 人形が 飾って あります。', 'Trên kệ có bày một con búp bê để trang trí.', 21),
(3002456, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 22', '壁に 鏡が 掛けて あります。', 'Trên tường có treo gương.', 22),
(3002457, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 23', 'テーブルに 花瓶が 置いて あります。', 'Trên bàn có đặt một lọ hoa.', 23),
(3002458, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 24', '本に 名前が 書いて あります。', 'Trong sách có ghi tên.', 24),
(3002459, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 25', '池の 周りに 木が 植えて あります。', 'Quanh ao có trồng cây.', 25),
(3002460, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 26', '買い物の メモは どこですか。', 'Mẩu ghi chú mua sắm ở đâu?', 26),
(3002461, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 27', '…冷蔵庫に 貼って あります。', '…Được dán trên tủ lạnh.', 27),
(3002462, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 28', 'カレンダーは どこですか。', 'Tờ lịch ở đâu?', 28),
(3002463, 3000579, 'GRAMMAR', 3000204, 'Ví dụ 29', '…冷蔵庫の 横に 掛けて あります。', '…Được treo bên cạnh tủ lạnh.', 29),
(3002464, 3000580, 'READING', NULL, 'Luyện tập', 'Bài có 8 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002465, 3000581, 'LISTENING', NULL, '非常袋を 準備して おかないと – Phải chuẩn bị sẵn túi đồ khẩn cấp mới được', 'ミラー：こんにちは。\n鈴木：いらっしゃい。さあ、どうぞ。\nミラー：大きい リュックが 置いて ありますね。\nミラー：山へ 行くんですか。\n鈴木：いや、非常袋ですよ。\nミラー：非常袋？ 何ですか。\n鈴木：非常時に 使う 物を 入れて おく 袋です。\n鈴木：電気や ガスが 止まっても、3日ぐらい 生活できる 物が 入れて あるんです。\nミラー：水や 食べ物ですか。\n鈴木：ええ、ほかにも いろいろ ありますよ。\n鈴木：懐中電灯とか、ラジオとか……。\nミラー：わたしも 準備して おかないと。\n鈴木：非常袋は スーパーでも 売って いますよ。\nミラー：そうですか。じゃ、買って おきます。', 'Chào anh.\nChào anh, mời anh vào.\nCó một chiếc ba lô to để sẵn ở đây nhỉ.\nAnh định đi leo núi à?\nKhông, đây là túi đồ khẩn cấp đấy.\nTúi đồ khẩn cấp? Là gì vậy anh?\nLà túi đựng sẵn những thứ cần dùng khi khẩn cấp.\nTrong túi có sẵn đồ dùng đủ để sinh hoạt khoảng ba ngày, kể cả khi mất điện hay ngừng cấp ga.\nNước và thức ăn phải không anh?\nVâng, ngoài ra còn nhiều thứ khác nữa.\nChẳng hạn như đèn pin, radio…\nTôi cũng phải chuẩn bị sẵn mới được.\nTúi đồ khẩn cấp cũng có bán ở siêu thị đấy.\nVậy à. Thế thì tôi sẽ mua sẵn một túi.', 1),
(3002466, 3000581, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002467, 3000581, 'LISTENING', NULL, 'Hỏi về đồ vật được đặt sẵn', 'A：あそこに ポスターが はって ありますね。\nA：あれは 何ですか。\nB：スポーツ教室の お知らせです。\nA：そうですか。\nA：廊下に 本が 並べて ありますね。\nA：あれは 何ですか。\nB：日本語教室の 本です。\nA：そうですか。\nA：玄関に 箱が 置いて ありますね。\nA：あれは 何ですか。\nB：古い 本や 雑誌を 入れる 箱です。\nA：そうですか。', 'Ở đằng kia có dán áp phích nhỉ.\nCái đó là gì vậy?\nLà thông báo về lớp học thể thao.\nVậy à.\nỞ hành lang có xếp sách nhỉ.\nCái đó là gì vậy?\nLà sách của lớp tiếng Nhật.\nVậy à.\nỞ lối vào có đặt một chiếc hộp nhỉ.\nCái đó là gì vậy?\nLà hộp để đựng sách và tạp chí cũ.\nVậy à.', 3),
(3002468, 3000581, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002469, 3000581, 'LISTENING', NULL, 'Hỏi việc cần chuẩn bị trước', 'A：来週の ミーティングまでに 何を して おいたら いいですか。\nB：そうですね。\nB：この 資料を コピーして おいて ください。\nA：はい、わかりました。\nA：来週の 会議までに 何を して おいたら いいですか。\nB：そうですね。\nB：この レポートを 読んで おいて ください。\nA：はい、わかりました。\nA：来週の 出張までに 何を して おいたら いいですか。\nB：そうですね。\nB：新しい カタログを 準備して おいて ください。\nA：はい、わかりました。', 'Trước buổi họp tuần sau, tôi nên chuẩn bị những gì?\nĐể tôi xem nào.\nBạn phô tô sẵn tài liệu này nhé.\nVâng, tôi hiểu rồi.\nTrước cuộc họp tuần sau, tôi nên chuẩn bị những gì?\nĐể tôi xem nào.\nBạn đọc trước bản báo cáo này nhé.\nVâng, tôi hiểu rồi.\nTrước chuyến công tác tuần sau, tôi nên chuẩn bị những gì?\nĐể tôi xem nào.\nBạn chuẩn bị sẵn ca-ta-lô mới nhé.\nVâng, tôi hiểu rồi.', 5),
(3002470, 3000581, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002471, 3000581, 'LISTENING', NULL, 'Đề nghị giúp và hỏi cách thu dọn', 'A：手伝いましょうか。\nB：ええ、お願いします。\nA：お皿や コップは どう しましょうか。\nB：台所へ 持って 行って おいて ください。\nA：わかりました。\nA：手伝いましょうか。\nB：ええ、お願いします。\nA：ジュースの 缶は どう しましょうか。\nB：あの 大きい 袋に 入れて おいて ください。\nA：わかりました。\nA：手伝いましょうか。\nB：ええ、お願いします。\nA：ケーキの 箱は どう しましょうか。\nB：この 紙と いっしょに まとめて おいて ください。\nA：わかりました。', 'Mình giúp bạn nhé?\nVâng, nhờ bạn giúp.\nCòn đĩa và cốc thì mình dọn thế nào?\nBạn mang vào bếp để sẵn nhé.\nMình hiểu rồi.\nMình giúp bạn nhé?\nVâng, nhờ bạn giúp.\nCòn những lon nước trái cây thì mình dọn thế nào?\nBạn cho vào chiếc túi to kia nhé.\nMình hiểu rồi.\nMình giúp bạn nhé?\nVâng, nhờ bạn giúp.\nCòn hộp bánh kem thì mình dọn thế nào?\nBạn gom lại cùng với chỗ giấy này nhé.\nMình hiểu rồi.', 7),
(3002472, 3000581, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002473, 3000582, 'READING', NULL, 'Luyện tập', 'Bài có 10 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002474, 3000583, 'READING', NULL, 'Văn mẫu 文型', '交番に 町の 地図が はって あります。\n旅行の まえに、インターネットで いろいろ 調べて おきます。', 'Ở đồn cảnh sát có dán sẵn bản đồ khu phố.\nTrước chuyến đi, tôi sẽ tìm hiểu sẵn nhiều thứ trên Internet.', 1),
(3002475, 3000583, 'READING', NULL, 'Ví dụ 例文', '駅の 新しい トイレ、おもしろいですね。\n…え？そうですか。\n壁に 花や 動物の 絵が かいて あるんです。\nセロテープは どこですか。\n…あの 引き出しに しまって ありますよ。\n来月の 出張ですが、ホテルを 予約して おきましょうか。\n…はい、お願いします。\nはさみを 使ったら、元の 所に 戻して おいて ください。\n…はい、分かりました。\n資料を 片付けても いいですか。\n…いいえ、その ままに して おいて ください。まだ 使って いますから。', 'Nhà vệ sinh mới ở ga trông thú vị nhỉ.\n…Ồ? Thế à?\nTrên tường có vẽ hoa và các con vật đấy.\nBăng dính ở đâu vậy?\n…Nó được cất trong ngăn kéo kia đấy.\nVề chuyến công tác tháng sau, để tôi đặt trước phòng khách sạn nhé?\n…Vâng, nhờ bạn giúp.\nDùng kéo xong, bạn cất lại chỗ cũ nhé.\n…Vâng, tôi hiểu rồi.\nTôi dọn tài liệu đi được không?\n…Không, bạn cứ để nguyên như vậy. Tôi vẫn đang dùng.', 2),
(3002476, 3000583, 'READING', NULL, 'Luyện tập A – 1', 'カレンダーに 今月の 予定が 書いて あります。\n壁に 絵が 掛けて あります。\nテーブルに お皿が 並べて あります。', 'Trên lịch có ghi sẵn kế hoạch tháng này.\nTrên tường có treo sẵn tranh.\nTrên bàn có bày sẵn đĩa.', 3),
(3002477, 3000583, 'READING', NULL, 'Luyện tập A – 2', '写真は 引き出しに しまって あります。\nごみ箱は 部屋の 隅に 置いて あります。\n予定表は ドアの 右に はって あります。', 'Ảnh được cất trong ngăn kéo.\nThùng rác được đặt ở góc phòng.\nBảng kế hoạch được dán bên phải cửa.', 4),
(3002478, 3000583, 'READING', NULL, 'Luyện tập A – 3', '子どもが 生まれる まえに、服や ベッドを 買って おきます。\n子どもが 生まれる まえに、名前を 決めて おきます。', 'Trước khi em bé chào đời, tôi sẽ mua sẵn quần áo và giường.\nTrước khi em bé chào đời, tôi sẽ chọn sẵn tên cho bé.', 5),
(3002479, 3000583, 'READING', NULL, 'Luyện tập A – 4', '食事が 終わったら、茶わんや お皿を 洗って おきます。\n食事が 終わったら、テーブルの 上を 片付けて おきます。', 'Ăn xong, tôi sẽ rửa sẵn bát đĩa.\nĂn xong, tôi sẽ dọn gọn mặt bàn.', 6),
(3002480, 3000583, 'READING', NULL, 'Luyện tập A – 5', 'あした 会議が ありますから、いすは この 部屋に 置いて おきます。\nあした 会議が ありますから、いすは そこに 並べて おきます。\nあした 会議が ありますから、いすは その ままに して おきます。', 'Vì ngày mai có cuộc họp nên tôi sẽ để sẵn ghế trong phòng này.\nVì ngày mai có cuộc họp nên tôi sẽ xếp sẵn ghế ở đó.\nVì ngày mai có cuộc họp nên tôi sẽ để nguyên ghế như vậy.', 7),
(3002481, 3000584, 'READING', NULL, 'Luyện tập', 'Bài có 4 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002482, 3000585, 'READING', NULL, 'r-intro', '時計がなかったら、不便ですが、たくさんあっても、大変です。', 'Không có đồng hồ thì bất tiện, nhưng có nhiều quá cũng vất vả.', 1),
(3002483, 3000585, 'READING', NULL, 'r-collection', '広島県福山市の赤繁さんのうちには時間を音で知らせる時計が560あります。\n壁に掛ける時計が310、置き時計が210、そのほかの時計が40です。\n日本でいちばん時計の音がうるさいうちです。\n560の時計が決まった時間になると、鳴るのです。', 'Nhà ông Akashige ở thành phố Fukuyama, tỉnh Hiroshima có 560 chiếc đồng hồ báo giờ bằng âm thanh.\nCó 310 chiếc đồng hồ treo tường, 210 chiếc đồng hồ để bàn và 40 chiếc đồng hồ khác.\nĐây là ngôi nhà có tiếng đồng hồ ồn nhất Nhật Bản.\nCứ đến giờ đã định, 560 chiếc đồng hồ lại reo lên.', 2),
(3002484, 3000585, 'READING', NULL, 'r-winding', 'ほとんど古い時計で、そのままにしておくと、止まってしまいます。\n毎日ねじを巻かなければなりません。\n赤繁さんは1日中時計のねじを巻いていますから、右手がいつも痛いと言っています。\nもし一度に560の時計が全部鳴ったら、耳も痛くなってしまいますね。\nでも、みんな古い時計ですから、少しずつ違う時間に鳴ります。\nですから、赤繁さんの耳は痛くならないのです。', 'Hầu hết đều là đồng hồ cũ, cứ để nguyên như vậy thì chúng sẽ ngừng chạy.\nNgày nào cũng phải lên dây cót.\nÔng Akashige nói tay phải lúc nào cũng đau vì ông lên dây cót đồng hồ suốt ngày.\nNếu cả 560 chiếc đồng hồ cùng reo một lúc thì chắc tai cũng đau mất nhỉ.\nNhưng vì tất cả đều là đồng hồ cũ nên chúng reo vào những thời điểm hơi lệch nhau.\nVì thế tai ông Akashige không bị đau.', 3),
(3002485, 3000585, 'READING', NULL, 'r-interview', '赤繁さんにちょっと聞きました。', 'Tôi đã hỏi ông Akashige một vài điều.', 4),
(3002486, 3000585, 'READING', NULL, 'r-e1', '――どうしてそんなにたくさん時計を集めているんですか。\n30年まえに骨董屋で見つけた時計を修理してから、時計が好きになりました。\n壊れた時計を直すと、動きますね。\nそれが楽しいんです。\n今も古い時計を見ると、買ってしまいます。\nもう離れの4つの部屋がいっぱいで、押し入れにも積んであります。', '— Vì sao ông lại sưu tập nhiều đồng hồ như vậy?\nTừ khi sửa chiếc đồng hồ tôi tìm được ở một cửa hàng đồ cổ 30 năm trước, tôi bắt đầu thích đồng hồ.\nSửa chiếc đồng hồ bị hỏng thì nó lại chạy, phải không?\nĐiều đó làm tôi rất vui.\nBây giờ cũng vậy, cứ thấy đồng hồ cũ là tôi lại mua.\nBốn phòng ở nhà phụ đã đầy cả rồi, trong tủ âm tường cũng chất đầy đồng hồ.', 5),
(3002487, 3000585, 'READING', NULL, 'r-e2', '――夜はよく寝られますか。\n時計の音がうるさくないですか。\n好きな時計の音ですから、すぐ慣れましたよ。\n音楽と同じです。', '— Buổi tối ông có ngủ ngon được không?\nTiếng đồng hồ không ồn sao ạ?\nĐó là tiếng của những chiếc đồng hồ tôi yêu thích nên tôi đã quen ngay đấy.\nCũng giống như âm nhạc vậy.', 6),
(3002488, 3000585, 'READING', NULL, 'r-e3', '――将来、時計の博物館を作りたいと思っていますか。\nええ。でも、今はお金がありませんから…。\nしばらくこのままにしておきます。', '— Trong tương lai, ông có muốn lập một bảo tàng đồng hồ không?\nCó chứ. Nhưng bây giờ tôi không có tiền nên…\nTôi sẽ cứ để thế này một thời gian nữa.', 7),
(3002489, 3000585, 'READING', NULL, 'x-memo1', '1)\nお帰りなさい。\n冷蔵庫にケーキとジュースが入れてあります。\n食べたら、お皿とコップは洗っておいてね。\n5時ごろ帰ります。', 'Mẩu nhắn 1\nVề rồi đấy à.\nBánh và nước trái cây để sẵn trong tủ lạnh rồi.\nĂn xong nhớ rửa đĩa và cốc nhé.\nKhoảng 5 giờ tôi về.', 8),
(3002490, 3000585, 'READING', NULL, 'x-memo2', '2)\n大阪支店の佐藤さんから電話がありました。\n出張の予定を知らせておきました。\n会議の資料はメールで送っておきました。\nでは、お先に失礼します。', 'Mẩu nhắn 2\nChị Sato ở chi nhánh Osaka đã gọi điện đến.\nTôi đã báo trước lịch công tác cho chị ấy.\nTôi đã gửi trước tài liệu cuộc họp qua email.\nVậy tôi xin phép về trước ạ.', 9),
(3002491, 3000585, 'READING', NULL, 'x-memo3', '3)\nきのうはほんとうにゴメン。\n僕が悪かった。\n今晩は早く帰る。', 'Mẩu nhắn 3\nChuyện hôm qua, tôi thật sự xin lỗi.\nTôi đã sai.\nTối nay tôi sẽ về sớm.', 10),
(3002492, 3000585, 'READING', NULL, 'x-memo4', '4)\n掃除しました。\n机の上はそのままにしてあります。\n今晩の食事はカレーです。\nサラダは冷蔵庫に入れてあります。\nそれから3時ごろ荷物が届きました。\n台所に置いてあります。\nあさっての午後また伺います。', 'Mẩu nhắn 4\nTôi đã dọn dẹp rồi.\nTrên bàn thì tôi để nguyên như cũ.\nBữa tối nay là cà ri.\nTôi đã để xa lát trong tủ lạnh.\nNgoài ra, khoảng 3 giờ có hàng gửi đến.\nTôi đã để ở trong bếp.\nChiều ngày kia tôi sẽ lại đến.', 11),
(3002493, 3000585, 'READING', NULL, 'x-memo5', '5)\n絶対にビデオに触らないで。\n今晩8時からサッカーの試合が予約してあるから。\nそれから今晩は彼女と食事するから、晩ごはんは要らないよ。', 'Mẩu nhắn 5\nTuyệt đối đừng đụng vào đầu video.\nVì tôi đã hẹn giờ ghi lại trận bóng đá từ 8 giờ tối nay rồi.\nCòn nữa, tối nay tôi đi ăn với bạn gái nên không cần phần cơm tối đâu.', 12),
(3002494, 3000586, 'READING', NULL, 'Luyện tập', 'Bài có 10 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002495, 3000587, 'LISTENING', NULL, '1. Giải quyết việc ở ký túc xá学生寮は どんな問題が ありますか。その 問題を どうしますか。Ký túc xá có những vấn đề gì? Mọi người sẽ giải quyết thế nào?', 'A：最近、寮の前に自転車が たくさん置いて ありますね。\nA：きれいじゃありません。\nB：ええ、片づけない人が多いんです。\nB：ちょっと問題ですね。\nB：「自転車置き場に入れて ください」と書いてあるんですが。\nA：じゃ、寮の前に自転車を置いた人の名前を書いて、ロビーに はりましょう。\nB：そうしましょう。\nA：ロビーが ちょっと暗いですね。\nB：ええ、カーテンが掛けて あるんですが、\nB：とても汚れて いるんです。\nA：じゃ、カーテンを取りましょう。\nA：明るく なりますよ。\nB：でも、なかったら、外から部屋の中が全部見えますよ。\nA：じゃ、洗いましょう。\nA：ロビーの壁に ポスターが はって ありますね。\nB：ああ、去年の留学生の旅行の ポスターですね。\nA：もう要らないから、捨てましょう。\nB：そうですね。\nA：あの部屋の外に本が たくさん置いて ありますね。\nB：ジャンさんの部屋ですね。\nB：彼は とても たくさん本を持って いますから。\nB：部屋の中には もう置けないんですよ。\nA：でも、危ないですよ。\nA：捨てましょう。\nB：それは……ちょっと。\nB：ジャンさんに片づけて もらいましょう。', 'Gần đây có nhiều xe đạp để trước ký túc xá nhỉ.\nTrông không đẹp mắt.\nVâng, có nhiều người không sắp xếp gọn gàng.\nThật phiền nhỉ.\nCó ghi “Vui lòng để xe vào chỗ để xe đạp” rồi mà…\nVậy chúng ta ghi tên những người để xe đạp trước ký túc xá rồi dán ở sảnh nhé.\nChúng ta làm như vậy nhé.\nSảnh hơi tối nhỉ.\nVâng, rèm cửa đang treo ở đây…\nbẩn lắm rồi.\nVậy chúng ta tháo rèm xuống nhé.\nSẽ sáng hơn đấy.\nNhưng nếu không có rèm thì từ ngoài sẽ nhìn thấy hết bên trong phòng đấy.\nVậy chúng ta giặt rèm nhé.\nCó áp phích dán trên tường ở sảnh nhỉ.\nÀ, áp phích chuyến du lịch của du học sinh năm ngoái nhỉ.\nVì không cần thiết nữa nên chúng ta vứt bỏ nó nhé.\nĐúng vậy nhỉ.\nCó nhiều quyển sách đặt ở ngoài phòng đó nhỉ.\nLà phòng của anh Jean nhỉ.\nVì anh ấy có rất nhiều sách.\nTrong phòng không còn chỗ để nữa.\nNhưng như vậy nguy hiểm đấy.\nChúng ta bỏ đi nhé.\nThế thì… hơi khó.\nChúng ta nhờ anh Jean dọn nhé.', 1),
(3002496, 3000587, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002497, 3000587, 'LISTENING', NULL, '2. Chọn đúng phòng trà今、クララさんが いる茶室は どれですか。Chọn hình căn phòng trà mà Clara đang ở', 'A：クララさん、こちらが この お寺の茶室です。\nB：静かで すてきですね。\nB：でも、ちょっと狭いですね。\nA：ええ、この茶室は大切な人2、3人と ゆっくり お茶を飲む所なんです。\nA：ですから、狭いんです。\nB：あ、ドアが ある。\nB：でも、低い所に作って ありますね。\nA：ええ、庭から来る人は ここから入ります。\nB：ええ。\nB：ここから入るんですか。\nB：ああ、きれいな花が飾って ありますね。\nA：ええ。\nA：この庭で咲いた花なんですよ。\nB：この花瓶は有名な人が作ったんですか。\nA：ええ、そうですよ。\nA：すてきでしょう?\nB：ええ。あそこに絵が掛けて ありますね。\nB：何が かいてあるんですか。\nA：あれは絵じゃありません。\nA：ひらがなが書いて あるんですよ。\nB：あ、わかりました。\nB：「はる」ですね。\nA：そうです。\nA：さあ、クララさん、どうぞ座って ください。\nB：はい。え、テーブルは ないんですか。\nA：ええ、茶室には テーブルや机は置かないんですよ。\nB：そうなんですか。\nA：さあ、お茶を どうぞ。\nB：いただきます。', 'Clara, đây là phòng trà của ngôi chùa này.\nĐẹp và yên tĩnh nhỉ.\nNhưng hơi chật nhỉ.\nVâng, phòng trà này là nơi thong thả uống trà cùng hai, ba người thân thiết.\nCho nên nó chật hẹp.\nÀ, có cửa ra vào kìa.\nNhưng cửa được làm ở vị trí thấp nhỉ.\nVâng, người đến từ sân vườn sẽ vào từ chỗ này.\nVâng.\nSẽ vào từ chỗ này phải không?\nÀ, hoa bày ở đây đẹp nhỉ.\nVâng.\nĐó là hoa nở trong khu vườn này đấy.\nBình hoa này do một người nổi tiếng làm à?\nVâng, đúng vậy đấy.\nTuyệt vời phải không?\nVâng, có treo bức tranh ở chỗ đằng kia nhỉ.\nTrên đó vẽ gì vậy?\nCái đó không phải là tranh.\nTrên đó viết chữ hiragana đấy.\nÀ, tôi hiểu rồi.\nLà chữ “Haru” (mùa xuân) nhỉ.\nĐúng vậy.\nNào, Clara, mời bạn ngồi.\nVâng. Ủa, không có bàn ạ?\nĐúng vậy, trong phòng trà không đặt bàn ăn hay bàn làm việc.\nVậy à.\nXin mời dùng trà ạ.\nTôi xin phép dùng ạ.', 3),
(3002498, 3000587, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002499, 3000587, 'LISTENING', NULL, '3. Chuẩn bị thi hùng biệnスピーチコンテストの 準備を して います。何が どこに ありますか。Mọi người chuẩn bị cho cuộc thi hùng biện. Các đồ vật nằm ở đâu?', 'A：あしたの スピーチコンテストの準備は できましたか。\nB：はい。だいたい終わりました。\nB：ちょっと教室の中を みてください。\nA：いすは いくつ並べましたか。\nB：スピーチを する人が10人、聞く人が80人ぐらいですから、全部で90並べて あります。\nA：聞きたい人が たくさん来たら、どうしますか。\nB：そのときは隣の教室から借りましょう。\nA：スピーチをする人はあそこに立つんですね。\nB：はい。机の真ん中にマイクが置いて あります。\nA：前の壁にはってある紙は？\nB：窓側ですね。\nB：スピーチをする人の名前が書いて あります。\nA：ああ、いいですね。\nA：プログラムは できましたか。\nB：はい。教室の外に机が ありますね。\nB：プログラムは その上に置いて あります。\nB：スピーチを聞いてから、意見を書いて もらう紙も いっしょに置いて あります。\nA：時々ボールペンや鉛筆を持って いない人が いますよ。\nB：大丈夫です。意見を書く紙の横に鉛筆が置いて ありますから。\nA：いちばん いい スピーチを した人に あげる プレゼントは？\nB：電子辞書ですね。\nB：きのう、買いに行きました。\nA：どこに あるんですか。\nB：あそこに引き出しが ありますね。\nB：あの中に しまって あります。\nB：スピーチが終わってから、審査員の所へ持って行きます。\nA：それから、スピーチを した人は みんな プレゼントが もらえるんですね。\nB：ええ、本が買える カードです。\nB：それも電子辞書と いっしょに しまって あります。\nA：そうですか。\nA：じゃ、もう準備は できましたね。', 'Đã chuẩn bị xong cho cuộc thi hùng biện ngày mai chưa?\nVâng, gần xong rồi.\nMời xem bên trong phòng học một chút.\nĐã xếp bao nhiêu chiếc ghế rồi?\nCó 10 người phát biểu và khoảng 80 người nghe nên đã xếp tổng cộng 90 chiếc ghế.\nNếu người nghe đến nhiều thì làm thế nào?\nLúc đó chúng ta mượn ghế ở phòng học bên cạnh nhé.\nNgười phát biểu đứng ở đằng kia à?\nVâng, micro được đặt ở giữa bàn.\nTờ giấy dán trên bức tường phía trước là gì?\nỞ phía cửa sổ nhỉ.\nTrên đó viết tên những người phát biểu.\nÀ, tốt đấy.\nĐã làm xong bản chương trình chưa?\nVâng. Có một chiếc bàn ở ngoài phòng học đấy.\nBản chương trình được đặt trên bàn đó.\nPhiếu để mọi người ghi nhận xét sau khi nghe phát biểu cũng được đặt cùng ở đó.\nĐôi khi có người không mang bút bi hay bút chì đấy.\nKhông sao. Tôi đã đặt bút chì cạnh phiếu góp ý.\nQuà tặng cho người phát biểu hay nhất thì sao?\nTừ điển điện tử nhỉ.\nTôi đã đi mua vào hôm qua.\nỞ đâu vậy?\nỞ đằng kia có ngăn kéo nhỉ.\nCất ở trong đó.\nPhần thi kết thúc thì tôi sẽ mang đến chỗ giám khảo.\nCòn tất cả những người phát biểu đều nhận được quà nhỉ?\nVâng, phiếu mua sách.\nCái ấy tôi cũng cất cùng với từ điển điện tử.\nVậy à.\nVậy đã chuẩn bị xong hết rồi nhỉ.', 5),
(3002500, 3000587, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002501, 3000587, 'LISTENING', NULL, '4. Du lịch cùng robot Aimoロボットと 旅行に 行きます。ロボットの 名前は「アイモ」です。アイモは 次の ことを しますか。Một người đi du lịch cùng robot tên là Aimo. Aimo có làm những việc sau không?', 'A：あしたから旅行だな。\nA：アイモ、荷物を まとめておいて。\nB：何を持って行きますか。\nA：僕の服と下着を かばんの中に入れて おいて。\nB：わたしは何を持って行ったら いいですか。\nA：アイモは電池だけ持って行ったら いいよ。\nB：はい、わかりました。\nA：アイモ、これから飛行機に乗るよ。\nA：かばんから チケットと パスポートを出して おいて。\nB：これですか。\nA：ううん。\nA：それは手帳だよ。\nA：それは元の所に戻して おいてね。\nA：こっちだよ。\nB：はい。\nA：さあ、ホテルに着いた。\nA：アイモ、広くて いい部屋だよ。\nB：はい。\nB：窓を開けましょうか。\nA：窓は開けなくても いいよ。\nA：そのままに して おいて。\nA：あ、脱いだ服を しまっておいてね。\nB：はい、しまって おきます。\nA：あ、このシャツ、汚れたから、洗っておいてね。\nB：はい、わかりました。\nB：あのう、かばんの中の物を全部出しましょうか。\nA：ううん。\nA：その ままに して おいて。\nA：アイモ、もうすぐ昼ごはんの時間だね。\nA：イタリア料理の レストランを予約して おいてね。\nB：はい、何時に行くと言いましょうか。\nA：そうだな。\nA：シャワーを浴びてから、出かけたいから、\nA：1時に行くと言って おいて。\nB：はい、わかりました。\nB：あのう、わたしも シャワーを浴びるんですか。\nA：君は浴びなくても いいよ。そのまま待って いてね。\nA：わあ、すごい料理だ。\nA：いただきます。\nB：たくさん仕事を しましたから、\nB：わたしも おなかが すきました。\nB：ちょっと食べても いいですか。\nA：だめだめ。\nA：君は そのまま そこに座っていてね。\nA：あとで電池を あげるよ。\nB：でも、電池は全然おいしくないんです。\nB：それが食べたい……。\nA：僕のだよ。\nA：触らないで。\nA：もう少し待って いてね、アイモ。\nB：何も くれないの?\nB：ふん、じゃ、日本へ帰って、ほかの仕事を探すよ。\nA：え？帰るの？\nB：荷物は そのままに して おくから、あしたからは全部自分で してね。バイバイ。\nA：アイモ、行かないで。\nA：君が いなかったら困るんだ。', 'Sẽ đi du lịch từ ngày mai nhỉ.\nAimo, chuẩn bị hành lý trước nhé.\nSẽ mang theo cái gì vậy?\nBỏ quần áo và đồ lót của tớ vào trong túi xách nhé.\nCòn tớ thì nên mang gì?\nAimo chỉ cần mang theo pin là được rồi.\nVâng, tớ hiểu rồi.\nAimo, bây giờ sẽ lên máy bay đấy.\nHãy lấy sẵn vé và hộ chiếu từ túi xách ra.\nCái này phải không?\nKhông phải.\nCái đó là sổ tay đấy.\nCái đó hãy để lại chỗ cũ nhé.\nCái này đấy.\nVâng.\nVậy là đến khách sạn rồi.\nAimo, phòng rộng và đẹp đấy.\nVâng.\nTớ mở cửa sổ ra nhé?\nKhông cần mở cửa sổ đâu.\nCứ để nguyên như vậy nhé.\nÀ, cất quần áo đã cởi ra nhé.\nVâng, tớ sẽ cất đi.\nÁo sơ mi này bẩn rồi, giặt giúp tớ nhé.\nVâng, tớ hiểu rồi.\nÀ, để tớ lấy hết đồ trong túi xách ra nhé?\nKhông.\nCứ để nguyên như vậy nhé.\nAimo, sắp đến giờ cơm trưa nhỉ.\nĐặt trước nhà hàng Ý giúp tớ nhé.\nVâng, tớ báo là chúng ta đến lúc mấy giờ?\nĐể xem nào.\nTớ muốn ra ngoài sau khi tắm,\nnên cứ báo trước là 1 giờ nhé.\nVâng, tớ hiểu rồi.\nÀ… tớ cũng phải tắm vòi sen à?\nCậu không cần tắm đâu. Cứ đợi như vậy nhé.\nỒ, món ăn trông tuyệt quá.\nTớ xin phép dùng ạ.\nVì làm nhiều việc quá nên…\nTớ cũng đói rồi.\nTớ ăn một chút được không?\nKhông được, không được.\nCậu ngồi nguyên ở chỗ đó nhé.\nLát nữa tớ sẽ cho cậu pin.\nNhưng pin chẳng ngon chút nào.\nTớ muốn ăn món đó…\nCái đó là của tớ!\nKhông sờ vào.\nĐợi thêm một chút nhé, Aimo.\nAnh không cho tôi gì cả à?\nHừ, vậy tôi về Nhật tìm việc khác đây.\nHả? Cậu về sao?\nTôi để nguyên hành lý đó, từ mai anh tự làm hết nhé. Tạm biệt!\nAimo, đừng đi!\nKhông có cậu thì tôi khổ mất.', 7),
(3002502, 3000587, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002503, 3000588, 'READING', NULL, 'Luyện tập', 'Bài có 43 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002504, 3000589, 'READING', NULL, '1. Nghe và trả lời', 'Nghe câu hỏi rồi trả lời về bản thân. Xem câu mẫu của Nguyễn Minh sau khi tự trả lời.\n時計が 置いて あります。\nはい、カレンダーが 掛けて あります。\n机の 引き出しに しまって あります。\n料理を 作ったり、飲み物を 買ったり して おきます。\nことばや 習慣を 勉強して おいたら いいと 思います。', NULL, 1),
(3002505, 3000589, 'READING', NULL, '1. Nghe và trả lời', 'Nghe câu hỏi rồi trả lời về bản thân. Xem câu mẫu của Nguyễn Minh sau khi tự trả lời.\n机の 上に 何が 置いて ありますか。\nあなたの 部屋の 壁に 何か 掛けて ありますか。\nパスポートは どこに しまって ありますか。\nパーティーの まえに、どんな 準備を して おきますか。\n外国へ 行く まえに、どんな ことを して おいたら いいですか。', NULL, 2),
(3002506, 3000589, 'READING', NULL, '2. Nghe: đúng hay sai', 'Nghe hội thoại và câu ★, chọn ○ nếu đúng hoặc × nếu sai.\n女：この 傘、だれのですか。\n男：忘れ物ですね。名前が 書いて ありませんか。\n女：ああ、ここに 書いて あります。佐藤さんのです。\n★：傘に 佐藤さんの 名前が 書いて あります。\n女：セロテープは どこですか。\n男：あの 引き出しの 中は 見ましたか。\n女：見たんですが、ないんです。\n男：あ、ここに あります。すみません。\n★：セロテープは 引き出しに 入れて あります。\n男：木曜日の 夜の 予定は？\n女：パワー電気の 森部長と お食事です。大阪ホテルの レストランを 予約して おきました。\n男：そう。ありがとう。\n★：男の 人は 木曜日の 夜 大阪ホテルで 食事します。\n男：田中さん、もう 帰っても いいですよ。\n女：はい。この 資料、しまって おきましょうか。\n男：まだ 使いますから、出して おいて ください。\n女：わかりました。\n★：女の 人は 資料を しまって、帰ります。\n女：おいしい ケーキが あるから、お茶でも 飲まない？\n男：えっ、冷蔵庫に あった ケーキ？ あれ、もう 食べて しまったけど。\n女：えっ！\n★：男の 人と 女の 人は これから 冷蔵庫に 入れて おいた ケーキを 食べます。', NULL, 3),
(3002507, 3000589, 'READING', NULL, '7. Đọc: ngôi nhà trong mơ', 'Đọc câu chuyện rồi chọn căn phòng thật của người kể sau khi tỉnh giấc.\nわたしの 部屋の 壁に 丸くて 青い 月の 写真が はって あります。いつも ベッドに 入る まえに、写真を 見ます。\nある 晩、夢を 見ました。わたしは 広い 部屋に いました。窓の 外に 地球が 見えました。「ここは 月の うちだ」と 思いました。うれしかったです。でも、よく 見ると、壁には 何も 掛けて ありません。机や いすも ありません。何も 飾って ありません。わたしは 「こんな うちは 嫌だ」と 大きい 声で 言いました。\nすると、目が 覚めました。わたしの 部屋には ベッドや 机が 置いて あります。壁に カレンダーも 掛けて あります。本棚に 好きな 本が いろいろ 並べて あります。夢で 見た うちより いいと 思いました。', NULL, 4),
(3002508, 3000589, 'READING', NULL, '8. Miêu tả ngôi nhà bạn muốn sống', 'Vẽ ra giấy ngôi nhà bạn muốn sống rồi viết lời miêu tả. Bạn có thể tự do viết theo ý mình.\nわたしは 明るくて 静かな うちに 住みたいです。\n部屋には 大きい 机が 置いて あります。本棚に 好きな 本が 並べて あります。\n壁に 家族の 写真が 掛けて あります。', NULL, 5),
(3002509, 3000590, 'READING', NULL, 'Luyện tập', 'Bài có 22 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002510, 3000591, 'READING', NULL, '1. Hành động và trạng thái sau đó', '〜ました ⇒ 〜てあります Nhìn từng cặp tranh: viết câu 〜ました cho hành động bên trái và câu 〜てあります cho trạng thái bên phải, như ví dụ.\n名前を 書きました。\n名前が 書いて あります。\n絵を はりました。\n絵が はって あります。\n本を 引き出しに しまいました。\n本が 引き出しに しまって あります。', NULL, 1),
(3002511, 3000591, 'READING', NULL, '3. Viết về phòng hoặc lớp học', '〜に 〜てあります Viết về lớp học hoặc phòng của bạn theo mẫu 〜に 〜が 〜てあります. Dùng bốn dòng để mô tả đồ vật và vị trí.\n部屋の 隅に 机が 置いて あります。\n壁に カレンダーが 掛けて あります。\n本棚に 本が 並べて あります。\n机の 上に 写真が 飾って あります。', NULL, 2),
(3002512, 3000591, 'READING', NULL, '7. Chuẩn bị trước khi đi, trước khi làm', '〜ておきます（準備） Viết ba việc cần làm trước khi đi du lịch và ba việc trước khi tổ chức tiệc. Mỗi dòng dùng 〜ておきます.\nホテルを 予約して おきます。\n荷物を 準備して おきます。\n旅行の 予定を 決めて おきます。\n飲み物を 買って おきます。\n部屋を 掃除して おきます。\n料理を 作って おきます。', NULL, 3),
(3002513, 3000591, 'READING', NULL, '8. ておきます: chuẩn bị trước', '「〜ておきます」の 整理（A．準備／B．事後措置／C．放置） Hoàn thành hai câu nói việc chuẩn bị trước cuộc họp và trước kỳ thi, theo ví dụ A.\n会議までに、資料を コピーして おきます。\n試験の まえに、漢字を 復習して おきます。', NULL, 4),
(3002514, 3000591, 'READING', NULL, '9. ておきます: thu dọn sau khi làm', '「〜ておきます」の 整理（A．準備／B．事後措置／C．放置） Viết một việc cần làm sau khi kết thúc một hoạt động, theo ví dụ B. Ô đầu kết thúc bằng thể た trước ら, ô sau kết thúc bằng thể て.\n本を 読んだら、本棚に 戻して おきます。', NULL, 5),
(3002515, 3000591, 'READING', NULL, '10. ておきます: giữ nguyên trạng thái', '「〜ておきます」の 整理（A．準備／B．事後措置／C．放置） Hoàn thành lời đáp: nêu lý do chưa dọn ghế và nhờ giữ nguyên trạng thái, theo ví dụ C.\nいいえ。まだ 使いますから、そのままに して おいて ください。', NULL, 6),
(3002516, 3000591, 'READING', NULL, '12. Vẫn đang làm, hãy để nguyên', 'まだ 〜ています（継続） Mỗi tình huống có hai dòng trả lời. Điền một cách nói khác nhau vào mỗi dòng, dùng động từ thể て sau まだ. Tình huống 2 là xin phép xóa bảng.\nいいえ。まだ 飲んで いますから、ちょっと 待って ください。\nいいえ。まだ 使って いますから、ちょっと 待って ください。\nいいえ。まだ 書いて いますから、そのままに して おいて ください。\nいいえ。まだ 読んで いますから、そのままに して おいて ください。', NULL, 7),
(3002517, 3000592, 'READING', NULL, 'Luyện tập', 'Bài có 48 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002518, 3000593, 'READING', NULL, 'Danh sách kanji', '予 (DỰ) — trước; dự định — よ\n習 (TẬP) — học; luyện tập — しゅう\n復 (PHỤC) — phục hồi, khôi phục; trở lại — ふく\n定 (ĐỊNH) — định, quyết định; cố định — てい\n表 (BIỂU) — bề mặt, mặt ngoài; bảng biểu; biểu hiện — ひょう\n決 (QUYẾT) — quyết định — き\n授 (THỤ) — trao, truyền thụ; dạy — じゅ\n業 (NGHIỆP) — nghề, công việc; ngành, ngành nghề — ぎょう\n講 (GIẢNG) — giảng, bài giảng — こう\n義 (NGHĨA) — chính nghĩa, đạo lý; nghĩa vụ — ぎ\n知 (TRI) — hiểu, biết — し\n掛 (QUẢI) — treo, mắc; tốn (thời gian, tiền) — か\n飾 (SỨC) — trang trí, trang sức — かざ\n並 (TỊNH) — xếp hàng, sắp xếp; bình thường — なら\n植 (THỰC) — trồng; thực vật — う\n戻 (LỆ) — quay lại, trở về; trả lại — もど\n箱 (TƯƠNG) — hộp, thùng — はこ\n人 (NHÂN) — người — にん\n形 (HÌNH) — hình, hình dạng; kiểu — ぎょう\n花 (HOA) — hoa — か\n瓶 (BÌNH) — chai, lọ, bình — びん\n鏡 (KÍNH) — gương — かがみ\n引 (DẪN) — kéo; dẫn; giảm (giá) — ひ\n出 (XUẤT) — ra; đưa ra ngoài — だ\n玄 (HUYỀN) — đen huyền; sâu xa, huyền bí; tiền sảnh (玄関) — げん\n関 (QUAN) — liên quan; cửa ải, cửa khẩu — かん\n廊 (LANG) — hành lang — ろう\n下 (HẠ) — dưới, bên dưới; hạ xuống, hạ thấp — か\n壁 (BÍCH) — tường, vách; trở ngại — かべ\n池 (TRÌ) — ao, hồ (nhỏ) — いけ\n元 (NGUYÊN) — gốc; ban đầu — もと\n所 (SỞ) — nơi, chỗ — ところ\n周 (CHU) — chu vi, xung quanh; vòng — まわ\n真 (CHÂN) — thật, chân thật — ま\n中 (TRUNG) — trong; giữa — なか\n隅 (NGUNG) — góc — すみ', NULL, 1),
(3002519, 3000594, 'READING', NULL, '使い方 – Câu ví dụ', '引き出しの隅に古い手紙がありました。彼女がくれた手紙です。\n机の上にパソコンを置きます。ピアノの上に母の写真を置きます。\nパーティーの前に、ビールを箱から出して、冷蔵庫に入れます。いすを並べておきます。\nあした友達が来ますから、部屋を片づけます。\n習った漢字を復習します。それから、あした習う漢字を予習します。\nホテルと飛行機を予約しました。早く予約すると、安くなります。\n部屋を片づけました。古い人形を捨てましたが、母が拾って、元の所に置きました。\nお知らせの紙がはってあります。エレベーターが故障です。\nケーキの真ん中にチョコレートの人形が置いてあります。', NULL, 1),
(3002520, 3000594, 'READING', NULL, '読み物 – Bài đọc · パーティーの準備', '今日は妻の誕生日です。5時からパーティーをします。友達に連絡しておきました。家の中を片づけておかなければなりません。\nメモ\n2：00 ワインを箱から出して、冷蔵庫に入れておく。\n3：00 テーブルの上に花とお皿を置いておく。\nナイフとフォークを並べておく。\n部屋の壁に妻の好きな絵を掛けておく。\n4：00 部屋の隅にCDプレーヤーを置いておく。\nジャズのCDを5枚ぐらい置いておく。\nプレゼントの日本人形を箱に入れておく。', NULL, 2),
(3002521, 3000595, 'READING', NULL, 'Luyện tập', 'Bài có 12 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002522, 3000596, 'READING', NULL, 'Luyện tập', 'Bài có 6 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002523, 3000597, 'READING', NULL, 'Danh sách từ vựng', 'Bài có 33 từ vựng.', NULL, 1),
(3002524, 3000599, 'GRAMMAR', 3000205, 'Ví dụ 1', 'いっしょに 帰ろう。', 'Cùng về nào.', 1),
(3002525, 3000599, 'GRAMMAR', 3000205, 'Ví dụ 2', 'ここで 写真を 撮ろう。', 'Chụp ảnh ở đây nào.', 2),
(3002526, 3000599, 'GRAMMAR', 3000206, 'Ví dụ 3', 'ちょっと 休まない？', 'Nghỉ một chút nhé?', 3),
(3002527, 3000599, 'GRAMMAR', 3000206, 'Ví dụ 4', '…うん、休もう。', '…Ừ, nghỉ nào.', 4),
(3002528, 3000599, 'GRAMMAR', 3000206, 'Ví dụ 5', '荷物を 持とうか。', 'Để mình xách hành lý giúp nhé?', 5),
(3002529, 3000599, 'GRAMMAR', 3000206, 'Ví dụ 6', '傘を 持って 行こうか。', 'Mình mang ô theo nhé?', 6),
(3002530, 3000599, 'GRAMMAR', 3000207, 'Ví dụ 7', '来年 車を 買おうと 思って います。', 'Tôi đang định mua ô tô vào năm sau.', 7),
(3002531, 3000599, 'GRAMMAR', 3000207, 'Ví dụ 8', '今から 銀行へ 行こうと 思います。', 'Bây giờ tôi định đi ngân hàng.', 8),
(3002532, 3000599, 'GRAMMAR', 3000207, 'Ví dụ 9', '彼は 学校を 作ろうと 思って います。', 'Anh ấy đang định thành lập một trường học.', 9),
(3002533, 3000599, 'GRAMMAR', 3000208, 'Ví dụ 10', '国へ 帰っても、日本語の 勉強を 続ける つもりです。', 'Dù về nước, tôi vẫn định tiếp tục học tiếng Nhật.', 10),
(3002534, 3000599, 'GRAMMAR', 3000208, 'Ví dụ 11', 'あしたは 出かけない つもりです。', 'Ngày mai tôi định không ra ngoài.', 11),
(3002535, 3000599, 'GRAMMAR', 3000208, 'Ví dụ 12', '週末は 部屋を 片づける つもりです。', 'Cuối tuần tôi định dọn phòng.', 12),
(3002536, 3000599, 'GRAMMAR', 3000209, 'Ví dụ 13', '7月の 終わりに ドイツへ 出張する 予定です。', 'Theo kế hoạch, cuối tháng 7 tôi sẽ đi công tác ở Đức.', 13),
(3002537, 3000599, 'GRAMMAR', 3000209, 'Ví dụ 14', '会議は 月曜日の 予定です。', 'Cuộc họp dự kiến vào thứ hai.', 14),
(3002538, 3000599, 'GRAMMAR', 3000209, 'Ví dụ 15', '旅行は 3日の 予定です。', 'Chuyến du lịch dự kiến kéo dài ba ngày.', 15),
(3002539, 3000599, 'GRAMMAR', 3000210, 'Ví dụ 16', '銀行は まだ 開いて いません。', 'Ngân hàng vẫn chưa mở cửa.', 16),
(3002540, 3000599, 'GRAMMAR', 3000210, 'Ví dụ 17', 'もう 昼ごはんを 食べましたか。', 'Bạn đã ăn trưa chưa?', 17),
(3002541, 3000599, 'GRAMMAR', 3000210, 'Ví dụ 18', '…いいえ、まだ 食べて いません。', '…Chưa, tôi vẫn chưa ăn.', 18),
(3002542, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 19', '帰りの 電車で 本を 読みました。', 'Trên chuyến tàu lúc về, tôi đã đọc sách.', 19),
(3002543, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 20', '休みは 何曜日ですか。', 'Bạn nghỉ vào thứ mấy?', 20),
(3002544, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 21', 'みんな 来たから、始めよう。', 'Mọi người đến đủ rồi, bắt đầu thôi.', 21),
(3002545, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 22', '疲れたから、ちょっと 休憩しよう。', 'Mệt rồi, nghỉ giải lao một chút nào.', 22),
(3002546, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 23', 'よく 見えないから、前の 方に 座ろう。', 'Không nhìn rõ, mình lên ngồi phía trước đi.', 23),
(3002547, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 24', 'もう 遅いから、寝よう。', 'Muộn rồi, ngủ thôi.', 24),
(3002548, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 25', 'あしたは 休みだから、動物園へ 行こう。', 'Mai được nghỉ, mình đi sở thú nhé.', 25),
(3002549, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 26', 'あした 何を しますか。', 'Ngày mai bạn sẽ làm gì?', 26),
(3002550, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 27', '…映画を 見ようと 思って います。', '…Tôi định xem phim.', 27),
(3002551, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 28', '今度の 日曜日は 何を しますか。', 'Chủ nhật này bạn sẽ làm gì?', 28),
(3002552, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 29', '…家族と 教会へ 行こうと 思って います。', '…Tôi định đi nhà thờ cùng gia đình.', 29),
(3002553, 3000599, 'GRAMMAR', 3000211, 'Ví dụ 30', '連休は 何を しますか。', 'Kỳ nghỉ dài này bạn sẽ làm gì?', 30),
(3002554, 3000600, 'READING', NULL, 'Luyện tập', 'Bài có 8 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002555, 3000601, 'LISTENING', NULL, '料理を 習おうと 思って います – Tôi đang định học nấu ăn', '小川：来月から 独身です。\nミラー：えっ？\n小川：実は 大阪の 本社に 転勤なんです。\nミラー：本社ですか。\nミラー：それは おめでとう ございます。\nミラー：でも、どうして 独身に なるんですか。\n小川：妻と 子どもは 東京に 残るんです。\nミラー：えっ、いっしょに 行かないんですか。\n小川：ええ。\n小川：息子は 来年 大学の 入学試験が あるから、東京に 残ると 言うし、妻も 今の 会社を やめたくないと 言うんです。\nミラー：それで、別々に 住むんですね。\n小川：ええ。\n小川：でも、月に 2、3回 週末に 帰る つもりです。\nミラー：大変ですね。\n小川：でも、いい チャンスですから、料理を 習おうと 思って います。\nミラー：それは いいですね。', 'Từ tháng sau tôi sẽ độc thân.\nHả?\nThật ra tôi sắp chuyển công tác đến trụ sở chính ở Osaka.\nTrụ sở chính à?\nVậy thì chúc mừng anh nhé.\nNhưng sao anh lại thành độc thân vậy?\nVợ và con tôi sẽ ở lại Tokyo.\nỒ, họ không đi cùng anh à?\nVâng.\nCon trai tôi nói sẽ ở lại Tokyo vì năm sau phải thi vào đại học, còn vợ tôi cũng nói không muốn nghỉ việc ở công ty hiện tại.\nVì thế mà gia đình anh sẽ sống xa nhau nhỉ.\nVâng.\nNhưng tôi định về nhà vào cuối tuần, mỗi tháng hai, ba lần.\nVất vả thật đấy.\nNhưng đây là cơ hội tốt nên tôi đang định học nấu ăn.\nVậy thì hay quá nhỉ.', 1),
(3002556, 3000601, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002557, 3000601, 'LISTENING', NULL, 'Rủ bạn nghỉ chân, ăn hoặc uống', 'A：ああ、疲れた。\nB：じゃ、どこかで 少し 休もう。\nA：あの 喫茶店に 入らない？\nB：うん、そうしよう。\nA：ああ、おなかが すいた。\nB：じゃ、どこかで 何か 食べよう。\nA：あの 喫茶店に 入らない？\nB：うん、そうしよう。\nA：ああ、のどが 渇いた。\nB：じゃ、どこかで ジュースでも 飲もう。\nA：あの 喫茶店に 入らない？\nB：うん、そうしよう。', 'Ôi, mệt quá.\nVậy mình nghỉ ở đâu đó một chút nhé.\nVào quán cà phê kia không?\nỪ, vậy đi.\nÔi, đói bụng quá.\nVậy mình ăn gì đó ở đâu đó nhé.\nVào quán cà phê kia không?\nỪ, vậy đi.\nÔi, khát quá.\nVậy mình tìm chỗ nào uống nước trái cây hay gì đó nhé.\nVào quán cà phê kia không?\nỪ, vậy đi.', 3),
(3002558, 3000601, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002559, 3000601, 'LISTENING', NULL, 'Hỏi việc chuẩn bị và nói việc sắp làm', 'A：発表の 準備は できましたか。\nB：えーと、まだ 資料を コピーして いません。\nB：これから コピーしようと 思って います。\nA：わかりました。\nA：会議の 準備は できましたか。\nB：えーと、まだ 会議室を 予約して いません。\nB：これから 予約しようと 思って います。\nA：わかりました。\nA：出張の 準備は できましたか。\nB：えーと、まだ 本社に 書類を 送って いません。\nB：これから 送ろうと 思って います。\nA：わかりました。', 'Bạn đã chuẩn bị xong cho buổi thuyết trình chưa?\nÀ, tôi vẫn chưa phô tô tài liệu.\nTôi định phô tô ngay bây giờ.\nTôi hiểu rồi.\nBạn đã chuẩn bị xong cho cuộc họp chưa?\nÀ, tôi vẫn chưa đặt phòng họp.\nTôi định đặt phòng ngay bây giờ.\nTôi hiểu rồi.\nBạn đã chuẩn bị xong cho chuyến công tác chưa?\nÀ, tôi vẫn chưa gửi giấy tờ đến trụ sở chính.\nTôi định gửi ngay bây giờ.\nTôi hiểu rồi.', 5),
(3002560, 3000601, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002561, 3000601, 'LISTENING', NULL, 'Hỏi dự định trong kỳ nghỉ', 'A：夏休みは 何か 予定が ありますか。\nB：北海道を 旅行する つもりです。\nA：いいですね。どのくらいですか。\nB：10日の 予定です。\nA：冬休みは 何か 予定が ありますか。\nB：国へ 帰る つもりです。\nA：いいですね。どのくらいですか。\nB：2週間の 予定です。\nA：春休みは 何か 予定が ありますか。\nB：沖縄へ 行く つもりです。\nA：いいですね。どのくらいですか。\nB：5日の 予定です。', 'Kỳ nghỉ hè bạn có dự định gì không?\nMình định đi du lịch Hokkaido.\nThích nhỉ. Bao lâu vậy?\nDự kiến là 10 ngày.\nKỳ nghỉ đông bạn có dự định gì không?\nMình định về nước.\nThích nhỉ. Bao lâu vậy?\nDự kiến là hai tuần.\nKỳ nghỉ xuân bạn có dự định gì không?\nMình định đi Okinawa.\nThích nhỉ. Bao lâu vậy?\nDự kiến là năm ngày.', 7),
(3002562, 3000601, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002563, 3000602, 'READING', NULL, 'Luyện tập', 'Bài có 10 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002564, 3000603, 'READING', NULL, 'Văn mẫu 文型', 'いっしょに 行こう。\n将来 自分の 会社を 作ろうと 思って います。\n来月 車を 買う つもりです。', 'Cùng đi nào!\nTrong tương lai, tôi định thành lập công ty riêng.\nTháng sau tôi định mua ô tô.', 1),
(3002565, 3000603, 'READING', NULL, 'Ví dụ 例文', '疲れたね。ちょっと 休まない？\n…うん、そう しよう。\nお正月は 何を しますか。\n…家族と 温泉に 行こうと 思って います。\nレポートは もう できましたか。\n…いいえ、まだ 書いて いません。金曜日までに まとめようと 思って います。\n国へ 帰っても、日本語の 勉強を 続けますか。\n…はい、続ける つもりです。\n夏休みは 国へ 帰らないんですか。\n…ええ。大学院の 試験を 受けますから、ことしは 帰らない つもりです。\nあしたから ニューヨークへ 出張します。\n…そうですか。いつ 帰りますか。\n来週の 金曜日に 帰る 予定です。', 'Mệt rồi nhỉ. Nghỉ một chút nhé?\n…Ừ, nghỉ thôi.\nDịp năm mới bạn sẽ làm gì?\n…Tôi định đi suối nước nóng cùng gia đình.\nBạn đã làm xong báo cáo chưa?\n…Chưa, tôi vẫn chưa viết. Tôi định hoàn thành báo cáo chậm nhất vào thứ sáu.\nDù về nước, bạn vẫn tiếp tục học tiếng Nhật chứ?\n…Có, tôi định tiếp tục học.\nNghỉ hè bạn không về nước à?\n…Vâng. Vì sẽ thi vào cao học nên năm nay tôi định không về.\nTừ ngày mai tôi sẽ đi công tác ở New York.\n…Thế à? Khi nào bạn về?\nTheo lịch, tôi sẽ về vào thứ sáu tuần sau.', 2);
INSERT INTO content_item (id, section_id, content_type, grammar_point_id, title, content, translated_text, order_index) VALUES
(3002566, 3000603, 'READING', NULL, 'Luyện tập A – 1', '買います\n買おう\n歩きます\n歩こう\n急ぎます\n急ごう\n直します\n直そう\n待ちます\n待とう\n遊びます\n遊ぼう\n休みます\n休もう\n乗ります\n乗ろう\n変えます\n変えよう\n覚えます\n覚えよう\n見ます\n見よう\n来ます\n来よう\nします\nしよう\n休憩します\n休憩しよう', 'mua\nmua nhé\nđi bộ\nđi bộ nhé\nvội\nnhanh lên nhé\nsửa\nsửa nhé\nđợi\nđợi nhé\nchơi\nchơi nhé\nnghỉ\nnghỉ nhé\nlên xe\nlên xe nhé\nthay đổi\nthay đổi nhé\nghi nhớ\nghi nhớ nhé\nxem\nxem nhé\nđến\nđến nhé\nlàm\nlàm nhé\nnghỉ giải lao\nnghỉ giải lao nhé', 3),
(3002567, 3000603, 'READING', NULL, 'Luyện tập A – 2', '買い物に 行こう。\n公園を 散歩しよう。', 'Đi mua sắm nào!\nĐi dạo công viên nào!', 4),
(3002568, 3000603, 'READING', NULL, 'Luyện tập A – 3', '外国で 働こうと 思って います。\n外国で 仕事を 見つけようと 思って います。\n外国で 勉強しようと 思って います。', 'Tôi định làm việc ở nước ngoài.\nTôi định tìm việc ở nước ngoài.\nTôi định học ở nước ngoài.', 5),
(3002569, 3000603, 'READING', NULL, 'Luyện tập A – 4', 'レポートは まだ まとめて いません。\nレポートは まだ 出して いません。', 'Tôi vẫn chưa hoàn thành báo cáo.\nTôi vẫn chưa nộp báo cáo.', 6),
(3002570, 3000603, 'READING', NULL, 'Luyện tập A – 5', 'わたしは ずっと 日本に 住む つもりです。\nわたしは 将来 大学で 研究する つもりです。\nわたしは 国へ 帰らない つもりです。\nわたしは 来年の 試験を 受けない つもりです。', 'Tôi định sống lâu dài ở Nhật.\nTrong tương lai, tôi định nghiên cứu ở trường đại học.\nTôi định không về nước.\nTôi định không dự kỳ thi năm sau.', 7),
(3002571, 3000603, 'READING', NULL, 'Luyện tập A – 6', '部長は 支店へ 行く 予定です。\n飛行機は 11時に 着く 予定です。\n来週は 出張の 予定です。\n午後は 会議の 予定です。', 'Theo lịch, trưởng phòng sẽ đến chi nhánh.\nMáy bay dự kiến đến lúc 11 giờ.\nTheo lịch, tuần sau tôi sẽ đi công tác.\nTheo lịch, buổi chiều sẽ có cuộc họp.', 8),
(3002572, 3000604, 'READING', NULL, 'Luyện tập', 'Bài có 4 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002573, 3000605, 'READING', NULL, 'intro', 'きょうは1月1日です。\nわたしの家族はみんな毎年1月1日に新年の決意を発表します。', 'Hôm nay là ngày 1 tháng 1.\nHằng năm, vào ngày 1 tháng 1, mọi người trong gia đình tôi đều nói về những quyết tâm của mình trong năm mới.', 1),
(3002574, 3000605, 'READING', NULL, 'torao', '太ると、困るから、食事に気をつけて、運動します。\n去年はジョギングを始めましたが、続けられませんでした。\nことしは50歳になるし、会社で部長になったし、体に気をつけようと思っています。\nお酒もできるだけ飲まないつもりです。', 'Béo lên thì khổ nên tôi sẽ chú ý chuyện ăn uống và tập thể dục.\nNăm ngoái tôi bắt đầu chạy bộ nhưng không duy trì được.\nNăm nay tôi bước sang tuổi 50, lại đã lên làm trưởng phòng ở công ty nên tôi định chú ý giữ gìn sức khỏe.\nTôi cũng định hạn chế uống rượu hết mức có thể.', 2),
(3002575, 3000605, 'READING', NULL, 'nobuko', 'ことしは介護のボランティアを始めようと思っています。\n若いときから介護の仕事をやりたかったんです。\nボランティアをしながら、勉強をして資格も取るつもりです。\n皆さん、応援よろしくお願いします。', 'Năm nay tôi định bắt đầu làm tình nguyện viên chăm sóc người cần hỗ trợ.\nTừ khi còn trẻ tôi đã muốn làm công việc chăm sóc này.\nTôi định vừa làm tình nguyện vừa học để lấy chứng chỉ nữa.\nMong mọi người ủng hộ tôi.', 3),
(3002576, 3000605, 'READING', NULL, 'megumi', 'わたしはアジアの踊りに興味があります。\n特にインドネシアのバリの踊りが好きだから、将来はバリで踊りを研究したいと思っています。\nそれで、ことしからインドネシア語の勉強を始めようと思っています。', 'Con có hứng thú với các điệu múa châu Á.\nĐặc biệt, con thích các điệu múa của Bali ở Indonesia nên trong tương lai con muốn nghiên cứu múa tại Bali.\nVì vậy, con định bắt đầu học tiếng Indonesia từ năm nay.', 4),
(3002577, 3000605, 'READING', NULL, 'tatsuo', 'ことし5年生になるから、学校のスポーツクラブに入れます。\n僕は野球のクラブに入ろうと思っています。\n僕は足も速いし、上手に打てるから、すぐ試合に出られると思います。\nみんな見に来てください。\nそれから去年は宿題をよく忘れたけど、ことしは忘れないつもりです。', 'Năm nay con lên lớp 5 nên có thể vào câu lạc bộ thể thao ở trường.\nCon định vào câu lạc bộ bóng chày.\nCon chạy nhanh, lại đánh bóng giỏi nên con nghĩ mình sẽ sớm được ra sân thi đấu.\nCả nhà đến xem con nhé.\nVới lại, năm ngoái con hay quên bài tập về nhà nhưng năm nay con sẽ không quên nữa.', 5),
(3002578, 3000605, 'READING', NULL, 'x-story-1', '昔、神様が動物たちに言った。\n「1月1日の朝、わたしのうちへ早く来たら、1番目から12番目のものに大切な仕事をあげよう。」\nネコは神様の話がよく聞こえなかったから、ネズミに「いつ？」と聞いた。\nネズミは「2日だ」とうそを言った。', 'Ngày xưa, một vị thần nói với các con vật.\n“Sáng ngày 1 tháng 1, hãy đến nhà ta sớm, ta sẽ giao một công việc quan trọng cho những con đến từ thứ nhất đến thứ mười hai.”\nMèo không nghe rõ lời vị thần nên hỏi Chuột: “Khi nào?”\nChuột nói dối: “Ngày mùng 2.”', 6),
(3002579, 3000605, 'READING', NULL, 'x-story-2', 'ウシが最初に神様のうちに着いたが、ウシの背中にはネズミがこっそり乗っていた。\nドアが開いたときに、ネズミが飛び降りて、1番になった。\nそして2番から12番までの動物が決まった。\n神様が言った。\n「ことしはネズミの年だ。\nネズミの仕事はことし生まれる人たちを守ることだ。\n来年はウシ年で、ウシの仕事は来年生まれる人たちを守ることだ。\n毎年順番に仕事をして、12番まで仕事をしたら、またネズミの年になる。」', 'Bò đến nhà vị thần đầu tiên, nhưng Chuột đã lén ngồi trên lưng Bò.\nKhi cửa mở, Chuột nhảy xuống và giành vị trí thứ nhất.\nSau đó, các con vật ở vị trí từ thứ hai đến thứ mười hai cũng được xác định.\nVị thần nói.\n“Năm nay là năm của Chuột.\nCông việc của Chuột là bảo vệ những người sinh ra trong năm nay.\nNăm sau là năm Sửu, và công việc của Bò là bảo vệ những người sinh ra trong năm sau.\nMỗi năm các con sẽ lần lượt làm công việc này, khi làm đến con thứ mười hai thì lại đến năm của Chuột.”', 7),
(3002580, 3000605, 'READING', NULL, 'x-story-3', 'このときから毎年ネズミ年、ウシ年などと言う。\nネコは遅れたから、仕事ももらえなかったし、ネコ年もない。\nそれで、ネコはネズミを見ると、追いかける。\n今も怒っているのだ。', 'Từ đó, mỗi năm được gọi là năm Tý, năm Sửu, v.v.\nMèo đến muộn nên không được giao việc, và cũng không có năm Mèo.\nVì vậy, cứ thấy chuột là mèo đuổi theo.\nĐến bây giờ mèo vẫn còn giận.', 8),
(3002581, 3000605, 'READING', NULL, 'x-years', '～年\n生まれた年\nネズミ\n1960\n1972\n1984\n1996\n2008\nウシ\n1961\n1973\n1985\n1997\n2009\nトラ\n1962\n1974\n1986\n1998\n2010\nウサギ\n1963\n1975\n1987\n1999\n2011\nタツ\n1964\n1976\n1988\n2000\n2012\nヘビ\n1965\n1977\n1989\n2001\n2013\nウマ\n1966\n1978\n1990\n2002\n2014\nヒツジ\n1967\n1979\n1991\n2003\n2015\nサル\n1968\n1980\n1992\n2004\n2016\nトリ\n1969\n1981\n1993\n2005\n2017\nイヌ\n1970\n1982\n1994\n2006\n2018\nイノシシ\n1971\n1983\n1995\n2007\n2019', 'Năm con ～\nNăm sinh\nTý – chuột\nSửu – bò\nDần – hổ\nMão – thỏ\nThìn – rồng\nTỵ – rắn\nNgọ – ngựa\nMùi – cừu\nThân – khỉ\nDậu – gà\nTuất – chó\nHợi – lợn rừng', 9),
(3002582, 3000606, 'READING', NULL, 'Luyện tập', 'Bài có 8 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002583, 3000607, 'LISTENING', NULL, '1. Rủ nhau đi triển lãm男の 人と 女の 人は 展覧会に 行きます。何を しますか。Người nam và người nữ đi xem triển lãm. Họ sẽ làm gì?', 'A：ピカソの展覧会、もう見た?\nB：ううん、まだ。\nA：じゃ、見に行かない?\nB：今から?\nA：うん、行こうよ。\nB：いいよ。\nA：うわあ、人が多いね。\nB：よく見えないから、もっと前の方へ行こうよ。\nA：無理よ。人が たくさんいるから、行けないよ。\nB：じゃ、しかたがないね。 ここから見よう。\nA：ちょっと疲れたね。\nB：うん、ちょっと休憩しよう。\nA：あ、あそこに いすが あるけど、\nA：みんな、座ってる。\nB：じゃ、全部見て しまおうよ。\nA：うん、それから、休もうね。\nA：ああ、すごかったね。\nB：うん、ピカソも、人も。\nA：ちょっと何か飲まない?\nB：じゃ、どこかに入ろう。\nA：うん。あ、あの店は?\nB：いいよ。', 'Triển lãm tranh Picasso, bạn đã xem chưa?\nChưa, vẫn chưa.\nVậy cùng đi xem không?\nBây giờ luôn à?\nỪ, đi nhé.\nĐược đấy.\nÔi, đông người quá nhỉ.\nTôi không nhìn rõ, mình tiến lên phía trước nữa đi.\nKhông được đâu. Đông người quá, không lên được.\nVậy đành chịu thôi nhỉ. Mình đứng đây xem vậy.\nHơi mệt nhỉ.\nỪ, mình nghỉ một chút đi.\nÀ, đằng kia có ghế, nhưng…\nGhế nào cũng có người ngồi rồi.\nVậy mình xem cho hết đi.\nỪ, rồi mình nghỉ nhé.\nÀ, tuyệt thật nhỉ.\nỪ, cả tranh Picasso lẫn số người đến xem đều ghê thật.\nUống một chút gì nhé?\nVậy mình vào quán nào đó đi.\nỪ. À, quán kia thì sao?\nĐược đấy.', 1),
(3002584, 3000607, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002585, 3000607, 'LISTENING', NULL, '2. Chuẩn bị chuyển công tác小山さんは 来月転勤します。これから どうしますか。Anh Koyama sẽ chuyển công tác vào tháng tới. Anh ấy dự định làm gì?', 'いらっしゃいませ。乾杯！\nA：小山さん、最近忙しいですか。\nB：ええ……実は、来月東京に転勤するんです。\nA：えっ、じゃ、引っ越しですか。\nA：大変ですね。\nB：いいえ、1年だけですから、\nB：一人で行こうと思っているんです。\nB：家族は こちらに残るんです。\nA：住む所は どうするんですか。\nB：会社が準備して くれます。\nA：でも、いろいろ買わなければならないでしょう?\nB：ええ。ですから、家具が付いているアパートを探してもらおうと思っているんです。\nA：それは便利ですね。\nA：食事が大変ですね。\nB：ええ。\nB：でも、毎日外で食べたら、お金も かかるし、体にも よくないし……。\nB：それで、簡単な食事だったら、自分で作ろうと思っているんです。\nA：へえ、そうですか。\nA：料理を習いに行くんですか。\nB：いいえ、本を買って、自分で勉強しようと思っています。\nA：休みの日は どうするんですか。\nA：一人で寂しくないですか。\nB：時々大阪へ帰りますけど、\nB：実は スペイン語を勉強しようと思っています。\nA：へえ、自分で勉強するんですか。\nB：いいえ。ちょっと調べたんですが、\nB：町には いろいろな教室が あるんですよ。\nB：それで、スペイン語教室に行こうと思っているんです。\nA：そうですか。\nA：じゃ、いつか スペインを旅行できますね。\nB：ええ。\nB：それに、将来、南アメリカへ ボランティアに行きたいと思っているんです。\nA：へえ、すごいですね。', 'Xin chào quý khách. Cạn ly!\nAnh Koyama, gần đây anh bận lắm phải không?\nVâng… Thật ra tháng tới tôi sẽ chuyển công tác đến Tokyo.\nƠ, vậy anh sẽ chuyển nhà à?\nVất vả nhỉ.\nKhông, vì chỉ đi một năm thôi.\nTôi dự định sẽ đi một mình.\nGia đình tôi sẽ ở lại đây.\nChỗ ở thì anh tính thế nào?\nCông ty sẽ chuẩn bị cho tôi.\nThế nhưng cũng phải mua nhiều thứ phải không?\nVâng, nên tôi định nhờ tìm căn hộ có sẵn nội thất.\nThế thì tiện nhỉ.\nChuyện ăn uống sẽ vất vả nhỉ.\nVâng.\nNhưng ngày nào cũng ăn ngoài thì vừa tốn tiền, vừa không tốt cho sức khỏe…\nVì vậy, nếu là bữa ăn đơn giản thì tôi định tự nấu.\nỒ, vậy à.\nAnh định đi học nấu ăn à?\nKhông, tôi định mua sách rồi tự học.\nNgày nghỉ thì anh định làm gì?\nMột mình không cô đơn sao?\nThỉnh thoảng tôi sẽ về Osaka, nhưng…\nThú thật là tôi định học tiếng Tây Ban Nha.\nỒ, anh tự học à?\nKhông, tôi có tìm hiểu sơ qua rồi.\nCó nhiều lớp học ở thành phố.\nVì thế, tôi dự định tham gia lớp học tiếng Tây Ban Nha.\nVậy à.\nVậy sau này anh có thể đi du lịch Tây Ban Nha nhỉ.\nVâng.\nHơn nữa, sau này tôi muốn sang Nam Mỹ làm tình nguyện.\nỒ, anh giỏi thật đấy.', 3),
(3002586, 3000607, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002587, 3000607, 'LISTENING', NULL, '3. Ước mơ trong tương lai将来の 夢について 聞きました。山本君と 坂口さんの 将来の 夢を 書いて ください。Hãy ghi lại ước mơ tương lai của Yamamoto và Sakaguchi', 'A：山本君は高校を出てから、大学で何を勉強するつもりですか。\nB：あのう、僕は大学へは行かないつもりです。\nA：どうしてですか。\nB：僕は料理が好きなんです。\nB：すばらしい料理人に なりたいと思っています。\nB：それで、まず料理学校に入ろうと思っています。\nB：それから、フランスや イタリアへ行って、\nB：有名な レストランで働きたいんです。\nA：ずっとヨーロッパに住むつもりですか。\nB：いいえ、日本へ帰って、40歳までに自分の店を持つつもりです。\nB：そして、みんなに僕の おいしい料理を食べて もらいたいです。\nA：そうですか。\nA：山本君の料理、わたしも いつか食べたいです。\nA：頑張って ください。\nB：はい、ありがとうございます。\nA：坂口さんは大学へ行こうと思っていますか。\nB：はい。\nB：大学院まで行く つもりです。\nB：わたしは動物学を勉強して、医者に なるつもりなんです。\nA：動物の お医者さんですか。\nB：ええ。\nB：そして、動物の病院と研究所を作ろうと思っています。\nA：動物の研究所?\nB：ええ、子どもの ときから、動物の ことばを知りたいと思っていました。\nB：いろいろな動物を飼って、動物の ことばを研究するつもりです。\nA：おもしろい研究ですね。\nB：ええ。\nB：動物と話せたら、きっと楽しいですよ。\nA：すばらしい夢ですね。', 'Yamamoto, sau khi tốt nghiệp cấp ba, em định học gì ở đại học?\nÀ… em định không học đại học ạ.\nTại sao lại thế?\nEm thích nấu ăn.\nEm muốn trở thành đầu bếp giỏi.\nVì thế, trước hết em định vào trường dạy nấu ăn.\nSau đó, em muốn sang những nước như Pháp hay Ý…\nđể làm việc ở một nhà hàng nổi tiếng.\nEm định sống mãi ở châu Âu à?\nKhông ạ, em định về Nhật và mở quán riêng chậm nhất là năm 40 tuổi.\nEm muốn mọi người được thưởng thức những món ngon do mình nấu.\nVậy à.\nYamamoto, tôi cũng muốn có dịp được ăn món do em nấu.\nEm cố gắng lên nhé.\nVâng, em cảm ơn ạ.\nSakaguchi, em định học đại học chứ?\nVâng.\nEm định học lên đến cao học.\nEm định học động vật học rồi trở thành bác sĩ thú y.\nBác sĩ chữa cho động vật à?\nVâng.\nSau đó, em định lập bệnh viện và viện nghiên cứu về động vật.\nViện nghiên cứu về động vật à?\nVâng, từ nhỏ em đã muốn hiểu ngôn ngữ của động vật.\nEm định nuôi nhiều loài động vật để nghiên cứu ngôn ngữ của chúng.\nNghiên cứu thú vị nhỉ.\nVâng.\nNếu có thể nói chuyện với động vật thì chắc chắn sẽ vui đấy.\nƯớc mơ thật tuyệt vời nhỉ.', 5),
(3002588, 3000607, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002589, 3000607, 'LISTENING', NULL, '4. Hẹn ngày xem Kabukiミラーさんは 手帳を 見ながら 話して います。いつ 歌舞伎に 行きますか。Anh Miller vừa xem sổ tay vừa bàn lịch hẹn. Hai người sẽ đi xem Kabuki ngày nào?', 'A：ミラーさん、一度歌舞伎が見たいと言いましたね。\nA：今、おもしろい歌舞伎を やっているから、見に行きませんか。\nB：いいですね。\nB：ぜひ、行きたいです。\nB：いつまで やっているんですか。\nA：来週の日曜日までですけど、……。\nA：今度の土曜日は どうですか。\nB：土曜日は仕事の予定が あります。\nB：あのう、今週の日曜日は どうですか。\nA：すみません。\nA：日曜日は ちょっと友達と約束が あるんです。\nB：じゃ、月曜日は?\nB：わたしは土曜日仕事を するから、月曜日に休みを取る予定です。\nA：月曜日は歌舞伎が休みなんです。\nB：そうですか。\nA：来週の週末は どうですか。\nB：そうですね。\nB：じゃ、……。', 'Anh Miller từng nói muốn xem Kabuki một lần nhỉ.\nHiện có vở Kabuki hay lắm, anh đi xem cùng tôi nhé?\nĐược đấy nhỉ.\nTôi rất muốn đi.\nVở đó diễn đến khi nào?\nĐến chủ nhật tuần sau…\nThứ bảy này thì sao?\nThứ bảy này tôi có lịch làm việc.\nÀ… chủ nhật tuần này thì sao?\nXin lỗi.\nChủ nhật này tôi có hẹn với bạn.\nVậy thứ hai thì sao?\nVì tôi có làm việc ngày thứ bảy nên dự định xin nghỉ phép vào ngày thứ hai.\nThứ hai nhà hát Kabuki nghỉ.\nVậy à.\nCuối tuần sau thì sao?\nĐể tôi xem nào.\nVậy thì…', 7),
(3002590, 3000607, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002591, 3000608, 'READING', NULL, 'Luyện tập', 'Bài có 28 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002592, 3000609, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo ý kiến hoặc dự định của bạn. Xem câu trả lời mẫu sau khi làm.\nはい、続ける つもりです。\n買い物に 行こうと 思って います。\nいいえ、まだ 勉強して いません。\nはい、友達と 映画を 見に行く 予定です。', NULL, 1),
(3002593, 3000609, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo ý kiến hoặc dự định của bạn. Xem câu trả lời mẫu sau khi làm.\n「みんなの 日本語 初級Ⅱ」が 終わってからも 日本語の 勉強を 続けますか。\n今度の 日曜日は 何を しますか。\n第３２課は もう 勉強しましたか。\nあしたは 何か 予定が ありますか。', NULL, 2),
(3002594, 3000609, 'READING', NULL, '2. Nghe: đúng hay sai', 'Nghe hội thoại và câu ★. Chọn ○ nếu câu ★ đúng với hội thoại, chọn × nếu sai.\n女：シュミットさん、連休は どこか 旅行に 行きますか。\n男：いいえ。息子と 近くの 池で 釣りを しようと 思って います。\n男：渡辺さんは？\n女：わたしも うちに いる つもりです。\n女：連休は 人も 多いし、ホテルも 高いですからね。\n★：女の 人は 連休は どこも 行きません。\n女：ミラーさん、日本語の 試験は どうでしたか。\n男：難しかったです。\n女：そうですか。\n男：でも、来年 もう 一度 受けようと 思って いるんです。\n女：そうですか。来年は きっと 大丈夫ですよ。\n★：ミラーさんは 来年も 日本語の 試験を 受けます。\n女：タワポンさん、レポートは もう まとめましたか。\n男：いいえ、まだなんです。\n女：あさってまでですよ。急がないと……。\n男：はい。今晩 書く つもりです。\n★：タワポンさんは まだレポートを まとめていません。\n男：田中さん、来週 さくら大学へ 行きますか。\n女：ええ、水曜日に 行く 予定です。\n男：じゃ、すみませんが、ワット先生に この 本を 返して いただけませんか。\n女：いいですよ。\n★：女の 人は 来週 ワット先生に 会います。\n女：サッカーの 試合は 何時から？\n男：７時から。\n男：まだ 時間が あるから、どこかで 食事しない？\n女：わたし、ちょっと 買い物したいんだけど……。\n男：いいよ。じゃ、試合が 終わってから、食べよう。\n★：男の 人と 女の 人は サッカーの 試合のまえに、食事します。', NULL, 3),
(3002595, 3000609, 'READING', NULL, '7. Trở về quê', 'Đọc đoạn văn rồi trả lời câu hỏi. Đối chiếu câu trả lời của bạn với mẫu.\nわたしは 九州の 小さい 村で 生まれた。高校を 卒業して、東京へ 来てから、もう１０年に なる。今 自動車会社で 働いて いる。\n田舎に いた ときは、映画館も ないし、レストランも ないし、田舎の 生活は 嫌だと 思った。でも、最近 疲れた ときや 寂しい とき、よく 田舎の 青い 空や 緑の 山を 思い出す。目を 閉じると、友達と 泳いだ 川の 音が 聞こえる。\nわたしは 来年の 春 会社を やめて、田舎へ 帰る つもりだ。そして、都会の 子どもたちが 自由に 遊べる 「山の 学校」を いつか 作ろう と 思って いる。\n東京に 住んで います。\n映画館も ないし、レストランも ないからです。\nいいえ、嫌では ありません。\n都会の 子どもたちが 自由に 遊べる「山の 学校」を 作ろうと 思って います。', NULL, 4),
(3002596, 3000609, 'READING', NULL, '8. Ước mơ của bạn', 'Viết về ước mơ và dự định tương lai của bạn.\nわたしの 夢は 日本語の 先生に なる ことです。ベトナムで 日本語を 教えようと 思って います。', NULL, 5),
(3002597, 3000610, 'READING', NULL, 'Luyện tập', 'Bài có 21 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002598, 3000611, 'READING', NULL, '5. Dự định đi du lịch', '〜（よ）うと 思っています／〜つもりです Dựa vào tranh gợi ý, viết về chuyến du lịch bạn dự định thực hiện, dùng 〜（よ）うと思っています và 〜つもりです theo ví dụ.\n夏休みに 友達と 沖縄へ 行こうと 思っています。\n飛行機で 行く つもりです。\n海で 泳いだり、写真を 撮ったり しようと 思っています。', NULL, 1),
(3002599, 3000611, 'READING', NULL, '6. Kế hoạch nghỉ hè', '〜予定です Dựa vào lịch, hoàn thành các câu nói về kế hoạch nghỉ hè. Theo ví dụ 1, dùng động từ thể từ điển + 予定です, theo ví dụ 2, dùng danh từ + の予定です.\n８月３日は 友達と 富士山に 登る 予定です。\n８月７日は 小川さんと ビール工場を 見学する 予定です。', NULL, 2),
(3002600, 3000611, 'READING', NULL, '7. Ước mơ tương lai', '辞書形ことです／意向形と 思っています Viết về ước mơ tương lai, dùng các mẫu 〜たいです・〜たいと思っています・夢は〜ことです・〜（よ）うと思っています.\nわたしの 将来の 夢は 日本語の 先生に なる ことです。\n大学を 卒業したら、ベトナムへ 帰りたいと 思っています。\nハノイの 学校で 働きたいです。\nこれからも 日本語を 勉強しようと 思っています。', NULL, 3),
(3002601, 3000611, 'READING', NULL, '9. Những việc vẫn chưa làm', 'まだ〜ていません Viết về những việc bạn vẫn chưa làm, dùng まだ〜ていません. Có thể dựa vào ví dụ và tranh gợi ý để nêu thêm dự định hoặc việc đang chuẩn bị.\nわたしは まだ 日本で スキーを して いません。\n冬休みに 友達と 行こうと 思っています。\nそれで 今 お金を 貯めて います。', NULL, 4),
(3002602, 3000612, 'READING', NULL, 'Luyện tập', 'Bài có 19 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002603, 3000613, 'READING', NULL, 'Danh sách kanji', '休 (HƯU) — nghỉ, nghỉ ngơi — きゅう\n憩 (KHẾ) — nghỉ ngơi, nghỉ giải lao — けい\n連 (LIÊN) — liên tiếp, nối liền; dẫn theo — れん\n取 (THỦ) — lấy, cầm; giành được — と\n続 (TỤC) — tiếp tục, nối tiếp — つづ\n見 (KIẾN) — nhìn, xem — み\n受 (THỤ) — nhận, tiếp nhận; dự (thi) — う\n申 (THÂN) — nói (khiêm nhường); xin, đăng ký — もう\n込 (NHẬP) — đông đúc, chật chội; cho vào — こ\n作 (TÁC) — làm, sản xuất, sáng tác, nấu nướng — さく\n文 (VĂN) — câu, văn, chữ; văn hóa, văn học — ぶん\n発 (PHÁT) — phát ra; xuất phát — はつ\n表 (BIỂU) — bề mặt, mặt ngoài; bảng biểu; biểu hiện — ひょう\n展 (TRIỂN) — mở rộng, phát triển; triển lãm — てん\n覧 (LÃM) — xem, ngắm; xem qua — らん\n会 (HỘI) — họp, gặp gỡ — かい\n式 (THỨC) — nghi lễ, lễ; kiểu, hình thức; công thức — しき\n結 (KẾT) — buộc, thắt; kết, kết hợp; kết thúc — けつ\n婚 (HÔN) — hôn nhân, kết hôn — こん\n葬 (TÁNG) — chôn cất, mai táng — そう\n本 (BẢN) — sách; gốc — ほん\n社 (XÃ) — công ty — しゃ\n支 (CHI) — chống đỡ, hỗ trợ; chi nhánh; chi trả — し\n店 (ĐIẾM) — cửa hàng — てん\n大 (ĐẠI) — to lớn, rộng lớn; rất — だい\n学 (HỌC) — học tập — がく\n院 (VIỆN) — viện; cơ sở như bệnh viện — いん\n教 (GIÁO) — dạy; tôn giáo — きょう\n動 (ĐỘNG) — chuyển động — どう\n物 (VẬT) — đồ vật — ぶつ\n園 (VIÊN) — vườn, công viên — えん\n温 (ÔN) — ấm, ấm áp; nhiệt độ — おん\n泉 (TUYỀN) — suối, nguồn nước — せん\n号 (HIỆU, HÀO) — số, số hiệu; ký hiệu — ごう\n方 (PHƯƠNG) — cách, phương pháp; phương hướng; người (cách nói lịch sự) — ほう\n子 (TỬ) — con; trẻ em — こ\n新 (TÂN) — mới — しん\n神 (THẦN) — thần, thần linh; tinh thần — こうべ\n戸 (HỘ) — cửa; hộ, nhà — こうべ', NULL, 1),
(3002604, 3000614, 'READING', NULL, '使い方 – Câu ví dụ', 'この飛行機は8時にケネディ空港に着く予定です。\n自動車の運転の試験を受けます。\n将来、動物園で働きたいです。\n大学を決める前に、自分が将来したいことをよく考えます。\n田中さんのお子さんは大学院で勉強しています。\n東京の本社へ転勤になりました。東京の西の方で家を見つけました。来週、家族を連れて行く予定です。\n家に帰るとすぐ、顔と手と足を洗います。', NULL, 1),
(3002605, 3000614, 'READING', NULL, '読み物 – Bài đọc · 将来の夢 1', 'わたしの家の近くに空港があります。子どものとき、毎日、飛行機を見ていました。あんなに大きくて重い飛行機が、空を飛んでいる……どうして、と思いながら。\n飛行機がだんだん高く、高く、空へ……。ワクワクしました。空を見ながら思いました。\nいつか、あの空の中の景色が見たい。\nそして将来、飛行機のパイロットになろうと決めました。', NULL, 2),
(3002606, 3000614, 'READING', NULL, '読み物 – Bài đọc · 将来の夢 2', 'Q：わたしは高校3年生です。将来、動物園の仕事をしたいです。今、動物園で仕事をしている方はどうやってその仕事を見つけましたか。教えてください。\nA：こんにちは。わたしは今、動物園で働いています。大学で生物学を勉強しました。北海道の牧場でアルバイトもしました。それから、国や市の動物園にたくさん手紙を書きました。その中のひとつの動物園から連絡がありました。そして、試験を受けて、今この仕事をしています。\n動物園の仕事は大変です。時間も体力も要ります。でも、あなたの夢ですから、よく考えて、よく勉強して、将来を決めてください。応援しています。', NULL, 3),
(3002607, 3000615, 'READING', NULL, 'Luyện tập', 'Bài có 12 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002608, 3000616, 'READING', NULL, 'Luyện tập', 'Bài có 6 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002609, 3000617, 'READING', NULL, 'Danh sách từ vựng', 'Bài có 48 từ vựng.', NULL, 1),
(3002610, 3000619, 'GRAMMAR', 3000212, 'Ví dụ 1', '毎日 運動した ほうが いいです。', 'Bạn nên vận động hằng ngày.', 1),
(3002611, 3000619, 'GRAMMAR', 3000212, 'Ví dụ 2', '熱が あるんです。', 'Tôi bị sốt.', 2),
(3002612, 3000619, 'GRAMMAR', 3000212, 'Ví dụ 3', '…じゃ、おふろに 入らない ほうが いいですよ。', '…Vậy thì bạn không nên tắm bồn.', 3),
(3002613, 3000619, 'GRAMMAR', 3000213, 'Ví dụ 4', 'あしたは 雨が 降るでしょう。', 'Ngày mai chắc trời sẽ mưa.', 4),
(3002614, 3000619, 'GRAMMAR', 3000213, 'Ví dụ 5', 'タワポンさんは 合格するでしょうか。', 'Liệu anh Thawaphon có thi đỗ không nhỉ?', 5),
(3002615, 3000619, 'GRAMMAR', 3000213, 'Ví dụ 6', '…きっと 合格するでしょう。', '…Chắc hẳn anh ấy sẽ đỗ.', 6),
(3002616, 3000619, 'GRAMMAR', 3000213, 'Ví dụ 7', '日曜日の 公園は にぎやかでしょう。', 'Công viên vào chủ nhật chắc sẽ nhộn nhịp.', 7),
(3002617, 3000619, 'GRAMMAR', 3000214, 'Ví dụ 8', 'あの 人は 先生かもしれません。', 'Người kia có thể là giáo viên.', 8),
(3002618, 3000619, 'GRAMMAR', 3000214, 'Ví dụ 9', '財布を うちに 忘れたかもしれません。', 'Có thể tôi đã để quên ví ở nhà.', 9),
(3002619, 3000619, 'GRAMMAR', 3000214, 'Ví dụ 10', '銀行は 込んで いるかもしれませんから、早く 行きましょう。', 'Ngân hàng có thể đông, nên chúng ta hãy đi sớm.', 10),
(3002620, 3000619, 'GRAMMAR', 3000215, 'Ví dụ 11', 'エンジンの 音が おかしいんですが。', 'Tiếng động cơ nghe có vẻ bất thường.', 11),
(3002621, 3000619, 'GRAMMAR', 3000215, 'Ví dụ 12', '…故障かもしれません。ちょっと 調べましょう。', '…Có thể máy bị hỏng. Để tôi kiểm tra một chút.', 12),
(3002622, 3000619, 'GRAMMAR', 3000215, 'Ví dụ 13', 'わたしが 荷物を 持ちましょう。', 'Để tôi mang hành lý cho.', 13),
(3002623, 3000619, 'GRAMMAR', 3000216, 'Ví dụ 14', '駅まで 30分で 行けますか。', 'Có thể đến ga trong 30 phút không?', 14),
(3002624, 3000619, 'GRAMMAR', 3000216, 'Ví dụ 15', '3万円で パソコンが 買えますか。', 'Với 30.000 yên có mua được máy tính không?', 15),
(3002625, 3000619, 'GRAMMAR', 3000216, 'Ví dụ 16', 'この 料理は 10分で 作れます。', 'Món này có thể làm trong 10 phút.', 16),
(3002626, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 17', '何か 心配な ことが あるんですか。', 'Bạn đang lo chuyện gì à?', 17),
(3002627, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 18', 'どこか いい ところ、ありますか。', 'Có nơi nào tốt không?', 18),
(3002628, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 19', '何か 冷たい ものが 飲みたいです。', 'Tôi muốn uống thứ gì đó lạnh.', 19),
(3002629, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 20', '毎日 1時間ぐらい 運動した ほうが いいです。', 'Mỗi ngày nên vận động khoảng một giờ.', 20),
(3002630, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 21', '年を 取ったら、車は 運転しない ほうが いいです。', 'Khi có tuổi thì không nên lái xe.', 21),
(3002631, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 22', '疲れた ときは、早く 寝た ほうが いいです。', 'Khi mệt thì nên đi ngủ sớm.', 22),
(3002632, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 23', '夏休みは 早く ホテルを 予約した ほうが いいです。', 'Vào kỳ nghỉ hè, nên đặt khách sạn sớm.', 23),
(3002633, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 24', '暗い ところで 本を 読まない ほうが いいです。', 'Không nên đọc sách ở chỗ tối.', 24),
(3002634, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 25', '夜 遅く 一人で 歩かない ほうが いいです。', 'Không nên đi bộ một mình vào đêm khuya.', 25),
(3002635, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 26', 'きのうから せきが 出るんです。', 'Tôi bị ho từ hôm qua.', 26),
(3002636, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 27', '…じゃ、病院へ 行った ほうが いいですよ。', '…Vậy thì bạn nên đi bệnh viện.', 27),
(3002637, 3000619, 'GRAMMAR', 3000217, 'Ví dụ 28', 'やけどを したんです。', 'Tôi bị bỏng.', 28),
(3002638, 3000620, 'READING', NULL, 'Luyện tập', 'Bài có 9 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002639, 3000621, 'LISTENING', NULL, '無理を しない ほうが いいですよ – Ông không nên làm việc quá sức đâu', '小川：シュミットさん、元気が ありませんね。\n小川：どう したんですか。\nシュミット：最近 体の 調子が よくないんです。\nシュミット：時々 頭や 胃が 痛く なるんですよ。\n小川：それは いけませんね。\n小川：仕事が 忙しいんですか。\nシュミット：ええ、残業が 多いんです。\n小川：ストレスかもしれませんね。\n小川：一度 病院で 診て もらった ほうが いいですよ。\nシュミット：ええ、そうですね。\n小川：無理を しない ほうが いいですよ。\nシュミット：ええ、今の 仕事が 終わったら、休みを 取ろうと 思って います。\n小川：それは いいですね。', 'Ông Schmidt, trông ông có vẻ mệt nhỉ.\nCó chuyện gì vậy?\nDạo này tôi thấy không khỏe trong người.\nThỉnh thoảng tôi bị đau đầu, đau dạ dày đấy.\nThế thì không ổn rồi.\nÔng bận công việc lắm à?\nVâng, tôi phải tăng ca nhiều.\nCó thể là do căng thẳng nhỉ.\nÔng nên đến bệnh viện khám một lần xem sao.\nVâng, anh nói phải.\nÔng không nên làm việc quá sức đâu.\nVâng, tôi định xin nghỉ khi xong công việc hiện tại.\nThế thì tốt quá.', 1),
(3002640, 3000621, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002641, 3000621, 'LISTENING', NULL, 'Hỏi thăm và đưa ra lời khuyên', 'A：どう したんですか。\nB：やけどを したんです。\nA：じゃ、すぐ 水道の 水で 冷やした ほうが いいですよ。\nB：ええ、そうします。\nA：どう したんですか。\nB：熱が あるんです。\nA：じゃ、うちへ 帰って 休んだ ほうが いいですよ。\nB：ええ、そうします。\nA：どう したんですか。\nB：頭が 痛いんです。\nA：じゃ、薬を 飲んだ ほうが いいですよ。\nB：ええ、そうします。', 'Có chuyện gì vậy?\nTôi bị bỏng.\nVậy bạn nên làm mát ngay bằng nước máy.\nVâng, tôi sẽ làm như vậy.\nCó chuyện gì vậy?\nTôi bị sốt.\nVậy bạn nên về nhà nghỉ ngơi.\nVâng, tôi sẽ làm như vậy.\nCó chuyện gì vậy?\nTôi bị đau đầu.\nVậy bạn nên uống thuốc.\nVâng, tôi sẽ làm như vậy.', 3),
(3002642, 3000621, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002643, 3000621, 'LISTENING', NULL, 'Dự đoán kết quả và nêu căn cứ', 'A：もうすぐ 入学試験ですね。\nA：タワポンさんは 合格するでしょうか。\nB：よく 勉強して いましたから、きっと 合格するでしょう。\nA：もうすぐ サッカーの 試合ですね。\nA：IMCの チームは 勝つでしょうか。\nB：あんなに 練習して いましたから、きっと 勝つでしょう。\nA：もうすぐ 国際ボランティア会議ですね。\nA：会議は 成功するでしょうか。\nB：6か月前から 準備して いましたから、きっと 成功するでしょう。', 'Sắp đến kỳ thi đầu vào rồi nhỉ.\nLiệu anh Thawaphon có thi đỗ không nhỉ?\nVì anh ấy đã học rất chăm chỉ nên chắc sẽ thi đỗ.\nSắp đến trận bóng đá rồi nhỉ.\nLiệu đội IMC có thắng không nhỉ?\nVì họ đã luyện tập nhiều đến thế nên chắc sẽ thắng.\nSắp đến hội nghị tình nguyện quốc tế rồi nhỉ.\nLiệu hội nghị có thành công không nhỉ?\nVì mọi người đã chuẩn bị từ sáu tháng trước nên chắc sẽ thành công.', 5),
(3002644, 3000621, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002645, 3000621, 'LISTENING', NULL, 'Hỏi kinh nghiệm và khuyên chuẩn bị trước', 'A：京都の 紅葉を 見た ことが ありますか。\nB：ええ。\nA：来週 行こうと 思って いるんですが……。\nB：きれいですよ。\nB：でも、京都は ちょっと 寒いかもしれませんから、セーターを 持って 行った ほうが いいですよ。\nA：そうですか。ありがとう ございます。\nA：歌舞伎を 見た ことが ありますか。\nB：ええ。\nA：来週 行こうと 思って いるんですが……。\nB：きれいですよ。\nB：でも、チケットが すぐ 売れて しまうかもしれませんから、予約した ほうが いいですよ。\nA：そうですか。ありがとう ございます。\nA：吉野山の 桜を 見た ことが ありますか。\nB：ええ。\nA：来週 行こうと 思って いるんですが……。\nB：きれいですよ。\nB：でも、道が 込むかもしれませんから、早く うちを 出た ほうが いいですよ。\nA：そうですか。ありがとう ございます。', 'Bạn đã từng ngắm lá đỏ ở Kyoto chưa?\nRồi.\nTuần sau tôi định đi…\nĐẹp lắm đấy.\nNhưng ở Kyoto có thể hơi lạnh nên bạn nên mang theo áo len.\nVậy à. Cảm ơn bạn.\nBạn đã từng xem kịch Kabuki chưa?\nRồi.\nTuần sau tôi định đi…\nĐẹp lắm đấy.\nNhưng vé có thể hết ngay nên bạn nên đặt trước.\nVậy à. Cảm ơn bạn.\nBạn đã từng ngắm hoa anh đào ở núi Yoshino chưa?\nRồi.\nTuần sau tôi định đi…\nĐẹp lắm đấy.\nNhưng đường có thể đông nên bạn nên ra khỏi nhà sớm.\nVậy à. Cảm ơn bạn.', 7),
(3002646, 3000621, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002647, 3000622, 'READING', NULL, 'Luyện tập', 'Bài có 10 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002648, 3000623, 'READING', NULL, 'Văn mẫu 文型', '毎日 運動した ほうが いいです。\nあしたは 雪が 降るでしょう。\n約束の 時間に 間に 合わないかも しれません。', 'Bạn nên vận động mỗi ngày.\nNgày mai có lẽ sẽ có tuyết rơi.\nCó thể tôi sẽ không kịp giờ hẹn.', 1),
(3002649, 3000623, 'READING', NULL, 'Ví dụ 例文', '学生の アルバイトに ついて どう 思いますか。\n…いいと 思いますよ。若い ときは、いろいろな 経験を した ほうが いいですから。\n1か月ぐらい ヨーロッパへ 遊びに 行きたいんですが、40万円で 足りますか。\n…十分だと 思います。でも、現金で 持って 行かない ほうが いいですよ。\n先生、日本の 経済は どう なるでしょうか。\n…そうですね。まだ しばらく よく ならないでしょう。\n先生、ハンスは インフルエンザですか。\n…はい、インフルエンザです。2、3日 高い 熱が 続くかも しれませんが、心配しなくても いいですよ。\nエンジンの 音が おかしいですね。\n…そうですね。故障かも しれません。ちょっと 調べましょう。', 'Bạn nghĩ sao về chuyện sinh viên đi làm thêm?\n…Tôi nghĩ là tốt đấy, vì khi còn trẻ nên trải nghiệm nhiều điều.\nTôi muốn đi chơi châu Âu khoảng một tháng. 400.000 yên có đủ không?\n…Tôi nghĩ là đủ. Nhưng bạn không nên mang số tiền đó bằng tiền mặt.\nThưa thầy, kinh tế Nhật Bản rồi sẽ thế nào ạ?\n…Để xem nào. Có lẽ trong một thời gian nữa vẫn chưa khá lên được.\nThưa bác sĩ, Hans bị cúm phải không ạ?\n…Vâng, cháu bị cúm. Có thể cháu còn sốt cao hai, ba ngày nữa, nhưng bạn không cần lo.\nTiếng động cơ nghe lạ nhỉ.\n…Đúng vậy. Có thể máy bị hỏng. Chúng ta kiểm tra một chút nhé.', 2),
(3002650, 3000623, 'READING', NULL, 'Luyện tập A – 1', '病院へ 行った ほうが いいです。\n薬を 飲んだ ほうが いいです。\nたばこを 吸わない ほうが いいです。\nおふろに 入らない ほうが いいです。', 'Bạn nên đi bệnh viện.\nBạn nên uống thuốc.\nBạn không nên hút thuốc.\nBạn không nên tắm bồn.', 3),
(3002651, 3000623, 'READING', NULL, 'Luyện tập A – 2', '今夜は 星が 見える でしょう。\n今夜は 雪は 降らない でしょう。\n今夜は 寒い でしょう。\n今夜は 月が きれい でしょう。\n今夜は 雨 でしょう。', 'Tối nay có lẽ sẽ nhìn thấy sao.\nTối nay có lẽ tuyết sẽ không rơi.\nTối nay có lẽ trời sẽ lạnh.\nTối nay có lẽ trăng sẽ đẹp.\nTối nay có lẽ sẽ có mưa.', 4),
(3002652, 3000623, 'READING', NULL, 'Luyện tập A – 3', '彼は 会社を 辞める かも しれません。\n彼は パーティーに 来ない かも しれません。\n彼は あした 忙しい かも しれません。\n彼は 来週 暇 かも しれません。\n彼は 病気 かも しれません。', 'Có thể anh ấy sẽ nghỉ việc ở công ty.\nCó thể anh ấy sẽ không đến dự tiệc.\nCó thể anh ấy sẽ bận vào ngày mai.\nCó thể anh ấy sẽ rảnh vào tuần sau.\nCó thể anh ấy bị ốm.', 5),
(3002653, 3000624, 'READING', NULL, 'Luyện tập', 'Bài có 4 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002654, 3000625, 'READING', NULL, 'r1', '日本人に「いちばん好きな花は何ですか」と聞いたら、多くの人が「桜」と答えるでしょう。\n春になって桜が咲くと、周りの景色がみんなピンク色になります。\nほんとうにきれいです。\nそして、満開の桜は風が吹くと一斉に散ります。\n桜は散るときも、とてもきれいです。', 'Nếu hỏi người Nhật “Bạn thích loài hoa nào nhất?”, có lẽ nhiều người sẽ trả lời là “hoa anh đào”.\nKhi xuân đến và hoa anh đào nở, cảnh vật xung quanh đều nhuộm hồng.\nThật đẹp.\nRồi khi gió thổi, những bông anh đào đang nở rộ đồng loạt rụng xuống.\nHoa anh đào lúc rụng cũng rất đẹp.', 1),
(3002655, 3000625, 'READING', NULL, 'r2', '春には、たくさんの人が桜を見に行きます。\nお花見は1,200年ぐらいまえから続いている日本の春の大きいイベントです。\n桜が咲く時期は南から北へだんだん移ります。\n沖縄の桜がいちばん早くて、1月ごろ咲きます。\n北海道の桜は5月ごろ咲きます。\nですから、お花見のシーズンになると、天気予報の中で、「上野公園の桜は来週金曜日ごろ満開になるでしょう。」とか、「弘前城の桜はもうすぐ咲くでしょう。」とか、桜の花が咲く日の予想を発表します。\n桜は1、2週間で散ってしまいますから、予想を聞いて、お花見の日を決めます。', 'Vào mùa xuân, rất nhiều người đi ngắm hoa anh đào.\nNgắm hoa là một sự kiện lớn vào mùa xuân ở Nhật, được duy trì từ khoảng 1.200 năm trước đến nay.\nHoa anh đào nở dần từ nam lên bắc.\nHoa anh đào ở Okinawa nở sớm nhất, vào khoảng tháng 1.\nHoa anh đào ở Hokkaido nở vào khoảng tháng 5.\nVì vậy, vào mùa ngắm hoa, bản tin dự báo thời tiết sẽ công bố dự đoán ngày hoa anh đào nở, chẳng hạn “Hoa anh đào ở công viên Ueno có lẽ sẽ nở rộ vào khoảng thứ sáu tuần sau” hay “Hoa anh đào ở thành Hirosaki có lẽ sắp nở”.\nHoa anh đào sẽ rụng hết trong một, hai tuần, nên mọi người nghe dự báo rồi quyết định ngày đi ngắm hoa.', 2),
(3002656, 3000625, 'READING', NULL, 'r3', 'お花見では、家族や友達と、桜を見ながら食べたり飲んだり、歌ったり踊ったりします。\n絵をかいたり、写真を撮ったりする人もいます。\nバーベキューなどができる公園もあります。\n昼の桜もいいですが、夜の桜もとてもきれいです。\nでも、お花見のころの夜はちょっと寒いかもしれませんから、セーターなど暖かい服を持って行ったほうがいいでしょう。', 'Khi đi ngắm hoa, mọi người vừa ngắm anh đào vừa ăn uống, ca hát, nhảy múa cùng gia đình và bạn bè.\nCũng có người vẽ tranh hoặc chụp ảnh.\nMột số công viên còn cho phép tổ chức tiệc nướng và những hoạt động tương tự.\nHoa anh đào ban ngày đẹp, mà hoa anh đào ban đêm cũng rất đẹp.\nTuy nhiên, đêm vào mùa ngắm hoa có thể hơi lạnh, nên mang theo quần áo ấm như áo len.', 3),
(3002657, 3000625, 'READING', NULL, 'r4', '日本には、桜の名所がたくさんあります。\n春になると、桜の名所も、町の公園も、朝から夜まで人でいっぱいです。\nお花見は、日本人が短い桜の季節を楽しむ大切なイベントなのです。', 'Ở Nhật có nhiều nơi nổi tiếng để ngắm hoa anh đào.\nKhi xuân đến, cả những điểm ngắm hoa nổi tiếng lẫn công viên trong phố đều đông kín người từ sáng đến tối.\nNgắm hoa là một sự kiện quan trọng để người Nhật tận hưởng mùa anh đào ngắn ngủi.', 4),
(3002658, 3000625, 'READING', NULL, 'sakura-map-text', '右の地図の「○/○（○月○日）」は桜が咲く日です。\n咲く日が同じ所を線で結んだものを「桜前線」と言います。', 'Ký hiệu “○/○ (tháng ○, ngày ○)” trên bản đồ bên phải là ngày hoa anh đào nở.\nĐường nối những nơi hoa nở cùng ngày được gọi là “đường hoa anh đào nở”.', 5),
(3002659, 3000625, 'READING', NULL, 'x-intro', '日本人3万人に桜とお花見について聞きました。', 'Chúng tôi đã hỏi 30.000 người Nhật về hoa anh đào và việc ngắm hoa.', 6),
(3002660, 3000625, 'READING', NULL, 'x-pie-table', 'あなたは桜が好きですか\na\n75%\nb\n22%\nc\n3%', 'Bạn có thích hoa anh đào không?', 7),
(3002661, 3000625, 'READING', NULL, 'x-style-table', '好きなお花見のスタイル（人）\n（①）\n20,503\n夜桜を見る\n13,583\n（②）\n11,139\n会社や学校へ行くとき見る\n9,228\n（③）\n9,055\n（1人の人が2つ以上答えました。それで、合計は3万人以上です。）', 'Cách ngắm hoa yêu thích (số người)\nngắm hoa anh đào ban đêm\nngắm trên đường đi làm hoặc đi học\n(Có người chọn hai câu trả lời trở lên. Vì vậy, tổng cộng nhiều hơn 30.000 người.)', 8),
(3002662, 3000625, 'READING', NULL, 'x-food', '塩漬けの桜の花や葉をお湯に入れて飲んだり、食べたりします。', 'Người ta cho hoa và lá anh đào đã muối vào nước nóng để uống, hoặc dùng để ăn.', 9),
(3002663, 3000626, 'READING', NULL, 'Luyện tập', 'Bài có 17 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002664, 3000627, 'LISTENING', NULL, '1. Nghe lời khuyên của hàng xóm隣の 人は とても 親切です。チンさんは どうしますか。Người hàng xóm rất tốt bụng. Chị Chin sẽ làm gì?', 'A：チンさん、今週の土曜日は この アパートの大掃除だけど、覚えてる?\nB：大掃除?\nB：何を するんですか。\nA：アパートの周りを みんなで掃除するのよ。\nA：掃除が終わったら、いっしょに昼ごはんを食べるの。\nB：土曜日は ちょっと約束が あるんですけど。\nA：1年に1回の ことだから、参加したほうが いいと思うよ。\nA：みんなと友達に なれるいいチャンスだし。\nB：わかりました。\nB：約束を変えて もらいます。\nA：チンさん、買い物は いつも コンビニで してるの?\nB：はい。\nB：便利ですから。\nA：コンビニは高いでしょう?\nA：マルヤスーパーへ行ったほうがいいよ。\nA：ちょっと遠いけど。\nB：そうですね。\nB：これから そうします。\nA：チンさん、最近いつも遅いね。\nB：ええ。\nB：残業が あったり、ミーティングが あったり、……。\nA：仕事だったら、しかたがないけど…。駅からは バスに乗っているの?\nB：いいえ、歩いています。\nB：遅くなると、バスが ないんです。\nA：遅くなったら、タクシーに乗ったほうが いいよ。\nA：危ないから。\nB：はい。\nB：これから そうします。\nA：最近元気が ないけど、どうしたの？忙しいの？\nB：実は、今の仕事を やめようと思っているんですが。\nA：どうして?\nB：給料も安いし、残業も多いし……。\nA：やめて、どうするの?\nB：ほかの仕事を探します。\nA：でも、今の仕事、田中さんに紹介して もらったんでしょう?\nB：ええ。\nA：やめるまえに、田中さんに話しておいたほうがいいと思うよ。\nB：そうですね。\nB：そうします。', 'Chin này, bạn còn nhớ thứ bảy này có buổi tổng vệ sinh chung cư không?\nTổng vệ sinh sao?\nSẽ làm gì vậy?\nMọi người sẽ dọn dẹp xung quanh chung cư.\nDọn dẹp xong thì mọi người sẽ cùng ăn trưa.\nThứ bảy này tôi có hẹn rồi…\nMỗi năm chỉ có một lần nên tôi nghĩ bạn nên tham gia.\nĐây cũng là dịp tốt để làm quen với mọi người.\nTôi đã hiểu rồi.\nTôi sẽ nhờ đổi lịch hẹn.\nChin này, bạn vẫn thường mua đồ ở cửa hàng tiện lợi à?\nVâng.\nVì tiện lợi.\nCửa hàng tiện lợi thì đắt nhỉ?\nBạn nên đến siêu thị Maruya.\nTuy hơi xa một chút.\nĐúng vậy nhỉ.\nTừ giờ tôi sẽ làm như vậy.\nChin này, dạo này bạn hay về muộn nhỉ.\nVâng.\nTôi phải tăng ca, họp hành…\nVì công việc thì đành vậy. Bạn đi xe buýt từ ga về à?\nKhông, tôi đi bộ.\nVề muộn thì không còn xe buýt.\nNếu muộn thì bạn nên đi taxi.\nVì nguy hiểm.\nVâng.\nTừ bây giờ tôi sẽ làm như thế.\nDạo này trông bạn không được vui, có chuyện gì vậy? Bạn bận lắm à?\nThật ra tôi đang định nghỉ công việc hiện tại…\nTại sao vậy?\nLương thì thấp, lại phải tăng ca nhiều…\nNghỉ rồi bạn sẽ làm gì?\nTôi sẽ tìm công việc khác.\nNhưng công việc hiện tại là do anh Tanaka giới thiệu cho bạn phải không?\nVâng.\nTôi nghĩ bạn nên nói với anh Tanaka trước khi nghỉ.\nĐúng vậy nhỉ.\nTôi sẽ làm như thế.', 1),
(3002665, 3000627, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 2),
(3002666, 3000627, 'LISTENING', NULL, '2. Chuẩn bị khi có động đấtサントスさんは 地震について 注意を 聞きました。どんな準備を しておきますか。もし地震が あったら、何を しなければなりませんか。〇を 付けてください。Santos nghe hướng dẫn về động đất. Hãy đánh dấu các việc cần chuẩn bị và các việc cần làm khi có động đất', 'A：日本は地震が多いですね。\nB：ええ。でも、あまり心配しないで ください。\nB：よく準備して おいたら、大丈夫ですよ。\nA：どんな準備を しておいたら いいですか。\nB：まず、いつもうちに水と食べ物を準備して おきます。\nB：それから、寝るときは お金と パスポートを近くに置いて おいたほうがいいです。\nB：あ、ケータイも。\nA：はい。\nB：それから、部屋の中の高い所に物を置いて おかないほうが いいですよ。\nB：危ないですから。\nA：わかりました。\nA：もし地震が あったら、まず何を しなければなりませんか。\nB：ガスを使っていたら、\nB：すぐ消して、それから、机の下に入ってください。\nA：え? すぐ外に出ないほうが いいんですか。\nB：はい。\nB：すぐ外に出ると危ないですから。\nB：窓のガラスなどが落ちてきますから、地震が終わってから、外に出て ください。\nA：わかりました。', 'Nhật Bản có nhiều động đất nhỉ.\nVâng, nhưng đừng lo quá.\nChuẩn bị kỹ từ trước thì sẽ ổn thôi.\nTôi nên chuẩn bị những gì?\nTrước hết, luôn luôn chuẩn bị sẵn nước và thức ăn trong nhà.\nNgoài ra, khi ngủ nên để tiền và hộ chiếu ở gần mình.\nÀ, cả điện thoại di động nữa.\nVâng.\nCũng không nên để đồ vật ở chỗ cao trong phòng.\nVì nguy hiểm.\nTôi đã hiểu rồi.\nNếu như có động đất thì trước hết phải làm gì?\nNếu đang dùng bếp ga thì…\ntắt ngay rồi trú dưới bàn.\nHả? Không nên ra ngoài ngay sao?\nVâng.\nVì ra ngoài ngay thì nguy hiểm.\nKính cửa sổ và những thứ khác có thể rơi xuống nên hãy đợi hết động đất rồi mới ra ngoài.\nTôi đã hiểu rồi.', 3),
(3002667, 3000627, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 4),
(3002668, 3000627, 'LISTENING', NULL, '3. Dự đoán tương lai Nhật Bản日本の 将来について 講義を 聞きました。今はａ、ｂの どちらですか。将来は①、②のどちらに なりますか。Nghe bài nói về tương lai Nhật Bản. Hiện tại là a hay b? Tương lai là hình 1 hay 2?', '100年ぐらいまえから地球が暖かく なって います。\nこのまま地球が暖かく なると、これからの100年間に日本は今より2度から4度ぐらい高く なるでしょう。\n35度より暑い夏の日が多く なって、寒い冬の日が少なく なるでしょう。\nそして、水、食べ物などが大きい問題に なるでしょう。\n日本は人が少なくなっています。\n今の若い人は あまり子どもを作りません。\n1つの家族に子どもは1.5人ぐらいです。\n20年後には老人が多くなって、3.6人に1人が老人に なります。\n若くて、元気で、働くことが できる人が少なくなると、\n日本の経済は だんだん弱くなるでしょう。\nこれは大変な問題です。\n今から70年ぐらいまえ、日本人は今より背が低かったです。\n17歳の男の人は平均161センチ、女の人は152センチでした。\n食べ物が よくなって、1996年に男の人は171センチ、女の人は158センチに なりました。\nでも、それからは高く なって いません。\nどうしてでしょうか。\n今、若い人は あまり運動を しません。\n寝る時間も少なく なりました。\nこの生活が続いたら、これからも日本人の背は高くならないでしょう。', 'Trái đất bắt đầu ấm dần lên từ khoảng 100 năm trước.\nNếu Trái đất tiếp tục ấm lên như thế này thì trong 100 năm tới, nhiệt độ ở Nhật Bản có lẽ sẽ cao hơn hiện nay khoảng 2 đến 4 độ.\nSẽ có nhiều ngày hè nóng trên 35 độ hơn, còn những ngày đông lạnh sẽ ít đi.\nNước, thức ăn và những thứ khác có lẽ sẽ trở thành những vấn đề lớn.\nDân số Nhật Bản đang giảm.\nGiới trẻ hiện nay không sinh con nhiều lắm.\nTrung bình mỗi gia đình có khoảng 1,5 con.\nSau 20 năm, số người già sẽ tăng: cứ 3,6 người thì có một người già.\nKhi số người trẻ, khỏe và có khả năng làm việc giảm đi…\nthì kinh tế Nhật Bản có lẽ sẽ dần suy yếu.\nĐây là một vấn đề lớn.\nKhoảng 70 năm trước, người Nhật thấp hơn bây giờ.\nỞ tuổi 17, nam cao trung bình 161 cm, nữ cao 152 cm.\nNhờ dinh dưỡng tốt hơn, đến năm 1996 nam cao 171 cm, nữ cao 158 cm.\nNhưng kể từ đó chiều cao không tăng thêm.\nVì sao thế nhỉ?\nBây giờ, giới trẻ không vận động cho lắm.\nThời gian ngủ cũng giảm đi.\nNếu tiếp tục sinh hoạt như vậy thì có lẽ chiều cao của người Nhật sẽ không tăng thêm.', 5),
(3002669, 3000627, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 6),
(3002670, 3000627, 'LISTENING', NULL, '4. Lo lắng và cách xử lý何を 心配して いますか。どう しますか。Họ đang lo điều gì và sẽ làm gì?', 'A：サントスさん、何か心配な ことが あるんですか。\nB：ええ。\nB：あした、富士山へ写真を撮りに行こうと思っているんですが、\nB：今夜は星も見えないし、月も出ていません。\nA：そうですね。\nA：あしたは富士山が見えない かもしれませんね。\nB：ええ。\nB：あしたは近くの動物園へ行って動物の写真を撮ります。\nA：そうですね。\nA：富士山は天気が いい日に撮ったほうが いいですね。\nA：マリアさん、どうしたんですか。\nA：何を心配しているんですか。\nB：見て ください。\nB：空が とても暗く なりました。\nA：そうですね。\nA：雨が降るかもしれませんね。\nB：ええ。\nB：けさ洗濯した物が外に出してあるんです。\nA：じゃ、早く帰って入れないと。\nB：ええ。\nA：テレーザちゃん、何を見ているの?\nB：見て。\nB：あそこに黒い猫が いる。\nA：あ、ほんとうだ。\nB：怖い。\nB：黒い猫、嫌い。\nB：何か悪いことが あるかもしれないよ。\nA：そう。\nB：きょうは もう遊ばない。\nB：帰る。\nA：ええ?', 'Anh Santos có chuyện gì lo lắng phải không?\nVâng.\nNgày mai tôi định đi chụp ảnh núi Phú Sĩ, nhưng…\nTối nay không nhìn thấy sao, trăng cũng không lên.\nĐúng vậy nhỉ.\nNgày mai, không chừng không nhìn thấy núi Phú Sĩ nhỉ.\nVâng.\nNgày mai tôi sẽ đến sở thú gần đây chụp ảnh động vật.\nĐúng vậy nhỉ.\nNên chụp ảnh núi Phú Sĩ vào ngày đẹp trời nhỉ.\nChị Maria, có chuyện gì vậy?\nChị đang lo chuyện gì vậy?\nNhìn xem.\nTrời tối sầm lại rồi.\nĐúng thế nhỉ.\nKhông chừng sẽ có mưa nhỉ.\nVâng.\nQuần áo giặt sáng nay vẫn đang phơi bên ngoài.\nVậy chị phải mau về cất quần áo vào thôi.\nVâng.\nTeresa, cháu đang nhìn gì vậy?\nNhìn kìa.\nCó con mèo đen ở chỗ đằng kia.\nÀ, đúng thật.\nSợ quá.\nCháu không thích mèo đen.\nCó thể sẽ xảy ra chuyện không hay đấy.\nVậy à.\nHôm nay cháu không chơi nữa đâu.\nCháu về nhà đây.\nHả?', 7),
(3002671, 3000627, 'LISTENING', NULL, 'Audio 1', NULL, NULL, 8),
(3002672, 3000628, 'READING', NULL, 'Luyện tập', 'Bài có 30 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002673, 3000629, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo ý kiến hoặc dự định của bạn. Xem câu trả lời mẫu sau khi làm.\nいいえ、飲まない ほうが いいです。\n借りたほうがいいです。', NULL, 1),
(3002674, 3000629, 'READING', NULL, '1. Nghe và trả lời', 'Nghe và trả lời theo ý kiến hoặc dự định của bạn. Xem câu trả lời mẫu sau khi làm.\n夜 寝られないんですが、薬を 飲んだ ほうが いいですか。\n子どもが 生まれるんですが、ベッドは 買った ほうが いいですか、借りた ほうが いいですか。', NULL, 2),
(3002675, 3000629, 'READING', NULL, '2. Nghe: đúng hay sai', 'Nghe hội thoại và câu ★. Chọn ○ nếu câu ★ đúng với hội thoại, chọn × nếu sai.\n女：小川さん、きょうは 料理教室に 行く 日ですね。\n男：そうなんですが、けさから ちょっと 調子が 悪いんです。\n女：じゃ、早く 帰って、ゆっくり 休んだ ほうが いいですね。\n男：ええ、そうします。\n★：男の 人は きょう 料理教室に 行きません。\n女：土曜日から ベトナムへ 旅行に 行くんです。\n男：へえ、いいですね。\n女：外国は 初めてなんですが、どんなことに 気を つけたら いいですか。\n男：そうですね。お金は 現金で 持って 行かない ほうが いいですよ。\n女：わかりました。\n★：旅行のとき、お金は 現金で 持って 行ったほうがいいです。\n女：きのう 日本語の 試験を 受けました。\n男：どうでしたか。\n女：あまり 難しくなかったです。\n男：じゃ、きっと 大丈夫でしょう。\n★：男の 人は 女の 人が 試験に 失敗したと 思って います。\n男：あのう、すみません。ミラーさんは 今 どちらですか。\n女：たぶん 食堂でしょう。\n男：じゃ、１時ごろ また 来ます。\n女：はい、ミラーさんに そう 言って おきます。\n★：男の 人は ミラーさんに 会えませんでした。\n女：バス、なかなか 来ないわね。もう ６時半よ。\n男：そうだね。コンサートに 間に合わない かも しれないね。\n女：じゃ、タクシーで 行かない？\n男：そうだね。そうしよう。\n★：バスが 来ませんから、男の人と 女の人は タクシーで 行きます。', NULL, 3),
(3002676, 3000629, 'READING', NULL, '6. Đọc bài bói sao', 'Theo nội dung bài bói sao, người thuộc cung Kim Ngưu nên làm việc nào? Chọn ○ cho việc nên làm và × cho việc không nên làm.\n牡牛座（４月２１日 － ５月２１日）\n仕事....何か 新しい 仕事を 始めると、成功するでしょう。でも、働きすぎには 気を つけた ほうが いいでしょう。\nお金....今月は たくさん お金を 使っても、困らないでしょう。宝くじを 買うと、当たる かも しれません。\n健康....東の 方へ 旅行したり、スポーツを したり すると、元気に なります。でも、足の けがには 気を つけて ください。\n恋愛....一人で コンサートや 展覧会に 出かけると、いいでしょう。その とき 会った 人が 将来の 恋人に なる かも しれません。\nラッキーアイテム....青い 石', NULL, 4),
(3002677, 3000629, 'READING', NULL, '7. Ý kiến về bói toán', 'Viết ý kiến của bạn về bói toán.\n占いは おもしろいと 思いますが、全部は 信じません。', NULL, 5),
(3002678, 3000630, 'READING', NULL, 'Luyện tập', 'Bài có 22 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002679, 3000631, 'READING', NULL, '3. Đưa ra lời khuyên', '〜た ほうが いいです Đọc tình huống rồi viết lời khuyên với thể た + ほうがいいです. Có thể có nhiều cách trả lời.\n水で 冷やした ほうが いいですよ。\n修理した ほうが いいですよ。', NULL, 1),
(3002680, 3000631, 'READING', NULL, '4. Nên làm và không nên làm', '［〜た／〜ない］ほうが いいです Viết lời khuyên cho hai tình huống. Dùng cả lời khuyên nên làm (thể た) và không nên làm (thể ない), như hai ví dụ.\nもう 夜 遅いですから、静かに した ほうが いいです。\nコーヒーは 飲まない ほうが いいです。\n日本語が 上手に なりたい 人は、毎日 勉強した ほうが いいです。\n日本人の 友達と たくさん 話した ほうが いいです。\n勉強を やめない ほうが いいです。', NULL, 2),
(3002681, 3000631, 'READING', NULL, '6. Dự đoán số trẻ em ở Nhật', '〜でしょう Xem ba biểu đồ dân số Nhật Bản và điền câu về số trẻ em. Mốc 「10 năm sau」 theo ngữ cảnh biểu đồ trong bài.\n今から １０年後、子どもの 数は 少なく なるでしょう。\n結婚しない 人が 多く なって いますから。', NULL, 3),
(3002682, 3000631, 'READING', NULL, '7. Viết về đất nước của bạn', '自分の 国について 書きましょう。 Viết về số trẻ em ở đất nước của bạn và dự đoán với 〜でしょう.\nベトナムには 子どもが たくさん います。\n１０年後、子どもの 数は 今より 少なく なるでしょう。', NULL, 4),
(3002683, 3000631, 'READING', NULL, '8. Bạn sau 5 năm hoặc 10 năm', '〜でしょう／〜かもしれません Viết về bản thân sau 5 năm hoặc 10 năm. Dùng でしょう để dự đoán và かもしれません để nêu một khả năng.\nわたしは 今 さくら大学で 日本語を 勉強して います。\n５年後は たぶん 会社で 働いて いるでしょう。\nでも、日本には 住んで いないかもしれません。', NULL, 5),
(3002684, 3000631, 'READING', NULL, '9. Bao nhiêu là đủ?', '数量／経費で＋足ります／可能動詞 Theo ví dụ, viết câu dùng số lượng hoặc chi phí + で với たります hoặc động từ thể khả năng.\nこの 仕事は ２人で 足ります。\nこの ノートは 100円で 買えます。', NULL, 6),
(3002685, 3000632, 'READING', NULL, 'Luyện tập', 'Bài có 44 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002686, 3000633, 'READING', NULL, 'Danh sách kanji', '成 (THÀNH) — thành, trở thành; hoàn thành — せい\n功 (CÔNG) — công lao, thành tích — こう\n失 (THẤT) — mất, đánh mất; sai sót — しつ\n敗 (BẠI) — thua, thất bại — はい\n合 (HỢP) — hợp, kết hợp; phù hợp, khớp — ごう\n格 (CÁCH) — cấp bậc, tư cách; quy cách — かく\n運 (VẬN) — chở, vận chuyển; vận may — うん\n動 (ĐỘNG) — chuyển động — どう\n続 (TỤC) — tiếp tục, nối tiếp — つづ\n冷 (LÃNH) — lạnh, mát; lạnh lùng — ひ\n無 (VÔ) — không, không có — む\n理 (LÝ) — lý do; lý luận — り\n十 (THẬP) — mười — じゅう\n分 (PHÂN) — phút; chia; phần — ぶん\n先 (TIÊN) — trước — せん\n生 (SINH) — sống; sinh ra; tươi, sống — せい\n水 (THỦY) — nước — すい\n道 (ĐẠO) — con đường — どう\n晴 (TÌNH) — trời nắng, quang đãng; xua tan — は\n曇 (ĐÀM) — có mây, u ám — くも\n空 (KHÔNG) — bầu trời, không trung; trống, rỗng — そら\n太 (THÁI) — to, dày; béo — たい\n陽 (DƯƠNG) — mặt trời, ánh nắng; dương — よう\n星 (TINH) — ngôi sao, sao — ほし\n風 (PHONG) — gió; phong cách, kiểu — かぜ\n東 (ĐÔNG) — phía đông — ひがし\n西 (TÂY) — phía tây — にし\n南 (NAM) — phía nam — みなみ\n北 (BẮC) — phía bắc — きた\n込 (NHẬP) — đông đúc, chật chội; cho vào — こ\n出 (XUẤT) — ra; đưa ra ngoài — で\n国 (QUỐC) — đất nước — こく\n際 (TẾ) — ranh giới, bờ mép; dịp — さい\n今 (KIM) — bây giờ, hiện tại — こん\n夜 (DẠ) — đêm, tối — や\n夕 (TỊCH) — buổi chiều, chiều tối — ゆう\n方 (PHƯƠNG) — cách, phương pháp; phương hướng; người (cách nói lịch sự) — かた\n遅 (TRÌ) — chậm; muộn, trễ — おそ', NULL, 1),
(3002687, 3000634, 'READING', NULL, '使い方 – Câu ví dụ', '今度の日曜日、サッカーの試合があります。毎日、朝と夕方に練習しています。ぜひ勝ちたいですから。\n3か月前にたばこをやめました。体の調子がとてもよくなりました。\n大学で国際経済を勉強しています。難しいですが、おもしろいです。\n今夜は空がとてもきれいです。南側の窓から月と星が見えます。\n道が込んでいます。新幹線の時間に間に合わないかもしれません。', NULL, 1),
(3002688, 3000634, 'READING', NULL, '読み物 – Bài đọc · ダイエット', 'わたしは毎日、自動車で会社へ行っています。そして、会社でも朝から晩までずっと座っています。そして休みの日は、うちで寝たり、食べたりしています。ずっと運動不足です。それで、太ってしまいました。\n彼女とかけをしました。もし、わたしが5キロやせられたら、わたしの勝ちです。彼女がわたしに欲しい物を買ってくれます。もし、やせられなかったら、わたしの負けです。わたしが彼女をニューヨーク旅行に連れて行かなければなりません。\nそれで、最近、運動を始めました。1週間に3回、スポーツクラブへ行っています。運動してから、冷やしておいたビールを飲みます。最高です。いつも、たくさんビールを飲んでしまいます。\nそろそろ、飛行機を予約したほうがいいかもしれません。', NULL, 2),
(3002689, 3000634, 'READING', NULL, '読み物 – Bài đọc · 冬の山', 'わたしは山が好きです。山に登ることが好きです。特に冬の山が好きです。冬の山の星空と風の音が好きです。山のいちばん上まで登って見る雪山の景色は最高です。\n今年も冬の山へ来ました。今日は山小屋に泊まっています。もう夕方です。西の空の夕焼けがきれいです。東の空を見ると、月と星が出ています。風が冷たくなりました。今夜は初雪が降るかもしれません。', NULL, 3),
(3002690, 3000635, 'READING', NULL, 'Luyện tập', 'Bài có 12 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002691, 3000636, 'READING', NULL, 'Luyện tập', 'Bài có 6 câu hỏi — làm trong bài kiểm tra của bài học.', NULL, 1),
(3002692, 3000637, 'READING', NULL, 'Danh sách từ vựng', 'Bài có 43 từ vựng.', NULL, 1),
(3002693, 3000639, 'GRAMMAR', 3000218, 'Ví dụ 1', '早く 逃げろ。', 'Chạy mau lên!', 1),
(3002694, 3000639, 'GRAMMAR', 3000218, 'Ví dụ 2', 'あした うちへ 来いよ。', 'Mai đến nhà tôi nhé!', 2),
(3002695, 3000639, 'GRAMMAR', 3000218, 'Ví dụ 3', '規則を 守れ。', 'Hãy tuân thủ quy định!', 3),
(3002696, 3000639, 'GRAMMAR', 3000219, 'Ví dụ 4', 'ここで 騒ぐな。', 'Đừng làm ồn ở đây!', 4),
(3002697, 3000639, 'GRAMMAR', 3000219, 'Ví dụ 5', 'エレベーターを 使うな。', 'Đừng dùng thang máy!', 5),
(3002698, 3000639, 'GRAMMAR', 3000219, 'Ví dụ 6', 'あきらめるな。', 'Đừng bỏ cuộc!', 6),
(3002699, 3000639, 'GRAMMAR', 3000220, 'Ví dụ 7', '頑張れ。負けるな。', 'Cố lên! Đừng thua nhé!', 7),
(3002700, 3000639, 'GRAMMAR', 3000220, 'Ví dụ 8', 'あまり 飲むなよ。', 'Đừng uống nhiều quá nhé!', 8),
(3002701, 3000639, 'GRAMMAR', 3000220, 'Ví dụ 9', '早く 寝ろ。', 'Đi ngủ ngay!', 9),
(3002702, 3000639, 'GRAMMAR', 3000221, 'Ví dụ 10', '勉強しなさい。', 'Học bài đi.', 10),
(3002703, 3000639, 'GRAMMAR', 3000221, 'Ví dụ 11', 'ごはんを 食べなさい。', 'Ăn cơm đi.', 11),
(3002704, 3000639, 'GRAMMAR', 3000221, 'Ví dụ 12', '早く 寝なさい。', 'Mau đi ngủ đi con.', 12),
(3002705, 3000639, 'GRAMMAR', 3000222, 'Ví dụ 13', 'この 漢字は 何と 読みますか。', 'Chữ Hán này đọc thế nào?', 13),
(3002706, 3000639, 'GRAMMAR', 3000222, 'Ví dụ 14', '…「いりぐち」と 読みます。', '…Đọc là “iriguchi”.', 14),
(3002707, 3000639, 'GRAMMAR', 3000222, 'Ví dụ 15', 'あそこに 「止まれ」と 書いて あります。', 'Đằng kia có ghi “Dừng lại”.', 15),
(3002708, 3000639, 'GRAMMAR', 3000223, 'Ví dụ 16', 'この マークは どういう 意味ですか。', 'Ký hiệu này có nghĩa là gì?', 16),
(3002709, 3000639, 'GRAMMAR', 3000223, 'Ví dụ 17', '…洗濯機で 洗えるという 意味です。', '…Có nghĩa là có thể giặt bằng máy giặt.', 17),
(3002710, 3000639, 'GRAMMAR', 3000223, 'Ví dụ 18', '「使用禁止」は 使うなという 意味です。', '“Shiyō kinshi” có nghĩa là cấm sử dụng.', 18),
(3002711, 3000639, 'GRAMMAR', 3000224, 'Ví dụ 19', '田中さんは 「あした 休みます」と 言って いました。', 'Anh Tanaka đã nói: “Ngày mai tôi nghỉ.”', 19),
(3002712, 3000639, 'GRAMMAR', 3000224, 'Ví dụ 20', '田中さんは あした 休むと 言って いました。', 'Anh Tanaka nói rằng ngày mai anh ấy sẽ nghỉ.', 20),
(3002713, 3000639, 'GRAMMAR', 3000224, 'Ví dụ 21', '佐藤さんは 日曜日は 暇だと 言って いました。', 'Chị Sato nói rằng chủ nhật chị ấy rảnh.', 21),
(3002714, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 22', 'ワンさんに 「あとで 電話を ください」と 伝えて いただけませんか。', 'Bạn nhắn giúp anh Wang gọi điện cho tôi sau được không?', 22),
(3002715, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 23', 'すみませんが、渡辺さんに あしたの パーティーは 6時からだと 伝えて いただけませんか。', 'Phiền bạn nhắn giúp chị Watanabe rằng bữa tiệc ngày mai bắt đầu lúc 6 giờ được không?', 23),
(3002716, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 24', '…はい、わかりました。6時からですね。', '…Vâng, tôi hiểu rồi. Bắt đầu lúc 6 giờ phải không?', 24),
(3002717, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 25', '頑張れ。', 'Cố lên!', 25),
(3002718, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 26', '走れ。', 'Chạy đi!', 26),
(3002719, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 27', '行け。', 'Đi đi!', 27),
(3002720, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 28', '戻れ。', 'Quay lại!', 28),
(3002721, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 29', '止めろ。', 'Dừng lại đi!', 29),
(3002722, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 30', 'ボールを 投げるな。', 'Đừng ném bóng!', 30),
(3002723, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 31', '泳ぐな。', 'Đừng bơi!', 31),
(3002724, 3000639, 'GRAMMAR', 3000225, 'Ví dụ 32', '登るな。', 'Đừng trèo!', 32),
