(3014079, 'CONTENT_ITEM', 3003333, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L160-LIS-002-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/b/23B-23.mp3', '23B-23.mp3', 'NGUON', NULL),
(3014080, 'CONTENT_ITEM', 3003334, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L160-LIS-003', 'https://www.vnjpclub.com/minna-no-nihongo/bai-40-luyen-nghe.html', '3. Nghe lời mời ở lễ hộiお祭りに 行きました。どの 店で 何を しますか。Bạn đến lễ hội. Ở gian hàng nào, bạn sẽ làm gì?', 'NGUON', NULL),
