INSERT INTO content_source (id, entity_type, entity_id, source_code, stable_code, source_url, original_title, review_status, note) VALUES
(3015503, 'LESSON', 3000479, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', 'Luyện nghe 聴解タスク25', 'NGUON', NULL),
(3015504, 'CONTENT_ITEM', 3003661, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-001', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '1. Hayashi quyết định thay đổi林さんは 今どうですか。どうしますか。Bây giờ Hayashi đang gặp tình trạng gì? Bạn ấy sẽ làm gì?', 'NGUON', NULL),
(3015505, 'CONTENT_ITEM', 3003662, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-001-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/c/05C-5.mp3', '05C-5.mp3', 'NGUON', NULL),
(3015506, 'CONTENT_ITEM', 3003663, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-002', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '2. Ý kiến về chương trình truyền hìnhテレビ番組について、どうしたら いいと 言っていますか。Những người tham gia cho rằng nên cải thiện các chương trình truyền hình như thế nào?', 'NGUON', NULL),
(3015507, 'CONTENT_ITEM', 3003664, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-002-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/c/06C-6.mp3', '06C-6.mp3', 'NGUON', NULL),
(3015508, 'CONTENT_ITEM', 3003665, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-003', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '3. Dễ và khó khi theo đuổi sở thíchいろいろな 趣味の 人に 聞きました。どの 人ですか。どんな 意見ですか。Người phỏng vấn đã hỏi những người có các sở thích khác nhau. Đó là người nào? Họ có ý kiến gì?', 'NGUON', NULL),
(3015509, 'CONTENT_ITEM', 3003666, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-003-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/c/07C-7.mp3', '07C-7.mp3', 'NGUON', NULL),
(3015510, 'CONTENT_ITEM', 3003667, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-004', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '4. Nghe dự báo thời tiết天気予報を 聞いて、どうしますか。Sau khi nghe dự báo thời tiết, bạn sẽ làm gì?', 'NGUON', NULL),
(3015511, 'CONTENT_ITEM', 3003668, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-004-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/c/08C-8.mp3', '08C-8.mp3', 'NGUON', NULL),
(3015512, 'CONTENT_ITEM', 3003669, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-005', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '5. Hóa trang cho vai diễn俳優の 原恵子さんは メークアップアーチストに 頼みました。どの 顔に なりましたか。Diễn viên Hara Keiko nhờ chuyên viên trang điểm hóa trang cho mình. Khuôn mặt cô ấy sau khi hóa trang là khuôn mặt nào?', 'NGUON', NULL),
(3015513, 'CONTENT_ITEM', 3003670, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-005-A01', 'https://www.vnjpclub.com/Audio/minnaln/minna2/c/09C-9.mp3', '09C-9.mp3', 'NGUON', NULL),
(3015514, 'CONTENT_ITEM', 3003671, 'VNJPCLUB', 'MINNA-SO-CAP-2-N4-L204-LIS-006', 'https://www.vnjpclub.com/minna-no-nihongo/bai-44-luyen-nghe.html', '6. Kế hoạch cuối tuần小山さんの 家族は 週末に 何を しますか。Gia đình bạn Koyama sẽ làm gì vào cuối tuần?', 'NGUON', NULL),
